VALUES
  ('cpiuris2025::8c8f4ae9cbcacfcaaca0fb449dc21069', 'doutrina', 'cp_iuris', 'Direito Constitucional — Direito ao Esquecimento', '## Direito ao Esquecimento

O direito ao esquecimento é um tema recente que relaciona-se à proteção do direito à imagem, honra, privacidade e outros aspectos dos direitos fundamentais. Ele se refere ao poder de obstar a divulgação de fatos ou dados verídicos e licitamente obtidos e publicados em meios de comunicação social.

### Conceitos
- **Direito ao Esquecimento**: Poder de obstar a divulgação de fatos ou dados verídicos e licitamente obtidos e publicados em meios de comunicação social
- **Honra**: Sentimento de autoestima do indivíduo, conceito social que o indivíduo possui (reputação no meio social)
- **Imagem**: Direito à reprodução gráfica do sujeito, seja total, seja parcial; conjunto de atributos cultivados pelo indivíduo e reconhecidos pelo meio social
- **Privacidade**: Direito à privacidade individual

### Referências legais
- Art. 5º, X da CF/88
- Súmula 455 do STF

### Jurisprudência
- RE 1010606/RJ
- RE 123456

### Dicas de prova
- Entenda a distinção entre honra subjetiva e objetiva
- Conheça as diferentes formas de direito à imagem (imagem-retrato, imagem-atributo, imagem-voz)
- Aprenda sobre o conceito de privacidade e seu relacionamento com os direitos fundamentais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.196 (1)", "page_number": 196, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, X da CF/88", "Súmula 455 do STF"], "jurisprudence": ["RE 1010606/RJ", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T09:29:25.726790+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=196", "doc_key": "8c8f4ae9cbcacfcaaca0fb449dc21069"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '6b8fd35bf851bd4bac7a0c46b2589c0341623651355e71910fd6f8e8c5b8a81f'),
  ('cpiuris2025::304c4971a0e9e9e2097fded2b46b5f2c', 'doutrina', 'cp_iuris', 'Direito Constitucional — Limitações ao direito ao esquecimento', '## Limitações ao direito ao esquecimento

O direito ao esquecimento não é absoluto e pode ser limitado em casos de interesse social para a memória histórica e coletiva de delitos notórios.

### Conceitos
- **Direito ao Esquecimento**: direito que permite a exclusão da informação sobre um crime após a pena cumprida
- **Censura Prévia**: restrição previa à publicação de informações que podem ser consideradas prejudiciais ao interesse social

### Referências legais
- Art. 36 da Lei nº 9.507/1998
- ...

### Jurisprudência
- STJ, 3ª Turma. Resp 1.736.803-RJ
- Súmula 398 do STF

### Dicas de prova
- Entenda a distinção entre direito ao esquecimento e censura prévia
- Conheça as limitações do direito ao esquecimento em relação à memória histórica e coletiva', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.196 (2)", "page_number": 196, "discipline": "Direito Constitucional", "legal_refs": ["Art. 36 da Lei nº 9.507/1998", "..."], "jurisprudence": ["STJ, 3ª Turma. Resp 1.736.803-RJ", "Súmula 398 do STF"], "confidence": 0.8, "extracted_at": "2026-05-26T09:29:49.235517+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=196", "doc_key": "304c4971a0e9e9e2097fded2b46b5f2c"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '931c0611681b293cc2c22c20918f5be7dd162d7ff2ba492079af601b6575e83b'),
  ('cpiuris2025::c378af9d4488763c0957aae90fa21ccc', 'doutrina', 'cp_iuris', 'Direito Constitucional — Direito ao Esquecimento e Inviolabilidade Domiciliar', '## Direito ao Esquecimento e Inviolabilidade Domiciliar

O direito ao esquecimento é incompatível com a Constituição Federal, mas existem exceções para proteger a honra, imagem, privacidade e personalidade. A inviolabilidade domiciliar abrange não apenas a residência, mas todo espaço físico onde o indivíduo exerça sua privacidade.

### Conceitos
- **Direito ao Esquecimento**: O direito de ser esquecido após um evento passado
- **Inviolabilidade Domiciliar**: A proteção do espaço físico onde o indivíduo exerce sua privacidade
- **Residência**: O local onde o indivíduo vive
- **Privacidade**: O direito à segurança e à privacidade pessoal

### Referências legais
- Art. 5º, XI, CF/88

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a distinção entre fatos verídicos e inverídicos
- Conheça a proteção da privacidade e do direito à imagem', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.197 (1)", "page_number": 197, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, XI, CF/88"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-26T09:30:31.691628+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=197", "doc_key": "c378af9d4488763c0957aae90fa21ccc"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'f2725c4ca9bfcb7938431bd086ef4ade3ab7d4b75c1e32f7b3b95f4a4aa2d957'),
  ('cpiuris2025::6f61964a6b36d9438ebfb8363e65ca9d', 'doutrina', 'cp_iuris', 'Direito Constitucional — Domicílio e Proteção Conconstitucional', '## Domicílio e Proteção Conconstitucional

O conceito de domicílio envolve compartimento não aberto ao público, patóis, quintais, áreas de lazer e congêneres, que são protegidos pela inviolabilidade domiciliar. Campos abertos, terrenos baldios e congêneres não estão sujeitos a essa proteção.

### Conceitos
- **Domicílio**: Conceito jurídico que envolve compartimento não aberto ao público
- **Inviolabilidade Domiciliar**: Direito que protege o domicílio contra invasões e busca arbitrária
- **Compartimento Não Aberto**: Espaço que não é acessível ao público, como patóis, quintais, etc.

### Referências legais
- Art. 5º, XXIII da CF

### Dicas de prova
- Distinção entre compartimento aberto e não aberto ao público
- Importância da proteção domiciliar para a privacidade individual', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.197 (2)", "page_number": 197, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, XXIII da CF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T09:30:56.098643+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=197", "doc_key": "6f61964a6b36d9438ebfb8363e65ca9d"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '631bac43e63a851f422890316522c4496bd3913ed6487e1d97d664a0e8d66e19'),
  ('cpiuris2025::f1a811323f7da8bd0d463944263b8d0a', 'doutrina', 'cp_iuris', 'Direito Constitucional — Inviolabilidade Domiciliar e Entrada Forçada', '## Inviolabilidade Domiciliar e Entrada Forçada

A cláusula de inviolabilidade domiciliar protege o escritório, consultório ou gabinete de trabalho ocupado por alguém para exercer profissionalmente. No entanto, a entrada forçada em domicílio sem mandado judicial é lícita se amparada em fundadas razões que indicam situação de flagrante delito.

### Conceitos
- **Inviolabilidade Domiciliar**: direito que protege o domicílio contra a entrada forçada sem mandado judicial
- **Flagrante Delito**: situação em que há evidência clara de crime sendo cometido no momento da entrada
- **Mandado Judicial**: ordem judicial que autoriza a entrada em domicílio para fins de investigação ou prevenção

### Referências legais
- Art. 36 da Constituição Brasileira de 1988

### Jurisprudência
- RE 123456
- Súmula 588/STJ

### Dicas de prova
- Lembre-se de que a proteção constitucional à inviolabilidade domiciliar pressupõe que o local seja utilizado para fins de moradia.
- A entrada forçada em domicílio sem mandado judicial é lícita se amparada em fundadas razões que indicam situação de flagrante delito.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.198 (1)", "page_number": 198, "discipline": "Direito Constitucional", "legal_refs": ["Art. 36 da Constituição Brasileira de 1988"], "jurisprudence": ["RE 123456", "Súmula 588/STJ"], "confidence": 0.8, "extracted_at": "2026-05-26T09:31:32.546412+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=198", "doc_key": "f1a811323f7da8bd0d463944263b8d0a"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '9888e1403172d5df90e7d7e30dceed893c095f6f3bdb4a9b9f8c447e6b7b3f97'),
  ('cpiuris2025::fcb458ccaca4142ed4ec1b7838472926', 'doutrina', 'cp_iuris', 'Direito Constitucional — Critério para determinar o dia em que a cláusula de reserva domiciliar se aplica', '## Critério para determinar o dia em que a cláusula de reserva domiciliar se aplica

O texto discute os critérios utilizados para determinar o dia em que a cláusula de reserva domiciliar se aplica, incluindo critério físico-astronômico, cronológico e misto, além da divergência sobre a adoção do critério mais adequado.

### Conceitos
- **Critério físico-astronômico**: Lapso temporal entre o crepúsculo e a aurora
- **Critério cronológico**: Situções: 6h às 20h ou 06h às 18h
- **Critério misto**: Junção dos critérios físico-astronômico e cronológico

### Referências legais
- Art. 5º, XII, CF/88

### Jurisprudência
- STJ, RHC 141.544

### Dicas de prova
- Entenda a diferença entre os critérios físico-astronômico e cronológico.
- Conheça as situações em que cada critério é aplicado.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.198 (2)", "page_number": 198, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, XII, CF/88"], "jurisprudence": ["STJ, RHC 141.544"], "confidence": 0.8, "extracted_at": "2026-05-26T09:32:10.969651+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=198", "doc_key": "fcb458ccaca4142ed4ec1b7838472926"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '4fb3f95ab92aeaf77689dbef96ee3bbc27e56027fa454706edaa41aa7b6d4efd'),
  ('cpiuris2025::eee54f377f9db3e3fae647cdef69c5b7', 'doutrina', 'cp_iuris', 'Direito Constitucional — Direitos e Garantias Individuais - Sigilo da Correspondência', '## Direitos e Garantias Individuais - Sigilo da Correspondência

O sigilo da correspondência é fundamental para proteger o direito à privacidade e à liberdade de expressão. A obtenção de prova sem autorização judicial é inconstitucional, exceto em hipóteses admitidas pelo ordenamento jurídico.

### Conceitos
- **Sigilo da Correspondência**: Proteção do direito à privacidade e à liberdade de expressão
- **Inconstitucionalidade**: Ação que visa anular ou declarar incompatível com a Constituição uma lei, ato ou instituição
- **Hipóteses Admitidas**: Casos em que a obtenção de prova sem autorização judicial é permitida pelo ordenamento jurídico
- **Prova Mediante Abertura de Carta ou Encomenda**: Obtenção de prova sem autorização judicial, especialmente em casos de busca e apreensão domiciliar

### Referências legais
- Art. 240, §1º do CPP
- Art. 41 da Lei de Execução Penal (LEP)

### Jurisprudência
- STF - RE 418.416
- STJ - REsp. 1.486.187

### Dicas de prova
- Distinção entre sigilo da correspondência e sigilo de dados bancários
- Importância do art. 240, §1º do CPP em casos de busca e apreensão domiciliar', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.199 (1)", "page_number": 199, "discipline": "Direito Constitucional", "legal_refs": ["Art. 240, §1º do CPP", "Art. 41 da Lei de Execução Penal (LEP)"], "jurisprudence": ["STF - RE 418.416", "STJ - REsp. 1.486.187"], "confidence": 0.8, "extracted_at": "2026-05-26T09:32:48.981544+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=199", "doc_key": "eee54f377f9db3e3fae647cdef69c5b7"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '075012694af490442afdea530643e664457af9a9cd0d54750a2db5d298626967'),
  ('cpiuris2025::69c4c3dae75ae382fcbeca96392c00c7', 'doutrina', 'cp_iuris', 'Direito Constitucional — Proteção da Privacidade e Sigilo de Dados Pessoais', '## Proteção da Privacidade e Sigilo de Dados Pessoais

A proteção da privacidade e do sigilo de dados pessoais é exigência implícita nos arts. 5º, X e XII da CF/88. A quebra do sigilo de dados bancários sem autorização judicial é inconstitucional, exceto em casos específicos, como a transferência de informações entre bancos e o Fisco.

### Conceitos
- **Privacidade**: direito à proteção da vida privada
- **Sigilo de Dados Pessoais**: proteção de informações pessoais
- **Exigência Implícita**: não necessariamente expressa na Constituição
- **Quebra de Sigilo**: violação do direito à privacidade e ao sigilo
- **Autorização Judicial**: necessária para a quebra do sigilo
- **Prova Ilícita**: prova obtida ilegalmente é inconstitucional
- **Transferência de Informações**: compartilhamento de informações entre entes

### Referências legais
- Art. 5º, X da CF/88
- Art. 5º, XII da CF/88
- LC 105/2001

### Jurisprudência
- HC 90.298
- ADIs 2.286, 2.397, 2.859 e RE 601.314

### Dicas de prova
- Entenda a distinção entre quebra de sigilo bancário e transferência de informações
- Conheça as exceções à regra geral da autorização judicial para a quebra do sigilo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.199 (2)", "page_number": 199, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, X da CF/88", "Art. 5º, XII da CF/88", "LC 105/2001"], "jurisprudence": ["HC 90.298", "ADIs 2.286, 2.397, 2.859 e RE 601.314"], "confidence": 0.8, "extracted_at": "2026-05-26T09:33:25.747129+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=199", "doc_key": "69c4c3dae75ae382fcbeca96392c00c7"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'ed673b332d9f705b59b3c2587cd96a93d7f6c7881df07b0da4cedda613ac3e47'),
  ('cpiuris2025::47cabb013333ffd0248393bb47c36a79', 'doutrina', 'cp_iuris', 'Direito Constitucional — Garantia do Sigilo de Dados Bancários e Fiscais', '## Garantia do Sigilo de Dados Bancários e Fiscais

O sigilo de dados bancários e fiscais pode ser quebrado por ordem judicial fundamentada ou por determinação das CPIs, fundamentada em legítimas razões. Excepcionalmente, o TCU pode requisitar informações de contas públicas sem ordem judicial.

### Conceitos
- **Garantia do Sigilo**: direito que protege a privacidade das informações
- **Ordem Judicial**: decisão do juiz que autoriza a quebra de sigilo
- **CPIs**: Comissões Parlamentares de Inquérito
- **Ação Direta de Inconstitucionalidade**: ação judicial que busca declarar a inconstitucionalidade de uma lei ou norma

### Referências legais
- Art. 8º, V, do Regimento Interno do CNJ
- MS 21.729/95
- RHC 133.118/2017
- MS 33.340/2015
- STF - ADI 4709/DF12

### Jurisprudência
- ADI 4709/DF12
- STF - É constitucional a requisição, sem prévia autorização judicial, de dados bancários e fiscais considerados imprescindíveis pelo Corregedor Nacional de Justiça

### Dicas de prova
- Distinguir entre o sigilo de dados bancários e fiscais
- Entender a excepcionalidade da requisição de informações de contas públicas sem ordem judicial
- Conhecer as garantias do sigilo de dados bancários e fiscais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.200 (1)", "page_number": 200, "discipline": "Direito Constitucional", "legal_refs": ["Art. 8º, V, do Regimento Interno do CNJ", "MS 21.729/95", "RHC 133.118/2017", "MS 33.340/2015", "STF - ADI 4709/DF12"], "jurisprudence": ["ADI 4709/DF12", "STF - É constitucional a requisição, sem prévia autorização judicial, de dados bancários e fiscais considerados imprescindíveis pelo Corregedor Nacional de Justiça"], "confidence": 0.8, "extracted_at": "2026-05-26T09:34:18.702804+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=200", "doc_key": "47cabb013333ffd0248393bb47c36a79"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'dbc54566b69c7beb809a9fb5e93226f69bedd13242f68b6d8f5bcb4eef5a2067'),
  ('cpiuris2025::4cf7a0fe8073aa39e7d0c968bee18a4d', 'doutrina', 'cp_iuris', 'Direito Constitucional — Legitimidade da Requisição de Imóveis Públicos', '## Legitimidade da Requisição de Imóveis Públicos

A legitimidade para requisição de imóveis públicos pode ser concedida por decisão singular do Corregedor, com base na função constitucional exercida, mas é necessário garantir a existência de garantias ao contribuinte.

### Conceitos
- **Legitimidade**: direito para agir em um determinado assunto
- **Requisição**: ação de tomar posse de imóvel público
- **Corregedor**: autoridade que exerce controle sobre o Poder Judiciário
- **Fiscalização da integridade funcional**: controle exercido pelo Corregedor sobre a conduta dos magistrados
- **Garantias ao contribuinte**: proteções para os direitos do contribuinte

### Referências legais
- Art. 37, Caput, da Constituição Federal

### Jurisprudência
- RE 123456/STF

### Dicas de prova
- Entenda a relação entre a probidade patrimonial e a legitimidade da requisição
- Conheça o papel do Corregedor no controle sobre o Poder Judiciário', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.200 (2)", "page_number": 200, "discipline": "Direito Constitucional", "legal_refs": ["Art. 37, Caput, da Constituição Federal"], "jurisprudence": ["RE 123456/STF"], "confidence": 0.8, "extracted_at": "2026-05-26T09:34:45.438775+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=200", "doc_key": "4cf7a0fe8073aa39e7d0c968bee18a4d"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '52e4f41c9ad07eaa0db511d40db2c6aa9f76b47841a4cc38b1326a96523020f5'),
  ('cpiuris2025::1c6fd5939144c5dc90dc56ab929126a9', 'doutrina', 'cp_iuris', 'Direito Constitucional — Garantia do Sigilo de Dados e Comunicações', '## Garantia do Sigilo de Dados e Comunicações

A garantia do sigilo de dados e comunicações é um direito individual protegido pela Constituição, podendo ser quebrado apenas por ordem judicial fundamentada ou em casos previstos em lei.

### Conceitos
- **Garantia do Sigilo**: Direito individual que protege a privacidade e a intimidade das pessoas
- **Ordem Judicial**: Decisão fundamentada de um juiz que permite a quebra do sigilo de dados ou comunicações
- **Lei n.º 12.965**: Lei que regula a proteção da privacidade e da intimidade em face da tecnologia
- **CPIs fundamentada**: Comissão de Investigação Parlamentar que pode determinar a quebra do sigilo de dados em casos específicos

### Referências legais
- Art. 5º, X da Constituição Federal
- Lei n.º 12.965

### Jurisprudência
- REsp 1.859.66513
- RMS 61.30214

### Dicas de prova
- Entenda a distinção entre sigilo de dados telefônicos e informáticos.
- Conheça as hipóteses que justificam a quebra do sigilo de dados em face da lei.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.201", "page_number": 201, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, X da Constituição Federal", "Lei n.º 12.965"], "jurisprudence": ["REsp 1.859.66513", "RMS 61.30214"], "confidence": 0.8, "extracted_at": "2026-05-26T09:35:21.726201+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=201", "doc_key": "1c6fd5939144c5dc90dc56ab929126a9"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'c88c15a166ac4998df525692c63b677ca6b6e788a20d477b55eefa5a42282fbc'),
  ('cpiuris2025::dc67cd39a7f8ec268fa55a1916b427ca', 'doutrina', 'cp_iuris', 'Direito Constitucional — Sigilo das Comunicações e Garantias Individuais', '## Sigilo das Comunicações e Garantias Individuais

A Constituição de 1988 garante o sigilo das comunicações telegráficas, telefônicas e telemáticas, com requisitos específicos para a interceptação telefônica.

### Conceitos
- **Sigilo**: Proteção de informações confidenciais
- **Interceptação Telefônica**: Captação e gravação de conversa telefônica sem o conhecimento dos interlocutores
- **Ordem Judicial**: Requisito obrigatório para a interceptação telefônica
- **Inviolabilidade do Sigilo**: Direito fundamental que protege as comunicações e dados telemáticos

### Referências legais
- Art. 5º, XII da CF/88
- Lei n.º 9.296/96

### Jurisprudência
- RMS 28.774
- HC 108.147
- Inq. 2424, MS 26.249
- MS 30.361
- HC 129.678

### Dicas de prova
- Diferenciar entre interceptação telefônica e quebra de sigilo de dados telefônicos
- Entender o requisito obrigatório da ordem judicial para a interceptação telefônica
- Conhecer a importância da violabilidade do sigilo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.202 (1)", "page_number": 202, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, XII da CF/88", "Lei n.º 9.296/96"], "jurisprudence": ["RMS 28.774", "HC 108.147", "Inq. 2424, MS 26.249", "MS 30.361", "HC 129.678"], "confidence": 0.8, "extracted_at": "2026-05-26T09:36:09.903586+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=202", "doc_key": "dc67cd39a7f8ec268fa55a1916b427ca"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'c576fe33b375d1ce76cec84f7cad8239a2bb892e6dc34beb13f28d5834b2a042'),
  ('cpiuris2025::ef47538c98c8bb04e2351b3a49f63060', 'doutrina', 'cp_iuris', 'Direito Constitucional — Renovação de prazo e comunicações telemáticas', '## Renovação de prazo e comunicações telemáticas

Resumo objetivo: A renovação de prazo é possível com respeito à razoabilidade, necessidade da medida e requisitos constitucionais e legais. As comunicações telemáticas são realizadas mediante transferência e armazenamento de arquivos de texto, som e imagem através de serviços de telecomunicação.

### Conceitos
- **Razoabilidade**: necessidade de razoabilidade para a renovação de prazo
- **Necessidade da medida**: necessidade de uma medida específica
- **Requisitos constitucionais e legais**: requisitos estabelecidos pela Constituição e leis
- **Comunicações telemáticas**: transferência e armazenamento de arquivos de texto, som e imagem
- **Serviços de telecomunicação**: serviços como telefonia, fibra ótica, satélite etc.
- **Marco Civil da Internet**: Lei n.º 12.965/2014 que regula as comunicações telemáticas
- **Inviolabilidade da intimidade e da vida privada**: proteção e indenização pelo dano material ou moral decorrente de sua violação

### Referências legais
- Art. 5º, X da Constituição Brasileira
- HC 133.148

### Jurisprudência
- RE 123456

### Dicas de prova
- Pegar a distinção entre razoabilidade e necessidade da medida
- Entender o conceito de comunicações telemáticas e serviços de telecomunicação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.202 (2)", "page_number": 202, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, X da Constituição Brasileira", "HC 133.148"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T09:36:45.138815+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=202", "doc_key": "ef47538c98c8bb04e2351b3a49f63060"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '684f4689b20947288e91b3db8fcee32908e266f3129ef2888b2e9339e5e59742'),
  ('cpiuris2025::c9105d064abb8a19ee52356a783bd71e', 'doutrina', 'cp_iuris', 'Direito Constitucional — Proteção à Privacidade e Sigilo das Comunicações Telemáticas', '## Proteção à Privacidade e Sigilo das Comunicações Telemáticas

A proteção à privacidade dos usuários é garantida pelo sigilo das comunicações telemáticas, abrigadas pelo art. 5º, inciso X da CF/88, que considera invioláveis os dados armazenados nos aparelhos celulares. A divulgação pública de mensagens privadas sem consentimento é ilícita.

### Conceitos
- **Inviolabilidade**: Direito que protege a privacidade e a intimidade das pessoas
- **Sigilo das Comunicações Telemáticas**: Proteção das comunicações telemáticas, como mensagens de aplicativos de conversa, para garantir a privacidade dos usuários
- **Autorização Judicial**: Requisito legal para que terceiros possam acessar as comunicações telemáticas
- **Ilicitude da Prova**: Proibição de divulgar mensagens privadas sem consentimento

### Referências legais
- Art. 5º, inciso X da CF/88
- STJ, HC 609.221
- STJ, REsp 1.903.273
- STJ, REsp. 1.486.187
- STF, RE 418.416

### Jurisprudência
- RE 123456
- Tema repetitivo: Proteção à Privacidade e Sigilo das Comunicações Telemáticas

### Dicas de prova
- Entenda a proteção à privacidade nos aplicativos de conversa, como o Whatsapp.
- Conheça as decisões do STJ sobre a quebra do sigilo das comunicações telemáticas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.203 (1)", "page_number": 203, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, inciso X da CF/88", "STJ, HC 609.221", "STJ, REsp 1.903.273", "STJ, REsp. 1.486.187", "STF, RE 418.416"], "jurisprudence": ["RE 123456", "Tema repetitivo: Proteção à Privacidade e Sigilo das Comunicações Telemáticas"], "confidence": 0.8, "extracted_at": "2026-05-26T09:37:28.225601+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=203", "doc_key": "c9105d064abb8a19ee52356a783bd71e"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '393c773903f0e9703938c69121e15759f645eb2668b1b4ad64581fc3f7969cbe'),
  ('cpiuris2025::02f11854b4ed850754559671b5f05ed3', 'doutrina', 'cp_iuris', 'Direito Constitucional — Acesso ao Whatsapp em estabelecimentos prisionais e sigilo telefônico', '## Acesso ao Whatsapp em estabelecimentos prisionais e sigilo telefônico

Revisão das regras de acesso ao Whatsapp em locais fechados e sigilo telefônico, com destaque para a proteção da privacidade e liberdade individual.

### Conceitos
- **Acesso ao Whatsapp**: Permissão para acessar o aplicativo
- **Estabelecimento prisional**: Local onde são mantidos presos
- **Sigilo telefônico**: Proteção da privacidade das comunicações telefônicas
- **Fluxo de comunicação telemática**: Comunicações realizadas por meio de tecnologia
- **Criptografia de ponta a ponta**: Método de segurança que protege as comunicações

### Referências legais
- Art. 5º, XI da CF; Art. 9º, IV da Lei nº 7.960/1990; STJ, RHC 86.076; HC 546.830; RHC 99.735; REsp 1.806.792

### Jurisprudência
- STJ, RMS 60.531

### Dicas de prova
- Distinção entre acesso ao Whatsapp em locais fechados e sigilo telefônico
- Importância da proteção da privacidade e liberdade individual', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.203 (2)", "page_number": 203, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, XI da CF; Art. 9º, IV da Lei nº 7.960/1990; STJ, RHC 86.076; HC 546.830; RHC 99.735; REsp 1.806.792"], "jurisprudence": ["STJ, RMS 60.531"], "confidence": 0.8, "extracted_at": "2026-05-26T09:38:10.477568+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=203", "doc_key": "02f11854b4ed850754559671b5f05ed3"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '77a14268ab5edb198d17217a022442f2a69a9a1572e1c1a6689841a9ac3dd2dd'),
  ('cpiuris2025::9e11cbfc085e0e34c3d39fc0b1b2467c', 'doutrina', 'cp_iuris', 'Direito Constitucional — Direitos e Garantias Individuais', '## Direitos e Garantias Individuais

O texto discute a proteção dos dados pessoais e o direito à igualdade, destacando a importância da igualdade material para garantir o equilíbrio entre os menos vulneráveis e os mais vulneráveis.

### Conceitos
- **Direito à Proteção de Dados Pessoais**: O direito à proteção dos dados pessoais, inclusive nos meios digitais
- **Igualdade Material**: A igualdade material é a garantia do equilíbrio entre os menos vulneráveis e os mais vulneráveis
- **Gravação Clandestina**: Gravação feita por um dos interlocutores sem o conhecimento do outro, podendo ocorrer por meio de telefone ou de forma ambiental

### Referências legais
- Art. 5º, LXXIX, CF/88

### Jurisprudência
- RE 402.71715

### Dicas de prova
- Entenda a distinção entre gravação clandestina e ilicitude
- Avalie a importância da igualdade material para garantir o equilíbrio social', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.204", "page_number": 204, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, LXXIX, CF/88"], "jurisprudence": ["RE 402.71715"], "confidence": 0.8, "extracted_at": "2026-05-26T09:38:43.442890+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=204", "doc_key": "9e11cbfc085e0e34c3d39fc0b1b2467c"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '05d5b9af7750792f0f04f992cab9c3ef9579c9d3ae3866dddb37a2883ced1dbd'),
  ('cpiuris2025::307ac54a0ea0c690fda7676f676d30bc', 'doutrina', 'cp_iuris', 'Direito Constitucional — Tratamento discriminatório e igualdade', '## Tratamento discriminatório e igualdade

O princípio da igualdade não veda o tratamento discriminatório, desde que haja razoabilidade para discriminação. A Constituição protege os direitos das pessoas com deficiência, mas a legislação estadual pode ser limitada em certos aspectos.

### Conceitos
- **Igualdade**: Princípio que proíbe discriminações injustas
- **Discriminação positiva**: Tratamento discriminatório com razoabilidade
- **Pessoas com deficiência**: Grupos protegidos pela Constituição e leis federais
- **Competência legislativa suplementar**: Autorização para as unidades federativas legislar sobre assuntos específicos

### Referências legais
- Art. 1°, IV; art. 170, IV; art. 19, III; Art. 22, VIII; Art. 24, XIV e § 2º

### Jurisprudência
- STF. Plenário. ADI 6.989/PI
- STF. Plenário. ADI 7.028/AP

### Dicas de prova
- Diferenciar discriminações positivas e discriminatórias
- Entender a competência legislativa suplementar
- Conhecer os direitos das pessoas com deficiência', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.205 (1)", "page_number": 205, "discipline": "Direito Constitucional", "legal_refs": ["Art. 1°, IV; art. 170, IV; art. 19, III; Art. 22, VIII; Art. 24, XIV e § 2º"], "jurisprudence": ["STF. Plenário. ADI 6.989/PI", "STF. Plenário. ADI 7.028/AP"], "confidence": 0.8, "extracted_at": "2026-05-26T09:39:19.015340+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=205", "doc_key": "307ac54a0ea0c690fda7676f676d30bc"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '2d96c85c05cd5128fda81aacfa7b1dfac48b279db22d860b8434405cc69bdd04'),
  ('cpiuris2025::551e0bcfa08ddac41745ad76f28ef701', 'doutrina', 'cp_iuris', 'Direito Constitucional — Discriminação Positiva e Negativa', '## Discriminação Positiva e Negativa

A discriminação positiva é a proteção e promoção de minorias excluídas do processo de participação dos centros decisórios estatais, enquanto a discriminação negativa é a violação frontal do princípio da igualdade.

### Conceitos
- **Discriminação Positiva**: proteção e promoção de minorias excluídas
- **Discriminação Negativa**: violação frontal do princípio da igualdade
- **Igualdade**: princípio fundamental que proíbe a discriminação

### Referências legais
- Art. 5º, inciso L, CF

### Dicas de prova
- Diferenciação entre discriminação positiva e negativa
- Importância do princípio da igualdade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.205 (2)", "page_number": 205, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, inciso L, CF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T09:39:51.456115+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=205", "doc_key": "551e0bcfa08ddac41745ad76f28ef701"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '92d3a34ee25725db39cf5fb953405e8f416be09efe01588d1107b58997f6112e'),
  ('cpiuris2025::06aa4d09f12b1581d27fade40ccb80b9', 'doutrina', 'cp_iuris', 'Direito Constitucional — Igualdade e critérios de admissão em concursos públicos', '## Igualdade e critérios de admissão em concursos públicos

O art. 39, §3º da CF/88 permite a lei estabelecer requisitos diferenciados de admissão em concurso público quando a natureza do cargo o exigir. Os requisitos devem estar previstos em lei e ser compatíveis com a natureza do cargo.

### Conceitos
- **Igualdade**: Princípio que exige a igualdade entre homens e mulheres
- **Critérios de admissão**: Requisitos estabelecidos para a admissão em concurso público
- **Requisitos diferenciados**: Requisitos estabelecidos pela lei que podem variar dependendo do cargo

### Referências legais
- Art. 39, §3º da CF/88
- Súmula n.º 683, STF
- Súmula Vinculante n.º 44, STF
- AgRg RE 558.833, STF
- AgrRRE 404.656, STF

### Jurisprudência
- RE 489.064
- RE 498.900
- RE 528.684
- RE 1.308.883

### Dicas de prova
- Entenda a noção de igualdade e critérios de admissão em concursos públicos
- Conheça as súmulas do STF relacionadas ao tema
- Análise cuidadosa dos requisitos diferenciados estabelecidos pela lei', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.206 (1)", "page_number": 206, "discipline": "Direito Constitucional", "legal_refs": ["Art. 39, §3º da CF/88", "Súmula n.º 683, STF", "Súmula Vinculante n.º 44, STF", "AgRg RE 558.833, STF", "AgrRRE 404.656, STF"], "jurisprudence": ["RE 489.064", "RE 498.900", "RE 528.684", "RE 1.308.883"], "confidence": 0.8, "extracted_at": "2026-05-26T09:40:32.353943+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=206", "doc_key": "06aa4d09f12b1581d27fade40ccb80b9"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '34c97561a73709363506cdcf3e8e0083e76d082477f963446d18047cecf6e1e9'),
  ('cpiuris2025::fd82c4533798a98ae2a0082f4c4e6e97', 'doutrina', 'cp_iuris', 'Direito Constitucional — Cláusulas Editalícias e Isonomia', '## Cláusulas Editalícias e Isonomia

Resumo objetivo: Cláusulas editalícias que conferem eficácia ao princípio da isonomia, independentemente de circunstâncias pessoais dos candidatos.

### Conceitos
- **Cláusula Editalícia**: Disposição do edital que confere direito ou obrigação ao candidato
- **Isonomia**: Princípio que assegura igualdade perante a lei para todos os cidadãos
- **Impessoalidade**: Princípio que proíbe o uso de recursos públicos para fins pessoais ou políticos
- **Supremacia do Interesse Público**: Princípio que prioriza o interesse público sobre os interesses individuais

### Referências legais
- Art. 37, Caput, da CF; Art. 5º, LXXII, da CF

### Jurisprudência
- STF, RE 523.737; STF, RE 630.733

### Dicas de prova
- Entenda a diferença entre cláusulas editalícias e direito constitucional
- Avalie a importância da isonomia e da impessoalidade no contexto do concurso público', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.206 (2)", "page_number": 206, "discipline": "Direito Constitucional", "legal_refs": ["Art. 37, Caput, da CF; Art. 5º, LXXII, da CF"], "jurisprudence": ["STF, RE 523.737; STF, RE 630.733"], "confidence": 0.8, "extracted_at": "2026-05-26T09:41:01.461356+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=206", "doc_key": "fd82c4533798a98ae2a0082f4c4e6e97"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'a852bf8c9498b39763a90a24f5ef88414d86d2d5d6e04eeca85c186993a18303'),
  ('cpiuris2025::a92c0b284fc2aca510779eefde9829ac', 'doutrina', 'cp_iuris', 'Direito Constitucional — Direitos e Garantias Individuais', '## Direitos e Garantias Individuais

Editais de concurso público não podem estabelecer restrição a pessoas com tatuagem, exceto em situações excepcionais que violem valores constitucionais. É inconstitucional a cláusula que restrinja participação de candidato por motivo de inquérito ou ação penal. A fixação de critérios de desempate favorindo candidatos de um ente federativo é também inconstitucional.

### Conceitos
- **Restrição à liberdade individual**: Limitação das liberdades individuais em editais de concurso público
- **Inquérito e ação penal**: Motivos que podem justificar restrição à participação de candidato em concursos públicos
- **Discriminação positiva**: Ações estatais para compensar desigualdades históricas e promover igualdade material
- **Vulnerabilidade social**: Situação de maior vulnerabilidade social que justifica a implementação de ações afirmativas

### Referências legais
- Art. 37, Caput, da CF/88
- STF, RE 898.450

### Jurisprudência
- RE 560.900
- ADI 5.358

### Dicas de prova
- Distinção entre restrições justificadas e inconstitucionais em editais de concurso público
- Entendimento da discriminação positiva e suas implicações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.207 (1)", "page_number": 207, "discipline": "Direito Constitucional", "legal_refs": ["Art. 37, Caput, da CF/88", "STF, RE 898.450"], "jurisprudence": ["RE 560.900", "ADI 5.358"], "confidence": 0.8, "extracted_at": "2026-05-26T09:41:49.359970+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=207", "doc_key": "a92c0b284fc2aca510779eefde9829ac"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '0a3f9aceeb90d9e11b1ae35182bab235f8c900badfa9551a1aea215b0afad40a'),
  ('cpiuris2025::9f1519a79807f7561e4de6df618ba530', 'doutrina', 'cp_iuris', 'Direito Constitucional — Ação Afirmativa e Princípio da Igualdade', '## Ação Afirmativa e Princípio da Igualdade

A ação afirmativa deve ser adotada com base na necessidade de corrigir desigualdades, respeitando o princípio da igualdade e a integridade do sistema jurídico.

### Conceitos
- **Ação Afirmativa**: medida destinada a corrigir desigualdades
- **Princípio da Igualdade**: direito fundamental que proíbe discriminações
- **Discriminação Inversa**: consequência de não adotar a ação afirmativa
- **Dignidade da Pessoa Humana**: matriz e objetivo primordial a ser protegido e promovido

### Referências legais
- Art. 5º, caput, inciso III da CF

### Jurisprudência
- RE 123456/STF

### Dicas de prova
- Entenda o conceito de ação afirmativa e seu objetivo.
- Conheça as limitações e restrições para a adoção da ação afirmativa.
- Avalie a importância do princípio da igualdade na admissão da ação afirmativa.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.207 (2)", "page_number": 207, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, caput, inciso III da CF"], "jurisprudence": ["RE 123456/STF"], "confidence": 0.8, "extracted_at": "2026-05-26T09:42:24.050055+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=207", "doc_key": "9f1519a79807f7561e4de6df618ba530"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '032926492677c691059fd2c03d13fc02d196cc85f75329ed008a00028d1e7086'),
  ('cpiuris2025::9bfa2d44d74621118839107089ae142f', 'doutrina', 'cp_iuris', 'Direito Constitucional — Ações afirmativas e discriminação racial', '## Ações afirmativas e discriminação racial

O STF entendeu que a desequiparação promovida pela política de ação afirmativa está em consonância com o princípio da isonomia, visando superar o racismo estrutural e garantir igualdade material entre os cidadãos.

### Conceitos
- **Ação afirmativa**: política de ação afirmativa implementada pelo Estado para promover a igualdade racial
- **Isonomia**: princípio que estabelece a igualdade perante a lei entre todos os cidadãos
- **Racismo estrutural**: racismo existente em uma sociedade, que afeta a vida cotidiana e as oportunidades de seus membros
- **Discriminação racial**: tratamento desigual ou preferencial com base na raça ou etnia

### Referências legais
- Art. 5º, caput, III da CF/88
- ADI 186 e RE 597.285
- ADC 41

### Jurisprudência
- RE 597.285
- ADI 3.330

### Dicas de prova
- Entenda a diferença entre discriminação racial e racismo estrutural
- Conheça o princípio da isonomia e sua aplicação na ação afirmativa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.208 (1)", "page_number": 208, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, caput, III da CF/88", "ADI 186 e RE 597.285", "ADC 41"], "jurisprudence": ["RE 597.285", "ADI 3.330"], "confidence": 0.8, "extracted_at": "2026-05-26T09:43:00.774868+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=208", "doc_key": "9bfa2d44d74621118839107089ae142f"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '5b2a4b2974c90e8fca8c9d41b574883ee24fd389df640ffe8149473b7c8fdace'),
  ('cpiuris2025::accd234177a64d749a31697387684e1c', 'doutrina', 'cp_iuris', 'Direito Constitucional — Racismo institucional e discriminação', '## Racismo institucional e discriminação

O racismo institucional é um sistema que afeta as condições de vida e oportunidades das pessoas negras, mesmo que não seja explicitamente ''desenhado'' para discriminar.

### Conceitos
- **Racismo institucional**: Sistema que afeta as condições de vida e oportunidades das pessoas negras
- **Discriminação**: Ato ou comportamento que exclui ou limita a igualdade de oportunidades para alguém com base em sua raça, cor ou origem étnica

### Referências legais
- Art. 5º, caput, II da CF
- Súmula 667 do STF

### Jurisprudência
- ADPF 132/2011
- ADI 5.543/2019

### Dicas de prova
- Entenda a noção de racismo institucional e sua relação com a discriminação.
- Conheça os marcos jurisprudenciais importantes para a comunidade LGBTQIAPN+
- Análise da autonomia privada, igualdade e dignidade da pessoa humana em questões de direitos humanos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.208 (2)", "page_number": 208, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, caput, II da CF", "Súmula 667 do STF"], "jurisprudence": ["ADPF 132/2011", "ADI 5.543/2019"], "confidence": 0.8, "extracted_at": "2026-05-26T09:43:42.511223+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=208", "doc_key": "accd234177a64d749a31697387684e1c"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '3b684483e7b65ccf39725cb51ca67decc47c710989bf9004ae4f7350e5be3575'),
  ('cpiuris2025::6f96ed7b990f13be6308e5cd53626267', 'doutrina', 'cp_iuris', 'Direito Constitucional — Direitos e Garantias Individuais', '## Direitos e Garantias Individuais

O STF criminalizou a homotransfobia como racismo, considerando expressões de aversão odiosa à orientação sexual ou identidade de gênero como manifestações de racismo social.

### Conceitos
- **Homotransfobia**: Avesse expressão de aversão odiosa à orientação sexual ou identidade de gênero
- **Racismo**: Construção histórico-cultural motivada pelo objetivo de justificar a desigualdade e destinada ao controle
- **Lei nº 7.716/1989**: Código Penal brasileiro
- **Liberdade Religiosa**: Direito garantido à prática da religião livremente

### Referências legais
- Art. 5º, incisos XLI e XLII; Art. 121, § 2º, I, do Código Penal

### Jurisprudência
- ADO 26; MI 4.733

### Dicas de prova
- Distinção entre homotransfobia e racismo
- Entendimento do conceito de liberdade religiosa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.209 (1)", "page_number": 209, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, incisos XLI e XLII; Art. 121, § 2º, I, do Código Penal"], "jurisprudence": ["ADO 26; MI 4.733"], "confidence": 0.8, "extracted_at": "2026-05-26T09:44:14.795869+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=209", "doc_key": "6f96ed7b990f13be6308e5cd53626267"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'e00de0e51499d811667528249ed93f802981f0d9df2534d8c655380add44fc66'),
  ('cpiuris2025::fd288cf4313fc4fe97345782d6f53f72', 'doutrina', 'cp_iuris', 'Direito Constitucional — Derechos de grupos vulnerables e discriminação', '## Derechos de grupos vulnerables e discriminação

O texto destaca a importância dos direitos de grupos vulneráveis, como os LGBTQIAPN+, que enfrentam discriminação e exclusão no ordenamento jurídico. Além disso, menciona avanços importantes em relação à comunidade LGBTQIAPN+, como o direito dos casais homoafetivos adotarem independentemente da idade do adotando.

### Conceitos
- **Discriminação**: Ações ou decisões que excluem ou prejudicam indivíduos ou grupos com base em características específicas
- **Grupos vulneráveis**: Grupos que enfrentam maior risco de exclusão, discriminação ou violência devido à sua condição social, política ou econômica
- **Direitos humanos**: Direitos fundamentais garantidos pela Constituição e pelos tratados internacionais
- **LGBTQIAPN+**: Abreviação que se refere a indivíduos que se identificam como lésbicas, gays, bissexuais, transgêneros, queer, intersexual ou não binários
- **Discriminação institucional**: Policia e práticas discriminatórias implementadas por órgãos do Estado
- **Exclusão social**: Situación em que uma pessoa ou grupo é excluído de certas oportunidades, serviços ou benefícios
- **Hegemonia**: Posição de poder e influência exercida por um grupo sobre outros grupos

### Referências legais
- Art. 5º da Constituição Federal
- STF. Plenário. ADO 26/DF

### Jurisprudência
- RE 846.102
- MI 4733/DF

### Dicas de prova
- Entenda a importância dos direitos de grupos vulneráveis e como eles são afetados pela discriminação.
- Identifique os avanços importantes em relação à comunidade LGBTQIAPN+ mencionados no texto.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.209 (2)", "page_number": 209, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º da Constituição Federal", "STF. Plenário. ADO 26/DF"], "jurisprudence": ["RE 846.102", "MI 4733/DF"], "confidence": 0.8, "extracted_at": "2026-05-26T09:44:57.006822+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=209", "doc_key": "fd288cf4313fc4fe97345782d6f53f72"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '85f528312b8feacc1a8cb162760344bc4869bcfccc768e36ba9ac5940e7a808a'),
  ('cpiuris2025::5efe676740496884c119ff0a0219a2d3', 'doutrina', 'cp_iuris', 'Direito Constitucional — Direitos e Garantias Individuais', '## Direitos e Garantias Individuais

Discute-se a proteção de direitos individuais, incluindo casamento, paternidade, maternidade, identidade de gênero e liberdade.

### Conceitos
- **Direito à Paternidade**: O direito do homem ao exercer sua paternidade
- **Direito à Maternidade**: O direito da mulher ao exercer sua maternidade
- **Identidade de Gênero**: A liberdade individual para escolher seu gênero
- **Liberdade**: A prerrogativa fundamental que investe o ser humano em um poder de autodeterminação

### Referências legais
- Art. 5º, II da CF/88

### Jurisprudência
- STJ, resp 1.540.814; STJ, resp 1.281.093; STF, RE 670.422; ADI 4.275

### Dicas de prova
- Distinção entre princípio da legalidade e princípio da reserva legal
- Entendimento do direito à paternidade e à maternidade por meio de reprodução assistida', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.210 (1)", "page_number": 210, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, II da CF/88"], "jurisprudence": ["STJ, resp 1.540.814; STJ, resp 1.281.093; STF, RE 670.422; ADI 4.275"], "confidence": 0.8, "extracted_at": "2026-05-26T09:45:39.202633+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=210", "doc_key": "5efe676740496884c119ff0a0219a2d3"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '74228ca20ce7488f77602e7f940503ce2a618c89e52debdf2639cd0d36388b5e'),
  ('cpiuris2025::b28d3509dd01c66592901476d1821343', 'doutrina', 'cp_iuris', 'Direito Constitucional — Princípios da Ação Estatal', '## Princípios da Ação Estatal

O princípio da legalidade abrange todas as formas de normas estatais, enquanto o princípio da reserva legal restringe-se a matérias específicas determinadas pela Constituição.

### Conceitos
- **Princípio da Legalidade**: abrangência ampla, submetendo a atuação estatal a qualquer espécie normativa
- **Reserva Legal**: restringe-se a matérias específicas determinadas pela Constituição

### Referências legais
- Art. 59 da CF/88

### Dicas de prova
- Diferenciar entre princípio da legalidade e reserva legal
- Entender a abrangência do princípio da legalidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.210 (2)", "page_number": 210, "discipline": "Direito Constitucional", "legal_refs": ["Art. 59 da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T09:45:58.899170+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=210", "doc_key": "b28d3509dd01c66592901476d1821343"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '0b5282d595f78710f2302c96c182cc6383223e3c25e44b951d974b6e2c3e0ede'),
  ('cpiuris2025::929e66f6b32c57a54000436fe4665333', 'doutrina', 'cp_iuris', 'Direito Constitucional — Reserva Legal e Liberdade de Manifestação', '## Reserva Legal e Liberdade de Manifestação

A reserva legal é classificada em absoluta, relativa ou simples, dependendo da regulamentação da matéria constitucional pela lei. A liberdade de manifestação do pensamento e expressão é garantida pela Constituição Federal, mas com restrições.

### Conceitos
- **Reserva Legal**: Classificação da reserva legal em absoluta, relativa ou simples
- **Liberdade de Manifestação**: Garantia constitucional à expressão do pensamento e expressão

### Referências legais
- Art. 5º, II da CF/88
- Art. 5º, IV, V, IX da CF/88

### Dicas de prova
- Entenda a classificação da reserva legal e sua relação com a liberdade de manifestação.
- Análise o grau de proteção da liberdade de expressão à luz do caso concreto.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.211 (1)", "page_number": 211, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, II da CF/88", "Art. 5º, IV, V, IX da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T09:46:27.236218+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=211", "doc_key": "929e66f6b32c57a54000436fe4665333"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '4cd6d80569e7bd0c9496b7340ed740fbbe9b56d321e147a4cdc3ac89343818a4'),
  ('cpiuris2025::3fbaf57798caebd9bc3d2746fc398f90', 'doutrina', 'cp_iuris', 'Direito Constitucional — Liberdade de Expressão e Anonimato', '## Liberdade de Expressão e Anonimato

A liberdade de expressão é garantida em um Estado Democrático de Direito, mas há limites, como a vedação do anonimato, que permitem o exercício do direito de resposta e responsabilização penal e civil.

### Conceitos
- **Liberdade de Expressão**: Direito à liberdade de pensamento, opinião e comunicação
- **Anonimato**: Falta de identificação da pessoa que expressa uma opinião ou pensamento
- **Direito de Resposta**: O direito de responder a uma opinião ou ato de alguém

### Referências legais
- Art. 5º, X da Constituição Brasileira

### Jurisprudência
- RE 123456
- Súmula 455/STF

### Dicas de prova
- Entenda a distinção entre liberdade de expressão e anonimato
- Conheça as limitações da liberdade de expressão em um Estado Democrático de Direito', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.211 (2)", "page_number": 211, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, X da Constituição Brasileira"], "jurisprudence": ["RE 123456", "Súmula 455/STF"], "confidence": 0.8, "extracted_at": "2026-05-26T09:47:03.514633+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=211", "doc_key": "3fbaf57798caebd9bc3d2746fc398f90"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '64cf070ecb9d3917fcb21ac1d88f0b9ab167512c68b6e134db24390b72db1a79'),
  ('cpiuris2025::94c0bae870ba4b5861b67d5262adbda1', 'doutrina', 'cp_iuris', 'Direito Constitucional — Garantias Individuais e Direitos do Cidadão', '## Garantias Individuais e Direitos do Cidadão

O texto discute a importância das garantias individuais, incluindo o direito de resposta, o direito de resposta no caso de denúncia anônima e o direito à manifestação abusiva do pensamento.

### Conceitos
- **Denúncia Anônima**: Ação apresentada por terceiro sem identificação, que pode ser apurada pelas autoridades competentes.
- **Direito de Resposta**: Direito do ofendido para reagir contra o uso ilegítimo dos meios de comunicação.
- **Manifestação Abusiva do Pensamento**: Ação que visa limitar a liberdade de expressão, geralmente por meio da censura ou restrições constitucionais.

### Referências legais
- Art. 5º, XIX da CF
- Lei n.º 13.188/2015

### Jurisprudência
- STF, HC 106.152
- STF, MS 24.369

### Dicas de prova
- Entenda a diferença entre denúncia anônima e bilhete apócrifo.
- Conheça o direito de resposta e suas limitações.
- Aprenda a distinguir entre manifestação abusiva do pensamento e liberdade de expressão.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.212 (1)", "page_number": 212, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, XIX da CF", "Lei n.º 13.188/2015"], "jurisprudence": ["STF, HC 106.152", "STF, MS 24.369"], "confidence": 0.8, "extracted_at": "2026-05-26T09:47:39.143606+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=212", "doc_key": "94c0bae870ba4b5861b67d5262adbda1"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '5db0fc992a6874869405934591f98a070f6b84b30c8dfb26f77d2bf777277571'),
  ('cpiuris2025::fbd84aa336376b645b6c4d563e14b934', 'doutrina', 'cp_iuris', 'Direito Constitucional — Limites à liberdade de expressão e proteção da dignidade humana', '## Limites à liberdade de expressão e proteção da dignidade humana

O STF discutiu limites à liberdade de expressão, incluindo discurso de ódio e biografias não autorizadas, e estabeleceu regras para proteger a dignidade humana e os direitos fundamentais.

### Conceitos
- **Discurso de ódio**: Manifestação que viola frontalmente a dignidade da pessoa humana
- **Liberdade de expressão**: Direito à liberdade de pensamento, criação artística, produção científica e expressão
- **Dignidade humana**: Conceito jurídico que se refere à dignidade e valor intrínseco da pessoa humana
- **Biografias não autorizadas**: Obras que retratam pessoas sem consentimento ou autorização
- **Censura prévia**: Requisito para a publicação de obras biográficas literárias e audiovisuais

### Referências legais
- Art. 19 da CF/88
- STF, HC 82.424/RS

### Jurisprudência
- RE 123456
- HC 82.424/RS

### Dicas de prova
- Entenda a distinção entre discurso de ódio e liberdade de expressão
- Conheça as regras para proteger a dignidade humana e os direitos fundamentais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.212 (2)", "page_number": 212, "discipline": "Direito Constitucional", "legal_refs": ["Art. 19 da CF/88", "STF, HC 82.424/RS"], "jurisprudence": ["RE 123456", "HC 82.424/RS"], "confidence": 0.8, "extracted_at": "2026-05-26T09:48:13.632114+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=212", "doc_key": "fbd84aa336376b645b6c4d563e14b934"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '02cf3954b6535c91bfe438d92ca0a3d132d15d18b21c72f836dbfc4201104ab1'),
  ('cpiuris2025::4f3371de019ee95462c8a4d21c726acb', 'doutrina', 'cp_iuris', 'Direito Constitucional — Liberdade de Expressão e Garantias Individuais', '## Liberdade de Expressão e Garantias Individuais

A liberdade de expressão é protegida pela Constituição, mas há limites para a sua utilização, como a proteção da intimidade, privacidade, honra e imagem. As charges políticas e o uso do humor durante o processo eleitoral estão protegidos pela liberdade de expressão.

### Conceitos
- **Liberdade de Expressão**: Direito fundamental que permite a manifestação de opiniões, pensamentos e ideias
- **Garantias Individuais**: Direitos fundamentais que protegem a liberdade, segurança, dignidade e outros valores individuais
- **Intimidade**: Direito à privacidade e à proteção da vida pessoal
- **Privacidade**: Direito à proteção da vida pessoal e das informações
- **Honra**: Direito à reputação e à proteção da imagem
- **Imagem**: Direito à proteção da representação pública

### Referências legais
- Art. 5º, X da Constituição Brasileira de 1988

### Jurisprudência
- Súmula 667 do STF
- ADPF 187/2017

### Dicas de prova
- Entenda a distinção entre liberdade de expressão e proteção da intimidade, privacidade, honra e imagem.
- Conheça as limitações da liberdade de expressão, como a proteção da imagem e da reputação.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.213 (1)", "page_number": 213, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, X da Constituição Brasileira de 1988"], "jurisprudence": ["Súmula 667 do STF", "ADPF 187/2017"], "confidence": 0.8, "extracted_at": "2026-05-26T09:49:05.626925+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=213", "doc_key": "4f3371de019ee95462c8a4d21c726acb"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'f59837f891db08a1ef5e50ff0df00841a2f21eccbfc626cb8d31e78409cd635a'),
  ('cpiuris2025::90faab0fb72955728d2475952a163125', 'doutrina', 'cp_iuris', 'Direito Constitucional — Limites da liberdade de expressão', '## Limites da liberdade de expressão

A liberdade de expressão não pode ser utilizada para práticas ilícitas ou discursos de ódio, e a imunidade parlamentar não protege manifestações injuriosas em redes sociais.

### Conceitos
- **Discursos de ódio**: Manifestações que visam destruir o Estado Democrático de Direito e a democracia
- **Imunidade parlamentar**: Garantia constitucional que protege manifestações proferidas no desempenho da função legislativa ou em razão dela
- **Liberdade de expressão**: Direito à liberdade de pensamento, consciência e culto, bem como à liberdade de imprensa

### Referências legais
- Art. 19 da Constituição Federal
- Súmula 547 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Liberdade de expressão e discursos de ódio

### Dicas de prova
- Distinção entre liberdade de expressão e práticas ilícitas
- Entendimento da imunidade parlamentar em relação a manifestações injuriosas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.213 (2)", "page_number": 213, "discipline": "Direito Constitucional", "legal_refs": ["Art. 19 da Constituição Federal", "Súmula 547 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Liberdade de expressão e discursos de ódio"], "confidence": 0.8, "extracted_at": "2026-05-26T09:49:34.209457+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=213", "doc_key": "90faab0fb72955728d2475952a163125"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'f18cf90e19a06466a1158a206d4742cf1258cd64c53f8ed36420c54854975346'),
  ('cpiuris2025::30132b081fdbd8366cb5a89a1d40bc48', 'doutrina', 'cp_iuris', 'Direito Constitucional — Garantia da Imunidade Parlamentar', '## Garantia da Imunidade Parlamentar

A garantia da imunidade parlamentar não alcança atos praticados sem nexo claro com o desempenho de mandatos parlamentares, nem em casos de abusos ou usos criminosos.

### Conceitos
- **Imunidade Parlamentar**: Garantia que protege os membros do Parlamento de responsabilidade por atos praticados no exercício de suas funções
- **Nexo de Vinculação**: Relação necessária entre o discurso proferido e o desempenho das funções parlamentares para que a imunidade seja aplicada
- **Teoria Funcional**: A forma como a imunidade é compreendida, focando na proteção das funções essenciais do Parlamento

### Referências legais
- Art. 36 da Constituição Federal
- Súmula 822/STF

### Jurisprudência
- RE 123456
- ADPF 722/DF

### Dicas de prova
- Entenda a distinção entre imunidade parlamentar e liberdade de expressão
- Análise do nexo de vinculação é fundamental para aplicação da imunidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.214 (1)", "page_number": 214, "discipline": "Direito Constitucional", "legal_refs": ["Art. 36 da Constituição Federal", "Súmula 822/STF"], "jurisprudence": ["RE 123456", "ADPF 722/DF"], "confidence": 0.8, "extracted_at": "2026-05-26T09:50:07.621627+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=214", "doc_key": "30132b081fdbd8366cb5a89a1d40bc48"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '92b19e3f0cf1a88f99ae5435922088337a741d147f1f2160c9fc9c1b2b0f0276'),
  ('cpiuris2025::4f09bd727d28288a4db7f3f7da0222b9', 'doutrina', 'cp_iuris', 'Direito Constitucional — Investigação de servidores públicos federais, estaduais e municipais identificados como integrantes de movimento político', '## Investigação de servidores públicos federais, estaduais e municipais identificados como integrantes de movimento político

O STF considera que a investigação de servidores públicos com postura política contrária ao governo caracteriza desvio de finalidade e afronta aos direitos fundamentais da livre manifestação do pensamento, da privacidade, reunião e associação.

### Conceitos
- **Desvio de finalidade**: ocorrência em que o uso de recursos públicos ou autoridade pública é destinado a um fim diferente do estabelecido pela lei
- **Abuso de poder**: ocorrência em que o exercício de autoridade pública é feito de maneira excessiva, arbitrária ou ilegal
- **Livre manifestação do pensamento**: direito fundamental que permite a expressão de opiniões, ideias e pensamentos sem medo de repressão
- **Privacidade**: direito fundamental que protege a vida privada e pessoal dos indivíduos

### Referências legais
- Art. 5º, X da CF

### Jurisprudência
- RE 123456/2023
- Tema repetitivo: Investigações de servidores públicos federais, estaduais e municipais identificados como integrantes de movimento político

### Dicas de prova
- Entenda a distinção entre desvio de finalidade e abuso de poder
- Conheça os direitos fundamentais da livre manifestação do pensamento, da privacidade, reunião e associação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.214 (2)", "page_number": 214, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, X da CF"], "jurisprudence": ["RE 123456/2023", "Tema repetitivo: Investigações de servidores públicos federais, estaduais e municipais identificados como integrantes de movimento político"], "confidence": 0.8, "extracted_at": "2026-05-26T09:50:55.281667+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=214", "doc_key": "4f09bd727d28288a4db7f3f7da0222b9"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'ae3a78cbe6fdbbd08c5873a79c5a2c6bc2ca1680b7949bcb134001e6bedd5965'),
  ('cpiuris2025::9a6e3737df25492f77fb5fd2b2e86fa7', 'doutrina', 'cp_iuris', 'Direito Constitucional — Liberdade de Imprensa e Responsabilidade', '## Liberdade de Imprensa e Responsabilidade

A liberdade de imprensa é protegida pela Constituição, mas com responsabilidade. A censura prévia é vedada, mas é permitida a análise posterior de informações injuriosas ou difamantes.

### Conceitos
- **Liberdade de Imprensa**: Direito à liberdade de expressão e informação
- **Responsabilidade**: Obrigação de responder por atos ou omissões que causam danos a terceiros
- **Censura Prévia**: Restrição à liberdade de imprensa antes da publicação de uma notícia
- **Análise Posterior**: Avaliação posterior de informações injuriosas ou difamantes após a sua publicação

### Referências legais
- Art. 220 da CF/88
- Súmula 955 do STF

### Jurisprudência
- RE 1.075.412/PE
- Tema 955 do STF

### Dicas de prova
- Entenda a distinção entre censura prévia e análise posterior.
- Conheça as condições para que uma empresa jornalística possa ser responsabilizada civilmente por publicação de informações falsas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.215 (1)", "page_number": 215, "discipline": "Direito Constitucional", "legal_refs": ["Art. 220 da CF/88", "Súmula 955 do STF"], "jurisprudence": ["RE 1.075.412/PE", "Tema 955 do STF"], "confidence": 0.8, "extracted_at": "2026-05-26T09:51:30.887178+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=215", "doc_key": "9a6e3737df25492f77fb5fd2b2e86fa7"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'e2bac7bfe95205c870974e466e092d307c44b3d2ddcfddc3f63a9806477965bd'),
  ('cpiuris2025::6141d6fc863696fc302a4016385532d8', 'doutrina', 'cp_iuris', 'Direito Constitucional — Liberdade Religiosa e Separação entre Estado e Igreja', '## Liberdade Religiosa e Separação entre Estado e Igreja

A liberdade religiosa é garantida pela Constituição Federal de 1988, com proteção a todas as crenças e manutenção da separação entre o Estado e a Igreja.

### Conceitos
- **Liberdade Religiosa**: Direito à liberdade de consciência e de crença
- **Separação entre Estado e Igreja**: Distinção entre o poder do Estado e a Igreja
- **Cultos Religiosos**: Práticas religiosas que podem ser estabelecidas ou financiadas por entes federativos
- **Proteção aos Locais de Culto**: Garantia da proteção a locais de culto religioso
- **Prestação de Assistência Religiosa**: Direito à assistência religiosa em entidades civis e militares
- **Proteção Contra Discriminação**: Proteção contra discriminação por motivo de crença ou convicção filosófica ou política
- **Separação entre Estado e Igreja (Constitucionalismo)**: Distinção entre o poder do Estado e a Igreja no constitucionalismo brasileiro

### Referências legais
- Art. 5º, VI, VII, VIII, CF/88

### Dicas de prova
- Entenda a distinção entre liberdade religiosa e separação entre Estado e Igreja
- Conheça as garantias para cultos religiosos e locais de culto', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.215 (2)", "page_number": 215, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, VI, VII, VIII, CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T09:52:08.810761+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=215", "doc_key": "6141d6fc863696fc302a4016385532d8"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '60c39748771647c801a4b7cc4c07f2fde2d3cfc6d12caa5a49e1ca5d29daa5fe'),
  ('cpiuris2025::def3298a5ceaf41ac51a528b5f84c597', 'doutrina', 'cp_iuris', 'Direito Constitucional — Escusa de Consciência', '## Escusa de Consciência

A escusa de consciência é um direito individual que permite recusar determinadas obrigações que contrariem as crenças ou convicções de uma pessoa. No entanto, está condicionada ao cumprimento de prestação alternativa fixada em lei.

### Conceitos
- **Escusa de Consciência**: Direito individual que permite recusar determinadas obrigações que contrariem as crenças ou convicções de uma pessoa
- **Prestação Alternativa**: Obrigação fixada em lei que deve ser cumprida pela pessoa que invoca a escusa de consciência
- **Liberdade de Crença**: Direito garantido pela Constituição para praticar qualquer crença ou religião sem interferência do Estado
- **Imunidade Tributária Religiosa**: Proteção constitucional à liberdade religiosa, que inclui a imunidade tributária sobre templos de qualquer culto

### Referências legais
- Art. 15, IV da CF/88
- Art. 143, §1º da CF/88

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre escusa de consciência e liberdade de crença
- Conheça as implicações da escusa de consciência na prestação alternativa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.216 (1)", "page_number": 216, "discipline": "Direito Constitucional", "legal_refs": ["Art. 15, IV da CF/88", "Art. 143, §1º da CF/88"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T09:52:55.363894+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=216", "doc_key": "def3298a5ceaf41ac51a528b5f84c597"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'f30ce6501dea85e60302e376906b2ceef13c8d213c95dec050b521a279009e01'),
  ('cpiuris2025::353f23223a4b84d4b63c776692731aa2', 'doutrina', 'cp_iuris', 'Direito Constitucional — Ensino de Religião nas Escolas Públicas', '## Ensino de Religião nas Escolas Públicas

O artigo 210, §1º da CF/88 estabelece que o ensino religioso é disciplina facultativa nas escolas públicas de ensino fundamental, regulamentado pela Lei n.º 9.394/96.

### Conceitos
- **Facultatividade**: O ensino religioso é obrigatório apenas se o aluno optar por cursá-lo.
- **Pluralismo**: A diversidade cultural do país deve ser respeitada no ensino de religião.
- **Proselitismo**: É vedado qualquer forma de proselitismo no ensino de religião.
- **Alternativas Pedagógicas**: Os alunos que não optarem por cursar a disciplina de ensino religioso devem ter alternativas pedagógicas para alcançarem a carga mínima anual de 800 horas.

### Referências legais
- Art. 210, §1º da CF/88
- Lei n.º 9.394/96

### Jurisprudência
- ADI 4.439
- ...

### Dicas de prova
- Observar a matrícula facultativa e a necessidade de expressa manifestação de vontade do aluno.
- Respeitar a pluralidade cultural do país no ensino de religião.
- Vedado o proselitismo no ensino de religião.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.216 (2)", "page_number": 216, "discipline": "Direito Constitucional", "legal_refs": ["Art. 210, §1º da CF/88", "Lei n.º 9.394/96"], "jurisprudence": ["ADI 4.439", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T09:53:28.101783+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=216", "doc_key": "353f23223a4b84d4b63c776692731aa2"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'b6790e517b3dca0d13f20f275fdf1f51933c15736c3bb13f43f545d17086b2a9'),
  ('cpiuris2025::6cc8468e507028002afd0609c696b908', 'doutrina', 'cp_iuris', 'Direito Constitucional — Direitos e Garantias Individuais', '## Direitos e Garantias Individuais

A doutrina majoritária defende que o ensino religioso pode ser confessional, interconfissional ou não confessional, mas a matrícula deve ser facultativa. Além disso, os feriados religiosos podem ser justificados por seu caráter histórico-cultural e o casamento pode ser celebrado por líder de qualquer religião ou crença.

### Conceitos
- **Liberdade Religiosa**: O direito de cada indivíduo de escolher sua própria religião e praticá-la livremente.
- **Direitos Individuais Garantidos**: Os direitos fundamentais assegurados pela Constituição, como a liberdade de expressão, a liberdade de culto e outros.
- **Feriados Religiosos**: Datas comemorativas que têm significado religioso para um grupo específico da população.

### Referências legais
- Art. 215, §2º da CF/88

### Dicas de prova
- Entenda a liberdade religiosa e seus limites.
- Conheça os direitos individuais garantidos pela Constituição.
- Análise os feriados religiosos e seu impacto na sociedade.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.217 (1)", "page_number": 217, "discipline": "Direito Constitucional", "legal_refs": ["Art. 215, §2º da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T09:54:03.705337+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=217", "doc_key": "6cc8468e507028002afd0609c696b908"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'ca3414e9e9ed13420c7121361508354182bfa198275ec8216500807e1bd1d893'),
  ('cpiuris2025::ef2898d89d5af9b492690e75c1f75fac', 'doutrina', 'cp_iuris', 'Direito Constitucional — Direito à Saúde e Liberdade Religiosa', '## Direito à Saúde e Liberdade Religiosa

Testemunhas de Jeová têm direito a recusar procedimentos médicos que envolvam transfusão de sangue, com base na autonomia individual e liberdade religiosa. O paciente também tem o direito de recusar tratamento de saúde por motivos religiosos, desde que seja feita uma decisão informada e esclarecida.

### Conceitos
- **Autonomia Individual**: Direito do indivíduo à liberdade e à capacidade de tomar decisões sobre sua própria vida.
- **Liberdade Religiosa**: Direito do indivíduo a praticar sua religião livremente, sem interferência do Estado.
- **Direito à Saúde**: Direito fundamental do indivíduo à saúde e bem-estar.
- **Recusa de Tratamento Médico**: O direito do paciente a recusar tratamento médico por motivos religiosos ou outros.

### Referências legais
- Art. 196 da Constituição Federal
- STF. Plenário. RE 979.742/AM

### Jurisprudência
- RE 979.742/AM
- RE 1.212.272/AL

### Dicas de prova
- Entenda a importância da autonomia individual e liberdade religiosa no direito à saúde.
- Conheça o conceito de recusa de tratamento médico e suas implicações.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.217 (2)", "page_number": 217, "discipline": "Direito Constitucional", "legal_refs": ["Art. 196 da Constituição Federal", "STF. Plenário. RE 979.742/AM"], "jurisprudence": ["RE 979.742/AM", "RE 1.212.272/AL"], "confidence": 0.8, "extracted_at": "2026-05-26T09:54:48.218536+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=217", "doc_key": "ef2898d89d5af9b492690e75c1f75fac"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'c28bbfea1c4645714d398892b7e86c9500bc1701c52ae41621b8d38b291cc328'),
  ('cpiuris2025::ac65a20c39ae1a5b3789269cefe69d26', 'doutrina', 'cp_iuris', 'Direito Constitucional — Direitos e Garantias Individuais', '## Direitos e Garantias Individuais

O texto discute vários tópicos relacionados a direitos individuais, incluindo o curandeirismo, fixação de crucifixos em repartições públicas, imunidade religiosa e guarda sabática.

### Conceitos
- **Curandeirismo**: Exercício do curandeirismo é crime contra a saúde pública
- **Liberdade Religiosa**: Não pode servir de escusa para prática de ilícitos penais, especialmente quando há abuso desse direito
- **Imunidade Tributária Religiosa**: Prevista no art. 150, VI, b, da CF/88, vedada a instituição de impostos sobre templos de qualquer culto
- **Guarda Sabática**: O candidato de concurso público pode alterar datas e horários previstos em edital por motivos religiosos?

### Referências legais
- Art. 284 do CP
- Art. 150, VI, b da CF/88
- Lei n.º 13.796/2019

### Jurisprudência
- RE 562.351
- RHC 62.240

### Dicas de prova
- Distinção entre liberdade religiosa e prática de ilícitos penais
- Entendimento da imunidade tributária religiosa
- Revisão do artigo 7º-A da Lei de Diretrizes e Bases da Educação Nacional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.218 (1)", "page_number": 218, "discipline": "Direito Constitucional", "legal_refs": ["Art. 284 do CP", "Art. 150, VI, b da CF/88", "Lei n.º 13.796/2019"], "jurisprudence": ["RE 562.351", "RHC 62.240"], "confidence": 0.8, "extracted_at": "2026-05-26T09:55:27.556722+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=218", "doc_key": "ac65a20c39ae1a5b3789269cefe69d26"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '66a79039660d0dac690801429a457a25711fd5d96aa1991cdfc04cbcc9c3b226'),
  ('cpiuris2025::3ec03519c9fea42cf9267da26ba139db', 'doutrina', 'cp_iuris', 'Direito Constitucional — Exceções à Lei: Direito à Consciência Religiosa', '## Exceções à Lei: Direito à Consciência Religiosa

O direito à consciência religiosa permite a realização de etapas de concurso público em datas e horários distintos dos previstos, desde que haja razoabilidade, igualdade e não acarrete ônus desproporcional.

### Conceitos
- **Direito à Consciência Religiosa**: O direito de um indivíduo a exercer sua religião sem interferência do Estado.
- **Razoabilidade**: A necessidade de justificar uma alteração no edital do concurso público por motivo de crença religiosa.
- **Igualdade**: A preservação da igualdade entre todos os candidatos que estão sendo afetados pela alteração do edital.
- **Ônus Desproporcional**: A não ocorrência de um impacto excessivo ou desmedido na Administração Pública que deverá decidir sobre a alteração do edital.

### Referências legais
- Art. 5º, VIII da Constituição Federal

### Jurisprudência
- {''term'': ''STF'', ''definition'': ''Superior Tribunal Federal''}
