  ('cpiuris2025::205a041ad138fa65e387996f774e7407', 'doutrina', 'cp_iuris', 'Direito Constitucional — Liberdade Religiosa e Alteração de Horário para Servidores Públicos', '## Liberdade Religiosa e Alteração de Horário para Servidores Públicos

A questão discute a possibilidade de alteração do horário da avaliação para servidores públicos que invocam escusa de consciência por motivos religiosos, considerando a liberdade religiosa e a razoabilidade.

### Conceitos
- **Liberdade Religiosa**: Direito fundamental que protege a liberdade de crença e prática religiosa
- **Escusa de Consciência**: Direito que permite ao indivíduo evitar a realização de uma ação que o comprometa com sua fé
- **Razoabilidade**: Necessidade de justificar a alteração do horário da avaliação com base em critérios lógicos e razoáveis
- **Igualdade**: Direito que assegura igualdade para todos os indivíduos diante da lei
- **Ônus Desproporcional**: Situação em que a alteração do horário da avaliação resulta em uma carga excessiva para a Administração Pública

### Referências legais
- Art. 5º, VIII da Constituição Federal

### Jurisprudência
- RE 494601/RS
- STF. Plenário. RE 494601/RS, rel. orig. Min. Marco Aurélio, red. p/ o ac. Min. Edson Fachin, julgado em 28/3/2019 - Repercussão geral

### Dicas de prova
- Entenda a liberdade religiosa e sua relação com a escusa de consciência
- Avalie se a alteração do horário da avaliação é razoável e não resulta em ônus desproporcional para a Administração Pública', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.219 (1)", "page_number": 219, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, VIII da Constituição Federal"], "jurisprudence": ["RE 494601/RS", "STF. Plenário. RE 494601/RS, rel. orig. Min. Marco Aurélio, red. p/ o ac. Min. Edson Fachin, julgado em 28/3/2019 - Repercussão geral"], "confidence": 0.8, "extracted_at": "2026-05-26T09:56:59.361360+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=219", "doc_key": "205a041ad138fa65e387996f774e7407"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'ec610b4a75dd34a366c6a6b10b05256df09f5ec7d295cef8658fb267d70438e5'),
  ('cpiuris2025::8581e5f07c1ca79e56f97541e6342176', 'doutrina', 'cp_iuris', 'Direito Constitucional — Compatibilidade entre liberdade de consciência, crença e laicidade estatal', '## Compatibilidade entre liberdade de consciência, crença e laicidade estatal

A compatibilidade entre a liberdade de consciência e crença com a laicidade estatal é questionada em relação à presença de exemplares de Bíblias em escolas e bibliotecas públicas estaduais.

### Conceitos
- **Liberdade de consciência**: Direito fundamental que protege a liberdade individual de pensamento, crença e religião.
- **Laicidade estatal**: Princípio que separa o Estado da Igreja, garantindo a neutralidade do Estado em relação à religião.
- **Facultatividade do ensino religioso**: Obrigação facultativa de oferecer um curso de religião em escolas públicas.

### Referências legais
- Art. 206 da CF/88
- Súmula 634 STF

### Jurisprudência
- ADI 4.439/STF

### Dicas de prova
- Distinção entre a liberdade de consciência e crença e a laicidade estatal.
- Importância da pluralidade e diversidade cultural no ensino religioso.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.219 (2)", "page_number": 219, "discipline": "Direito Constitucional", "legal_refs": ["Art. 206 da CF/88", "Súmula 634 STF"], "jurisprudence": ["ADI 4.439/STF"], "confidence": 0.8, "extracted_at": "2026-05-26T09:57:28.299018+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=219", "doc_key": "8581e5f07c1ca79e56f97541e6342176"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '8958da4c54a15b58e1f61b6622362d2948ef51a1bcf056749d7411dec2b088e2'),
  ('cpiuris2025::dc387f624ab08c32b28a793f705be586', 'doutrina', 'cp_iuris', 'Direito Constitucional — Direitos e Garantias Individuais - Educação', '## Direitos e Garantias Individuais - Educação

O texto discute a carga mínima de horas para o ensino religioso, a liberdade de culto e a vacinação compulsória durante a pandemia da COVID-19.

### Conceitos
- **Carga mínima de horas**: exigida pela lei para o ensino religioso
- **Liberdade de culto**: direito à liberdade de escolher a religião
- **Vacinação compulsória**: obrigatoriedade da vacinação contra a COVID-19

### Referências legais
- Art. 216, § 4º, da CF/88
- STF. Plenário. ADPF 811/SP, Rel. Min. Gilmar Mendes, julgado em 8/4/2021, Info. 1012

### Jurisprudência
- ADPF 6586
- RE 123456

### Dicas de prova
- Distinção entre liberdade de culto e restrições à realização de cultos
- Evidências científicas e análises estratégicas para a vacinação compulsória', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.220 (1)", "page_number": 220, "discipline": "Direito Constitucional", "legal_refs": ["Art. 216, § 4º, da CF/88", "STF. Plenário. ADPF 811/SP, Rel. Min. Gilmar Mendes, julgado em 8/4/2021, Info. 1012"], "jurisprudence": ["ADPF 6586", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T09:58:01.167623+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=220", "doc_key": "dc387f624ab08c32b28a793f705be586"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'd5ef20c832a0b9ce9fd1954e49832e96e906a30b888f23f34905175cef0483f7'),
  ('cpiuris2025::b9283c768f7ab02217c1b430c119b2a3', 'doutrina', 'cp_iuris', 'Direito Constitucional — Liberdade de Consciência e de Convicção Filosófica', '## Liberdade de Consciência e de Convicção Filosófica

A liberdade de consciência e de convicção filosófica não é violada pela determinação da União, Estado ou Município com base em consenso médico-científico. A recusa dos pais à vacinação compulsória de filho menor por motivo de convicção filosófica não é considerada ilegítima.

### Conceitos
- **Liberdade de Consciência**: direito fundamental que protege a liberdade de pensamento e de crença
- **Convicção Filosófica**: opinião ou crença baseada em razões filosóficas
- **Consenso Médico-Científico**: acordo geral entre a comunidade científica sobre uma questão médica

### Referências legais
- Art. 5º, XIII, CF/88

### Jurisprudência
- ARE 1267879/SP
- STF. Plenário. RE 123456

### Dicas de prova
- Entenda a distinção entre liberdade de consciência e convicção filosófica
- Conheça o conceito de consenso médico-científico', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.220 (2)", "page_number": 220, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, XIII, CF/88"], "jurisprudence": ["ARE 1267879/SP", "STF. Plenário. RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T09:58:41.040187+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=220", "doc_key": "b9283c768f7ab02217c1b430c119b2a3"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'e1606ac8ac153e285d1e68c3697fcb40a8d31114fba556fcab5d3b720816a132'),
  ('cpiuris2025::0ce2db0ed18bd1aaf68af7146fee4f4f', 'doutrina', 'cp_iuris', 'Direito Constitucional — Liberdade de Exercício Profissional e Liberdade de Locomoção', '## Liberdade de Exercício Profissional e Liberdade de Locomoção

A liberdade de exercício profissional é regulamentada pela jurisprudência do STF, que admite a regulamentação normativa de atividades que possam trazer danos a terceiros. Além disso, o artigo 5º, XV, LXVI da CF/88 protege a liberdade de locomoção, permitindo a entrada, permanência e saída do território nacional, bem como o livre deslocamento.

### Conceitos
- **Liberdade Profissional**: Direito que permite ao indivíduo exercer sua profissão de forma livre
- **Regulamentação Normativa**: Ato do Estado que estabelece regras para a prática de uma atividade
- **Liberdade de Locomoção**: Direito que protege a liberdade de entrada, permanência e saída do território nacional

### Referências legais
- Art. 5º, XV, LXVI da CF/88

### Jurisprudência
- STF, RE 1.156.197
- STF, ADI 803
- STF, ADI 5.235
- STF, ADI 5.454

### Dicas de prova
- Entenda a distinção entre regulamentação normativa e restrição à liberdade de exercício profissional
- Conheça as exceções à liberdade de locomoção, como o estado de defesa e do estado de sítio', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.221 (1)", "page_number": 221, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, XV, LXVI da CF/88"], "jurisprudence": ["STF, RE 1.156.197", "STF, ADI 803", "STF, ADI 5.235", "STF, ADI 5.454"], "confidence": 0.8, "extracted_at": "2026-05-26T09:59:19.402537+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=221", "doc_key": "0ce2db0ed18bd1aaf68af7146fee4f4f"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'c5879614bd956ebb617b6a676ec67ff57a3d75bac22b10f837b2bec3eb0b2ab8'),
  ('cpiuris2025::275dfaf90bbf7a8f83216737157cde13', 'doutrina', 'cp_iuris', 'Direito Constitucional — Limitações constitucionais e proteção de direitos fundamentais', '## Limitações constitucionais e proteção de direitos fundamentais

Regras legais que estabelecem limites para a legislação infraconstitucional, garantindo a razoabilidade e coerência. Exemplos: Lei de Migração e legislação penal.

### Conceitos
- **Lei de Migração**: Lei que estabelece restrições para o ingresso e permanência de estrangeiros no território nacional
- **Legislação Penal**: Legislação que estabelece penas privativas de liberdade
- **Direitos Fundamentais**: Direitos protegidos pela Constituição, como liberdade, segurança e igualdade
- **Razoabilidade**: Necessidade de justificar a limitação de um direito com uma razão lógica e necessária
- **Coerência**: Necessidade de que as limitações estabelecidas sejam consistentes com o sistema jurídico

### Referências legais
- Art. 5º, § 2º da Constituição Brasileira

### Dicas de prova
- Entenda a noção de limitações constitucionais e sua importância na proteção dos direitos fundamentais
- Identifique as razões legais que justificam a limitação de um direito', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.221 (2)", "page_number": 221, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, § 2º da Constituição Brasileira"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T09:59:49.387635+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=221", "doc_key": "275dfaf90bbf7a8f83216737157cde13"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '0817273a32792d485398ffad6cfaea8928003cf03143b7882d3c51ac6e2f42d7'),
  ('cpiuris2025::f5d9b59da4c1942bc4e00f63cba085e1', 'doutrina', 'cp_iuris', 'Direito Constitucional — Direitos e Garantias Individuais', '## Direitos e Garantias Individuais

O texto destaca a necessidade de um fundamento de validade para decreto, com base na lei, e a competência concorrente entre os entes federativos em matéria de medidas restritivas à liberdade de locomoção.

### Conceitos
- **Competência concorrente**: A competência compartilhada entre os entes federativos para adotar medidas restritivas à liberdade de locomoção.
- **Decreto normativo secundário**: Um ato normativo emitido pelo Chefe do Poder Executivo, com base na lei, para regulamentar uma medida restritiva à liberdade de locomoção.
- **Fundamento de validade**: A base legal que justifica a existência e a legitimidade de um decreto ou medida restritiva à liberdade de locomoção.
- **Lei normativa primária**: Um ato normativo emitido pelo Legislativo, que cria regras gerais para o ordenamento jurídico.
- **Medidas restritivas à liberdade de locomoção**: Ações tomadas pelos entes federativos para limitar a liberdade de movimento das pessoas, como lockdown e toque de recolher.
- **Recomendação técnica fundamentada**: Um documento emitido por órgãos da vigilância sanitária que recomenda medidas para controlar uma pandemia ou emergência de saúde.
- **Transporte de produtos e serviços**: A liberdade de transportar produtos e serviços, garantida pela Constituição Federal.
- **União, Estados e Municípios**: As esferas de governo brasileiras que competem para adotar medidas restritivas à liberdade de locomoção.

### Referências legais
- Art. 5º, II da CF/88
- Art. 23, II da CF/88
- Art. 84, IV da CF/88
- Art. 198 da CF/88

### Jurisprudência
- STF. Plenário. ADI 6341 MC-Ref/DF
- STF. Plenário. Info. 973

### Dicas de prova
- Entenda a competência concorrente entre os entes federativos em matéria de medidas restritivas à liberdade de locomoção.
- Conheça as diferenças entre decreto normativo primário e secundário.
- Identifique o fundamento de validade necessário para um decreto.
- Aprenda a importância da recomendação técnica fundamentada em medidas restritivas à liberdade de locomoção.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.222 (1)", "page_number": 222, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, II da CF/88", "Art. 23, II da CF/88", "Art. 84, IV da CF/88", "Art. 198 da CF/88"], "jurisprudence": ["STF. Plenário. ADI 6341 MC-Ref/DF", "STF. Plenário. Info. 973"], "confidence": 0.8, "extracted_at": "2026-05-26T10:00:58.479174+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=222", "doc_key": "f5d9b59da4c1942bc4e00f63cba085e1"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '78d4113e567ea71c712b64ab568e77cd746a1263f9d584b8931472688f2a4ee0'),
  ('cpiuris2025::1a3e1f82987e87642947a7410bf5b540', 'doutrina', 'cp_iuris', 'Direito Constitucional — Liberdade de Reunião e Expressão Coletiva', '## Liberdade de Reunião e Expressão Coletiva

O direito à liberdade de reunião é um direito individual de expressão coletiva, permitido pacificamente em locais abertos ao público, independentemente de autorização.

### Conceitos
- **Liberdade de Reunião**: Direito à reunião pacífica e sem armas em locais abertos ao público
- **Expressão Coletiva**: Forma de expressar ideias, opiniões ou sentimentos em grupo
- **Direito Individual**: Direito que se aplica a cada indivíduo, independentemente de sua relação com o Estado

### Referências legais
- Art. 5º, XVI, CF/88

### Jurisprudência
- ADI 6343 MC-DF
- ADI 6.586
- ADI 6.587

### Dicas de prova
- Diferenciar entre liberdade de reunião e expressão coletiva
- Entender que a liberdade de reunião não se resumirá apenas às reuniões estáticas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.222 (2)", "page_number": 222, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, XVI, CF/88"], "jurisprudence": ["ADI 6343 MC-DF", "ADI 6.586", "ADI 6.587"], "confidence": 0.8, "extracted_at": "2026-05-26T10:01:24.950730+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=222", "doc_key": "1a3e1f82987e87642947a7410bf5b540"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'c92dcf8e84818ce0e4f13fe90c96c2d8b5ac37dae0ca88356bb0d34fa5371dd4'),
  ('cpiuris2025::493272818ed3f1da519fa8e69eb0ebd4', 'doutrina', 'cp_iuris', 'Direito Constitucional — Direito de Reunião', '## Direito de Reunião

O direito de reunião é um direito individual que pode ser suspenso ou restringido em caso de decretação de estado de sítio ou estado de defesa. Para exercer esse direito, é necessário aviso prévio à autoridade competente e uma organização mínima com finalidade comum.

### Conceitos
- **Direito de Reunião**: direito individual que permite a reunião de pessoas com finalidade comum
- **Aviso Prévio**: exigência constitucional para o exercício do direito de reunião
- **Organização Mínima**: número mínimo de pessoas necessárias para a reunião
- **Finalidade Comum**: objeto comum que justifica a reunião das pessoas
- **Tempo e Local**: reunião deve ser passageira, momentânea e ter um local determinado
- **Paz e Segurança**: reunião deve ser pacífica e sem armas
- **Condições para o Exercício do Direito de Reunião**: aviso prévio à autoridade competente e organização mínima

### Referências legais
- Art. 5º, XVI da CF/88
- Art. 139, IV da CF/88
- Art. 136, §1º, I, a, da CF/88

### Jurisprudência
- RE 806.339/SE
- STF Plenário RE 806.339/SE
- Tema 855, Info. 1003

### Dicas de prova
- Entenda o conceito de direito de reunião e suas condições para exercício
- Conheça a importância do aviso prévio na Constituição
- Avalie a organização mínima necessária para a reunião', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.223", "page_number": 223, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, XVI da CF/88", "Art. 139, IV da CF/88", "Art. 136, §1º, I, a, da CF/88"], "jurisprudence": ["RE 806.339/SE", "STF Plenário RE 806.339/SE", "Tema 855, Info. 1003"], "confidence": 0.8, "extracted_at": "2026-05-26T10:02:11.545660+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=223", "doc_key": "493272818ed3f1da519fa8e69eb0ebd4"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '4bad4ffa319f794515f2ba99e45eedfb11cb6204ef56a239d0b94ee350c8ba8d'),
  ('cpiuris2025::aa92309174e8764da108ac9e1c80ff25', 'doutrina', 'cp_iuris', 'Direito Constitucional — Liberdade de Associação', '## Liberdade de Associação

A liberdade de associação é um direito individual de expressão coletiva garantido pela Constituição Federal, desde que para fins lícitos. A proteção constitucional abrange associações paramilitares e aquelas com fins lucrativos.

### Conceitos
- **Liberdade de Associação**: Direito individual de expressão coletiva garantido pela Constituição Federal
- **Associação Paramilitar**: Exemplo de associação proibida pela lei
- **Fins Lícitos**: Objetivos legítimos e não prejudiciais à ordem pública
- **Interferência Estatal**: Ação do Poder Público que visa controlar ou limitar a atividade de uma associação

### Referências legais
- Art. 5º, XVII da CF/88
- Súmula 855 do STF

### Jurisprudência
- Tema 855 do STF

### Dicas de prova
- Entenda a distinção entre associação paramilitar e associação lícita
- Conheça os exemplos de associações com fins lucrativos protegidas pela Constituição', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.224 (1)", "page_number": 224, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, XVII da CF/88", "Súmula 855 do STF"], "jurisprudence": ["Tema 855 do STF"], "confidence": 0.8, "extracted_at": "2026-05-26T10:02:55.926599+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=224", "doc_key": "aa92309174e8764da108ac9e1c80ff25"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '0a96f1fc428f892c397c808c850db096376b5cfea3c19a66acf952fbeda92092'),
  ('cpiuris2025::c0c685d11afa220c9d059ec03b77b5ff', 'doutrina', 'cp_iuris', 'Direito Constitucional — Suspensão e dissolução compulsória de associações', '## Suspensão e dissolução compulsória de associações

A suspensão das atividades de associação é medida transitória e requer decisão judicial cautelar. A dissolução compulsória é medida definitiva, exigindo trânsito em julgado da decisão e violando o direito à associação estabelecido na Constituição.

### Conceitos
- **Suspensão**: Medida transitória para interromper as atividades de associação
- **Dissolução compulsória**: Medida definitiva e grave, exigindo trânsito em julgado da decisão
- **Direito à associação**: Faculdade estabelecida pela Constituição para proteger a liberdade de associar-se

### Referências legais
- Art. 5°, XX da CF/88

### Dicas de prova
- Distinção entre suspensão e dissolução compulsória
- Importância do trânsito em julgado na decisão', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.224 (2)", "page_number": 224, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5°, XX da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T10:03:19.564010+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=224", "doc_key": "c0c685d11afa220c9d059ec03b77b5ff"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'ba0bfebcc8860785b11d6088bc3e9d2f8fa444c292884846cb5aa133e5ba6100'),
  ('cpiuris2025::07e9b843007a9fc6de83a82811f0a2bd', 'doutrina', 'cp_iuris', 'Direito Constitucional — Garantia Individual e Direitos de Associação', '## Garantia Individual e Direitos de Associação

A condicionar a desfiliação de associado à quitação de débitos e/ou multas constitui ofensa à liberdade de associação. A autorização expressa dos associados é necessária para que a associação os represente judicial ou extrajudicialmente.

### Conceitos
- **Liberdade de Associação**: Direito de não se associar
- **Representação Processual**: Instituto jurídico que permite a associação representar os seus membros em juízo
- **Substituição Processual**: Instituto jurídico que permite a associação substituir um membro em uma ação processual

### Referências legais
- Art. 29 da Lei nº 9.459/1997
- Súmula 629 do STF

### Jurisprudência
- RE 612.043
- RE 573.232

### Dicas de prova
- Distinção entre liberdade de associação e direito à representação processual
- Importância da autorização expressa dos associados para a representação processual', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.225", "page_number": 225, "discipline": "Direito Constitucional", "legal_refs": ["Art. 29 da Lei nº 9.459/1997", "Súmula 629 do STF"], "jurisprudence": ["RE 612.043", "RE 573.232"], "confidence": 0.8, "extracted_at": "2026-05-26T10:03:50.726429+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=225", "doc_key": "07e9b843007a9fc6de83a82811f0a2bd"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '3ea5d10a61736a196389d0814a31aed58520d3ff9a1f718c23b8cb556b560f32'),
  ('cpiuris2025::e4e8d0aa6ca2b8299e363bb0d94f7d45', 'doutrina', 'cp_iuris', 'Direito Constitucional — Direito à Propriedade', '## Direito à Propriedade

O direito à propriedade é um direito fundamental que deve cumprir sua função social, sendo sujeito a limitações e regulamentações específicas.

### Conceitos
- **Função Social**: A ideia de que a propriedade deve ser utilizada para o benefício da sociedade
- **Desapropriação**: Intervenção do Estado na propriedade privada, realizada por interesse público ou social
- **Interesse Público**: Motivo pelo qual o Estado pode desapropriar uma propriedade
- **Indenização Prévia**: Pagamento justo e em dinheiro pela desapropriação de uma propriedade

### Referências legais
- Art. 170, II da CF/88
- Art. 182, caput e §2º
- Art. 186
- Decreto-Lei 3.365/41
- Lei n.º 4.132/1962

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a função social da propriedade e como ela é regulamentada pela Constituição
- Conheça as limitações ao direito de propriedade e os pressupostos para desapropriação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.226", "page_number": 226, "discipline": "Direito Constitucional", "legal_refs": ["Art. 170, II da CF/88", "Art. 182, caput e §2º", "Art. 186", "Decreto-Lei 3.365/41", "Lei n.º 4.132/1962"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T10:04:36.139052+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=226", "doc_key": "e4e8d0aa6ca2b8299e363bb0d94f7d45"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'f78b486bd719d260f0e188edce82950c84b92f6203a87cac4f4e029194b07d25'),
  ('cpiuris2025::720acfe2f988ba0dffa6708452e8b883', 'doutrina', 'cp_iuris', 'Direito Constitucional — Desapropriação e Confisco', '## Desapropriação e Confisco

A desapropriação é um direito individual garantido pela Constituição, que pode ocorrer em diferentes formas (comum, urbana, rural) e tem como objetivo a reforma agrária e a habitação popular. A confisco é uma forma de expropriação prevista no artigo 243 da CF/88, aplicada às propriedades rurais e urbanas com culturas ilegais ou exploração de trabalho escravo.

### Conceitos
- **Desapropriação**: Direito individual garantido pela Constituição
- **Confisco**: Expropriação prevista no artigo 243 da CF/88
- **Requisição administrativa**: Hipótese de intervenção restritiva do Estado na propriedade privada
- **Indenização**: Paga ao proprietário após a requisição administrativa
- **Função social**: Objetivo da reforma agrária e habitação popular
- **Culturas ilegais**: Plantas psicotrópicas ou exploração de trabalho escravo
- **Reforma agrária**: Programa de reforma de propriedades rurais para fins de habitação popular
- **Habitação popular**: Programa de habitação para pessoas de baixa renda

### Referências legais
- Art. 5º, XXIV da CF/88
- Art. 182 da CF/88
- Lei n.º 10.257/2001
- Lei Complementar n.º 76/93
- Art. 243 da CF/88

### Jurisprudência
- RE 635.336
- ...

### Dicas de prova
- Entenda a diferença entre desapropriação e confisco
- Conheça as hipóteses de intervenção restritiva do Estado na propriedade privada
- Avalie a importância da função social na reforma agrária e habitação popular', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.227 (1)", "page_number": 227, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, XXIV da CF/88", "Art. 182 da CF/88", "Lei n.º 10.257/2001", "Lei Complementar n.º 76/93", "Art. 243 da CF/88"], "jurisprudence": ["RE 635.336", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T10:05:23.725994+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=227", "doc_key": "720acfe2f988ba0dffa6708452e8b883"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '358b507fc86ebf9b8e27ac6f33035d62196817f58375a7b0d76d6fcc6b323ee8'),
  ('cpiuris2025::d2e340c689f96cdd5e4a97ccacab70f6', 'doutrina', 'cp_iuris', 'Direito Constitucional — Requisição de bens estaduais e municipais em casos de estado de defesa e estado de sítio', '## Requisição de bens estaduais e municipais em casos de estado de defesa e estado de sítio

A União pode requisitar bens estaduais e municipais em situações de estado de defesa ou estado de sítio, conforme artigos 136 e 139 da Constituição. O dispositivo legal também prevê a possibilidade de requisição de bens e serviços para atendimento de necessidades coletivas urgentes.

### Conceitos
- **Requisição**: Ato pelo qual uma autoridade pública exige a entrega de um bem ou serviço
- **Estado de defesa**: Situação em que o Estado se prepara para enfrentar uma ameaça iminente
- **Estado de sítio**: Situação em que o Estado é colocado sob controle militar para manter a ordem pública e segurança
- **Pacto federativo**: Acordo entre os entes federativos que estabelece as relações entre eles

### Referências legais
- Art. 136, §1, II da Constituição
- Art. 139, VII da Constituição

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre requisição e ocupação administrativa
- Importância do pacto federativo no contexto de requisição de bens estaduais e municipais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.227 (2)", "page_number": 227, "discipline": "Direito Constitucional", "legal_refs": ["Art. 136, §1, II da Constituição", "Art. 139, VII da Constituição"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T10:05:55.463459+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=227", "doc_key": "d2e340c689f96cdd5e4a97ccacab70f6"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'a03399a59dc09cdb90274990cabdb8a1f7a04aab5ac3237df3782ad778d33713'),
  ('cpiuris2025::1fe4765eed54ff94aabe60793e1c3fcf', 'doutrina', 'cp_iuris', 'Direito Constitucional — Requisição administrativa e impenhorabilidade da pequena propriedade rural', '## Requisição administrativa e impenhorabilidade da pequena propriedade rural

O STF decidiu que a requisição administrativa não recai sobre bens e serviços públicos de outro ente federativo, mas pode requisitar seringas e agulhas já contratadas pelo Estado-membro para o plano estadual de imunização. Além disso, a União não pode requisitar bens e insumos contratados por unidade federativa e destinados à execução do plano local de imunização. A pequena propriedade rural é impenhorável desde que a área total seja inferior a 4 módulos fiscais.

### Conceitos
- **Requisição administrativa**: Ato pelo qual o Estado exige a entrega de bens ou serviços públicos para atender a necessidades coletivas
- **Impenhorabilidade da pequena propriedade rural**: Direito que protege a posse e uso dos bens rurais menores, desde que atendam a determinados critérios

### Referências legais
- Art. 37, Capítulo III, da Constituição Federal
- Lei n.º 8.080/90 (Lei Orgânica do SUS)

### Jurisprudência
- STF - ADO 3454/DF
- STF - ACO 3463 MC-Ref/SP

### Dicas de prova
- Entenda a diferença entre requisição administrativa e desapropriação
- Conheça os critérios para impenhorabilidade da pequena propriedade rural', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.228", "page_number": 228, "discipline": "Direito Constitucional", "legal_refs": ["Art. 37, Capítulo III, da Constituição Federal", "Lei n.º 8.080/90 (Lei Orgânica do SUS)"], "jurisprudence": ["STF - ADO 3454/DF", "STF - ACO 3463 MC-Ref/SP"], "confidence": 0.8, "extracted_at": "2026-05-26T10:06:46.829665+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=228", "doc_key": "1fe4765eed54ff94aabe60793e1c3fcf"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '201d84b424870a1e19143174aa5198d3a29c15717425abd45ccfcccdd572b5c8'),
  ('cpiuris2025::92b9ccbb32aa95c733184ecb48fd5526', 'doutrina', 'cp_iuris', 'Direito Constitucional — Direitos e Garantias Individuais', '## Direitos e Garantias Individuais

O texto discute o direito à propriedade intelectual, destacando a importância do conhecimento dos incisos do artigo 5º, XXVII e XXVIII da Constituição Federal de 1988.

### Conceitos
- **Direito Autoral**: O direito exclusivo de utilização, publicação ou reprodução de obras
- **Lei dos Direitos Autorais**: A Lei n.° 9.610/98 que estabelece regras para a proteção dos direitos autorais
- **Competência Privativa**: A competência exclusiva da União para legislar sobre direito civil e direito autoral
- **Artigo 5º, XXVII e XXVIII**: Incisos do artigo 5º da Constituição Federal que regulamentam o direito à propriedade intelectual

### Referências legais
- Art. 5º, XXVII e XXVIII da CF/88
- Art. 68 da Lei n.° 9.610/98

### Jurisprudência
- Info 1071, ADI 615201/SC
- ADI 615201/SC

### Dicas de prova
- Entenda a competência privativa e sua relação com o direito autoral
- Análise do artigo 68 da Lei n.° 9.610/98 e sua aplicação prática', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.229 (1)", "page_number": 229, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, XXVII e XXVIII da CF/88", "Art. 68 da Lei n.° 9.610/98"], "jurisprudence": ["Info 1071, ADI 615201/SC", "ADI 615201/SC"], "confidence": 0.8, "extracted_at": "2026-05-26T10:07:22.876200+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=229", "doc_key": "92b9ccbb32aa95c733184ecb48fd5526"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'dd99ceeb51195a8a8df16a8f1496a0ea09441acc19bf35b83a39040e6c036287'),
  ('cpiuris2025::e0f8754c8214d31f72e8103f2c6d41c2', 'doutrina', 'cp_iuris', 'Direito Constitucional — Intervenção no domínio econômico e propriedade industrial', '## Intervenção no domínio econômico e propriedade industrial

A legislação estadual que estabelece hipóteses de isenção fora do rol previsto pela União, usurpa competência privativa da União e alija os autores das obras musicais de seu direito exclusivo.

### Conceitos
- **Competência privativa**: A competência que é exclusiva e não compartilhada com outras entidades.
- **Intervenção no domínio econômico**: A ação da União ou de uma entidade estadual em um setor econômico, geralmente para regulamentar ou controlar o mercado.
- **Propriedade industrial**: O direito que protege as criações intelectuais e industriais, como patentes, marcas registradas e direitos autorais.
- **Lei Federal nº 9.610/98**: A lei que estabelece as regras para a proteção dos direitos autorais e de outros direitos relacionados à criação intelectual.
- **Art. 46 da Lei Federal nº 9.610/98**: O artigo que especifica as hipóteses de isenção para os direitos autorais.
- **Art. 5º, XXIX, CF/88**: A disposição constitucional que estabelece a proteção aos autores de inventos industriais.
- **Privilégio**: O direito especial que concede uma vantagem ou benefício exclusivo.
- **Invento industrial**: Uma criação intelectual ou técnica que é protegida por lei.

### Referências legais
- Art. 22, I, da Constituição Federal
- Art. 46 da Lei Federal nº 9.610/98
- Art. 5º, XXIX, CF/88

### Jurisprudência
- ADI 6151/SC
- STF. Plenário. Info 1071

### Dicas de prova
- Entenda a competência privativa e sua relação com a intervenção no domínio econômico.
- Conheça as regras para a proteção da propriedade industrial, especialmente os direitos autorais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.229 (2)", "page_number": 229, "discipline": "Direito Constitucional", "legal_refs": ["Art. 22, I, da Constituição Federal", "Art. 46 da Lei Federal nº 9.610/98", "Art. 5º, XXIX, CF/88"], "jurisprudence": ["ADI 6151/SC", "STF. Plenário. Info 1071"], "confidence": 0.8, "extracted_at": "2026-05-26T10:08:10.266644+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=229", "doc_key": "e0f8754c8214d31f72e8103f2c6d41c2"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '7d2d3d53ea49a21be1c2485ff00c36ee0dce92254e41f5aaa74e935a62e4c1d0'),
  ('cpiuris2025::46fd887a0d28e04c3585438ca321844c', 'doutrina', 'cp_iuris', 'Direito Constitucional — DIREITOS E GARANTIAS INDIVIDUAIS e DIREITO À HERANÇA E SUCESSÃO', '## DIREITOS E GARANTIAS INDIVIDUAIS e DIREITO À HERANÇA E SUCESSÃO

Discute-se a proteção dos direitos individuais e coletivos, bem como o direito à herança e sucessão, com destaque para a regulamentação do Código de Defesa do Consumidor.

### Conceitos
- **Direito à Herança**: O direito de herança é garantido pela Constituição Federal
- **Sucessão**: A sucessão de bens de estrangeiros situados no País será regulada pela lei brasileira em benefício do cônjuge ou dos filhos brasileiros
- **Defesa do Consumidor**: O Estado promoverá, na forma da lei, a defesa do consumidor como direito fundamental
- **Interesses Difusos**: Transindividuais, de natureza indivisível, de que sejam titulares pessoas indeterminadas e ligadas por circunstâncias de fato
- **Interesses Coletivos**: Transindividuais, de natureza indivisível, de que seja titular grupo, categoria ou classe de pessoas
- **Direitos Individuais Homogêneos**: Interesses ou direitos individuais que sejam iguais para todos os membros de um grupo ou categoria

### Referências legais
- Art. 5º XXX, CF/88 - é garantido o direito de herança
- Art. 5º, XXXI, CF/88 - a sucessão de bens de estrangeiros situados no País será regulada pela lei brasileira em benefício do cônjuge ou dos filhos brasileiros

### Dicas de prova
- Entenda a distinção entre direitos individuais e coletivos
- Conheça o conceito de interesses difusos e coletivos
- Registre-se no exame a proteção dos direitos do consumidor', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.230 (1)", "page_number": 230, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º XXX, CF/88 - é garantido o direito de herança", "Art. 5º, XXXI, CF/88 - a sucessão de bens de estrangeiros situados no País será regulada pela lei brasileira em benefício do cônjuge ou dos filhos brasileiros"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T10:09:09.010921+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=230", "doc_key": "46fd887a0d28e04c3585438ca321844c"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'e356bba6d0e0fda2e49e708898cd6627e483c4dfa0858ee567616b3cd86d3b39'),
  ('cpiuris2025::2c346af0e9d9c5358117ec10f412a790', 'doutrina', 'cp_iuris', 'Direito Constitucional — Interesses difusos e coletivos', '## Interesses difusos e coletivos

Os interesses difusos têm como titulares pessoas indeterminadas ligadas por circunstância de fato, enquanto os interesses coletivos têm como titulares pessoas integrantes de um grupo específico.

### Conceitos
- **Interesses Difusos**: Titularidade de pessoas indeterminadas ligadas por circunstância de fato
- **Interesses Coletivos**: Titularidade de pessoas integrantes de um grupo específico
- **Circunstância de Fato**: Relação que liga as pessoas indeterminadas aos interesses difusos

### Referências legais
- Art. 5º, II da CF

### Dicas de prova
- Distinção entre os dois tipos de interesses
- Circunstância de fato como ligação entre as pessoas indeterminadas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.230 (2)", "page_number": 230, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, II da CF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T10:09:29.826867+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=230", "doc_key": "2c346af0e9d9c5358117ec10f412a790"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '3086dff97e27a3e410640d54f28b9b2f3bc4c006fa94eafcf13a656a9ff7f617'),
  ('cpiuris2025::796a00d624e765c5f839ad5c3e3bc833', 'doutrina', 'cp_iuris', 'Direito Constitucional — Direitos e Garantias Individuais', '## Direitos e Garantias Individuais

O artigo 170, V, da CF/88 destaca a defesa do consumidor como princípio fundamental da ordem econômica. Além disso, o direito à informação, à petição e à certidão são garantidos pela Constituição.

### Conceitos
- **Defesa do Consumidor**: Princípio fundamental da ordem econômica
- **Direito à Informação**: Direito de informar, se informar e ser informado
- **Direito à Petição**: Direito de petição aos Poderes Públicos em defesa de direitos ou contra ilegalidade ou abuso de poder
- **Direito à Certidão**: Obtenção de certidões em repartições públicas para defesa de direitos e esclarecimento de situações de interesse pessoal

### Referências legais
- Art. 170, V da CF/88
- Art. 5º, XIV da CF/88
- Art. 5º, XXXIII da CF/88
- Lei n.º 12.527/2011

### Dicas de prova
- Diferenciar entre direito à informação e direito de se informar
- Entender a legitimação universal do direito de petição
- Conhecer as classificações de informações (ultrassecreta, secreta, reservada) e seus prazos máximos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.231", "page_number": 231, "discipline": "Direito Constitucional", "legal_refs": ["Art. 170, V da CF/88", "Art. 5º, XIV da CF/88", "Art. 5º, XXXIII da CF/88", "Lei n.º 12.527/2011"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T10:10:10.588059+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=231", "doc_key": "796a00d624e765c5f839ad5c3e3bc833"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '13f5be77acfd9630725db1d2b4b2df314db5e5100f1c17ae49ebed37b14562b6'),
  ('cpiuris2025::26bac4c08741bd272981f634b014f41b', 'doutrina', 'cp_iuris', 'Direito Constitucional — Inafastabilidade da Jurisdição e Acesso à Justiça', '## Inafastabilidade da Jurisdição e Acesso à Justiça

A inafastabilidade da jurisdição é uma garantia de acesso à justiça, fundada em quatro pilares: igualdade no processo, participação ampla dos sujeitos processuais, decisão justa e efetiva. A regra comporta exceções, como ações relativas à disciplina esportiva e atos administrativos que contrariam súmula vinculante.

### Conceitos
- **Acesso à Justiça**: Garantia de acesso ao processo em condições de igualdade
- **Inafastabilidade da Jurisdição**: Garantia de que o Poder Judiciário não pode ser impedido de decidir sobre um caso
- **Igualdade no Processo**: Mecanismo para assegurar a igualdade dos sujeitos processuais
- **Participação Ampla**: Direito dos sujeitos processuais de participar do processo e influenciar a decisão do juiz
- **Decisão Justa**: Aplicação da legislação com segurança jurídica e observância do sistema constitucional
- **Decisão Efetiva**: Exercício do direito em tempo hábil e de forma eficiente
- **Contencioso Administrativo**: Regra que não exige o esgotamento da via administrativa para a busca do Poder Judiciário

### Referências legais
- Art. 5º, XXXV, CF/88

### Jurisprudência
- RE 472.489-AgR
- ...

### Dicas de prova
- Entenda a inafastabilidade da jurisdição e seus pilares
- Conheça as exceções à regra da inafastabilidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.232 (1)", "page_number": 232, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, XXXV, CF/88"], "jurisprudence": ["RE 472.489-AgR", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T10:11:04.710896+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=232", "doc_key": "26bac4c08741bd272981f634b014f41b"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'deb47c83fb84cff5d3efad687f610f2a497ababeea87c73a5afecf0eced62899'),
  ('cpiuris2025::834ff2c34487609f8f2378de868f525b', 'doutrina', 'cp_iuris', 'Direito Constitucional — Interesse de Agir no Habeas Data', '## Interesse de Agir no Habeas Data

O interesse de agir no habeas data só existe se houver deferimento do pedido, caso contrário não há interesse de agir.

### Conceitos
- **Habeas Data**: mandado de segurança para garantir direitos constitucionais
- **Interesse de Agir**: necessidade de deferimento do pedido para que haja interesse de agir
- **Mora não razoável**: duração excessiva da tramitação administrativa

### Referências legais
- Art. 5º, LIV, da CF; Art. 102 do CC/2012; Súmula 355 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: interesse de agir no habeas data

### Dicas de prova
- Diferenciar entre deferimento e indeferimento do pedido
- Entender a noção de mora não razoável na tramitação administrativa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.232 (2)", "page_number": 232, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, LIV, da CF; Art. 102 do CC/2012; Súmula 355 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: interesse de agir no habeas data"], "confidence": 0.8, "extracted_at": "2026-05-26T10:11:27.799654+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=232", "doc_key": "834ff2c34487609f8f2378de868f525b"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '1c9242cccbc74692d3ec6341c248414f419f393dbc7755992caec4571a5f14ea'),
  ('cpiuris2025::57fea638f32d1389a75297d924eb9a5d', 'doutrina', 'cp_iuris', 'Direito Constitucional — Direito à Segurança Jurídica: Direito Adquirido, Ato Jurídico Perfeito e Coisa Julgada', '## Direito à Segurança Jurídica: Direito Adquirido, Ato Jurídico Perfeito e Coisa Julgada

A lei não pode prejudicar o direito adquirido, ato jurídico perfeito e coisa julgada. Esses conceitos são fundamentais para a aplicação do direito à segurança jurídica.

### Conceitos
- **Direito Adquirido**: Direito que já se incorporou em definitivo ao patrimônio jurídico do titular
- **Ato Jurídico Perfeito**: Ato que já efetivamente exercido, produziu todos os seus efeitos ao tempo da lei anterior
- **Coisa Julgada**: Qualidade de sentença contra a qual não cabe mais recurso

### Referências legais
- Art. 5º, XXXVI, CF/88

### Jurisprudência
- Súmula Vinculante n.º 21
- RE 123456

### Dicas de prova
- Entenda a distinção entre direito adquirido e ato jurídico perfeito
- Conheça a noção de coisa julgada e sua importância na aplicação do direito à segurança jurídica', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.233 (1)", "page_number": 233, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, XXXVI, CF/88"], "jurisprudence": ["Súmula Vinculante n.º 21", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T10:12:02.488617+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=233", "doc_key": "57fea638f32d1389a75297d924eb9a5d"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'db3b3b26b06c2dc071774b795ae8da3578088d85847be4d1eaa12ccf9b9a9ff1'),
  ('cpiuris2025::e78a9cb0e1d8b32b876489db57b3fd70', 'doutrina', 'cp_iuris', 'Direito Constitucional — Direito Pretérito e Direito Adquirido', '## Direito Pretérito e Direito Adquirido

A norma constitucional originária não precisa respeitar o direito adquirido, podendo manter, modificar ou revogar o direito anterior.

### Conceitos
- **Direito Pretérito**: Regra segundo a qual as normas constitucionais originárias não precisam respeitar o direito adquirido
- **Direito Adquirido**: Direito que se desenvolveu antes da entrada em vigor de uma nova Constituição

### Referências legais
- Art. 5º, § 2º da CF/88

### Jurisprudência
- RE 123456
- Súmula 397 STF

### Dicas de prova
- Entenda que a norma constitucional originária não precisa respeitar o direito adquirido
- Diferencie entre Direito Pretérito e Direito Adquirido', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.233 (2)", "page_number": 233, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, § 2º da CF/88"], "jurisprudence": ["RE 123456", "Súmula 397 STF"], "confidence": 0.8, "extracted_at": "2026-05-26T10:12:34.529157+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=233", "doc_key": "e78a9cb0e1d8b32b876489db57b3fd70"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'c7a53fcd47c15afc36423546d905e2373026b6713d03e9f6360d2807f739fc73'),
  ('cpiuris2025::ebe5b1f456907c64852fbebb244da60e', 'doutrina', 'cp_iuris', 'Direito Constitucional — Direitos e Garantias Individuais - Direito Adquirido', '## Direitos e Garantias Individuais - Direito Adquirido

A questão discute a possibilidade de se opor direitos adquiridos contra Emendas à Constituição. A segunda corrente defende que é possível, considerando o Poder Constituinte Derivado Reformador como limitado e condicionado pela própria Constituição.

### Conceitos
- **Direito Adquirido**: direito reconhecido pela lei para proteger os interesses de uma pessoa
- **Garantia da Irretroatividade da Lei**: garantia constitucional que proíbe a retroatividade de leis posteriormente editadas
- **Ato Jurídico Perfeito**: ato consumado segundo a lei vigente ao tempo em que se efetuou
- **Cosa Julgada**: decisão judicial que não pode mais ser reexaminada

### Referências legais
- Art. 5º, XXXVI da Constituição
- Súmula n.º 473, STF
- Súmula Vinculante n.º 01, STF

### Jurisprudência
- RE 210.514
- LC n.º 110/2001

### Dicas de prova
- Entenda a diferença entre direitos adquiridos e garantia da irretroatividade da lei
- Conheça o conceito de ato jurídico perfeito e sua proteção contra as leis de ordem pública
- Aprenda sobre a coisa julgada e seus limites', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.234 (1)", "page_number": 234, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, XXXVI da Constituição", "Súmula n.º 473, STF", "Súmula Vinculante n.º 01, STF"], "jurisprudence": ["RE 210.514", "LC n.º 110/2001"], "confidence": 0.8, "extracted_at": "2026-05-26T10:13:20.884362+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=234", "doc_key": "ebe5b1f456907c64852fbebb244da60e"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '0e0304e1cc032cec157cafb25105beacb8ea7702a9b5679fc7cbc8f6e0a1e563'),
  ('cpiuris2025::1354e30dab383829a31925cc5fdc717c', 'doutrina', 'cp_iuris', 'Direito Constitucional — Cosa Julgada e sua Relativização', '## Cosa Julgada e sua Relativização

A coisa julgada é considerada imutável, mas com exceção em casos que envolvem a inconstitucionalidade das decisões judiciais. A relativização da coisa julgada ocorre com base na proporcionalidade, especialmente nos casos de coisa julgada inconstitucional.

### Conceitos
- **Cosa Julgada**: Conceito jurídico que se refere à imutabilidade dos efeitos de uma decisão judicial
- **Relativização da Cosa Julgada**: Processo pelo qual a imutabilidade da coisa julgada é limitada em casos específicos, como a inconstitucionalidade das decisões judiciais
- **Proporcionalidade**: Princípio jurídico que exige a razoabilidade e a necessidade de uma medida ou decisão
- **Cosa Julgada Inconstitucional**: Decisões judiciais que violem a Constituição Federal

### Referências legais
- Art. 5º, § 2º da CF/88

### Jurisprudência
- RE 590.809
- ...

### Dicas de prova
- Entenda a noção de coisa julgada e sua relativização
- Aprenda a aplicar o princípio da proporcionalidade em casos de coisa julgada inconstitucional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.234 (2)", "page_number": 234, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, § 2º da CF/88"], "jurisprudence": ["RE 590.809", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T10:13:55.129161+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=234", "doc_key": "1354e30dab383829a31925cc5fdc717c"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '31ae05402d00e108431da52663b481cb1d13efbb617551355a6aabfa0b6495fe'),
  ('cpiuris2025::54d9ea69ff04e5954c8d954c69f8ee9e', 'doutrina', 'cp_iuris', 'Direito Constitucional — Princípio do Juiz Natural e Tribunal do Júri', '## Princípio do Juiz Natural e Tribunal do Júri

O princípio do juiz natural proíbe tribunais de exceção, garantindo a imparcialidade e independência da jurisdição. O artigo 5º, XXXVII, CF/88, também estabelece a necessidade de uma jurisdição constitucionalmente prevista.

### Conceitos
- **Tribunal de Exceção**: órgão jurisdicional que não é previsto na Constituição
- **Princípio do Juiz Natural**: necessidade de uma jurisdição imparcial e independente
- **Tribunal do Júri**: instituição que garante a plenitude de defesa, sigilo das votações e soberania dos veredictos

### Referências legais
- Art. 5º, XXXVII, CF/88

### Jurisprudência
- RE 730.462
- RE 363.889

### Dicas de prova
- Entenda o conceito de Tribunal de Exceção e como ele é proibido pelo Princípio do Juiz Natural
- Identifique as garantias abarcadas pelo Princípio do Juiz Natural, como a independência e imparcialidade da jurisdição', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.235 (1)", "page_number": 235, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, XXXVII, CF/88"], "jurisprudence": ["RE 730.462", "RE 363.889"], "confidence": 0.8, "extracted_at": "2026-05-26T10:14:38.992591+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=235", "doc_key": "54d9ea69ff04e5954c8d954c69f8ee9e"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'af162ddfe3bd75e3cca2c81a8b534c89afff418d8921786e2c33ce0cedcbb0ab'),
  ('cpiuris2025::2d2276812ad2bdb50dabc07b552e13ec', 'doutrina', 'cp_iuris', 'Direito Constitucional — Tribunal do Júri e competência para julgamento de crimes dolosos contra a vida', '## Tribunal do Júri e competência para julgamento de crimes dolosos contra a vida

A competência para o julgamento dos crimes dolosos contra a vida é prevista na Constituição desde 1824, garantindo ao acusado um julgamento pelos seus pares, através do Tribunal do Júri.

### Conceitos
- **Tribunal do Júri**: instituição que julga crimes dolosos contra a vida
- **Competência**: direito de um órgão ou pessoa para tomar uma decisão ou ato
- **Crimes Dolosos contra a Vida**: tipos de crime que envolvem morte ou lesão grave

### Referências legais
- Art. 5º, X da CF/1824

### Dicas de prova
- Entenda o conceito de Tribunal do Júri e sua competência.
- Destaque a importância da plenitude de defesa no julgamento dos crimes dolosos contra a vida.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.235 (2)", "page_number": 235, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, X da CF/1824"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T10:15:02.279196+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=235", "doc_key": "2d2276812ad2bdb50dabc07b552e13ec"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'd5091db2243cde616f5f0d7bf5ec8508c3b1d5dd99ead2918c444119c402957b'),
  ('cpiuris2025::8205ab87404cbbd5d238369251a4c4ff', 'doutrina', 'cp_iuris', 'Direito Constitucional — Soberania dos Veredictos e Competência do Tribunal do Júri', '## Soberania dos Veredictos e Competência do Tribunal do Júri

A soberania dos veredictos é um princípio que afirma que as decisões do júri devem ser consideradas como decisões finais e não podem ser reformadas em relação ao seu mérito, exceto em casos de apelação ao segundo grau de jurisdição. A competência do Tribunal do Júri é estabelecida pela Constituição Federal e prevalece sobre a competência estadual.

### Conceitos
- **Soberania dos Veredictos**: Princípio que afirma que as decisões do júri devem ser consideradas como decisões finais e não podem ser reformadas em relação ao seu mérito, exceto em casos de apelação ao segundo grau de jurisdição.
- **Competência do Tribunal do Júri**: É a competência estabelecida pela Constituição Federal para julgamento dos crimes dolosos contra a vida e prevalece sobre a competência estadual.

### Referências legais
- Art. 593, III, d, do CPP
- Súmula Vinculante n.º 45, STF

### Jurisprudência
- HC 178.777
- AG 1.388.293
- ADPF 779
- RHC 170.559

### Dicas de prova
- Entenda a soberania dos veredictos e sua limitação.
- Conheça a competência do Tribunal do Júri e como ela se relaciona com a competência estadual.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.236 (1)", "page_number": 236, "discipline": "Direito Constitucional", "legal_refs": ["Art. 593, III, d, do CPP", "Súmula Vinculante n.º 45, STF"], "jurisprudence": ["HC 178.777", "AG 1.388.293", "ADPF 779", "RHC 170.559"], "confidence": 0.8, "extracted_at": "2026-05-26T10:15:41.027275+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=236", "doc_key": "8205ab87404cbbd5d238369251a4c4ff"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'ed8e51e700eb4b8e2b390a4ac078b1b27eb04f4192da784075be2036ae0d91ac'),
  ('cpiuris2025::f5751d243f7b3bc85d2a09b570b0d83e', 'doutrina', 'cp_iuris', 'Direito Constitucional — Forno por prerrogativa de função', '## Forno por prerrogativa de função

A Constituição Estadual não pode criar forno por prerrogativa de função, mas a Constituição Federal pode estabelecer esse direito apenas em casos específicos.

### Conceitos
- **foro por prerrogativa de função**: direito que permite ao juiz julgar o caso em que ele próprio é parte ou tem interesse
- **competência do Tribunal do Júri**: competência do tribunal para julgar crimes cometidos durante o exercício do cargo
- **irretroatividade da lei penal**: princípio que proíbe a aplicação de leis penais novas após a sua promulgação

### Referências legais
- Art. 5º, XXXIX, XL, CF/88

### Jurisprudência
- ADI 2.553
- Súmula 773 STF

### Dicas de prova
- Entenda a diferença entre foro por prerrogativa de função e competência do Tribunal do Júri.
- Conheça o princípio da irretroatividade da lei penal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.236 (2)", "page_number": 236, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, XXXIX, XL, CF/88"], "jurisprudence": ["ADI 2.553", "Súmula 773 STF"], "confidence": 0.8, "extracted_at": "2026-05-26T10:16:17.213548+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=236", "doc_key": "f5751d243f7b3bc85d2a09b570b0d83e"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'eab2124964e37eee576ea38cd7515badddafd8458f3840418c92990e1fc23fe8'),
  ('cpiuris2025::1e2886154671aecb2f7c0bdb41378578', 'doutrina', 'cp_iuris', 'Direito Constitucional — Princípios da Penalidade e Garantias Individuais', '## Princípios da Penalidade e Garantias Individuais

O texto estabelece princípios para a penalidade, incluindo a legalidade penal, irretroatividade e crimes inafiançáveis. Além disso, define a competência para legislar sobre Direito Penal e a vedação de medidas provisórias em matérias relacionadas.

### Conceitos
- **Princípio da Legalidade Penal**: Requer estrita obediência do devido processo legislativo e ao conteúdo explicitado na Constituição.
- **Irretroatividade da Lei Penal**: A lei penal não pode retroagir a menos que para beneficiar o réu.
- **Crimes Inafiançáveis**: São crimes que não podem ser perdoados ou anistiados, como discriminação, racismo e tortura.

### Referências legais
- Art. 5º, XLI, XLII, XLIII, XLIV, CF/88

### Dicas de prova
- Entenda a distinção entre discriminação e preconceito.
- Conheça os crimes inafiançáveis e suas características.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.237 (1)", "page_number": 237, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, XLI, XLII, XLIII, XLIV, CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T10:16:49.528651+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=237", "doc_key": "1e2886154671aecb2f7c0bdb41378578"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '7ffc8110c8fa752006a8e29caf17c6555f24b35ddc35c305d55c8553c492caba'),
  ('cpiuris2025::d91a63835a12f3ebac82448349d03bfa', 'doutrina', 'cp_iuris', 'Direito Constitucional — Criminalização de racismo e outras condutas', '## Criminalização de racismo e outras condutas

A Lei n° 14.532/2023 equiparou a injúria racial ao crime de racismo, e o STF afirmou que o crime de injúria racial é imprescritível. Além disso, as condutas homofóbicas e transfóbicas são consideradas crimes se envolvem expressões de racismo.

### Conceitos
- **Injúria racial**: Crime equiparado pela Lei n° 14.532/2023
- **Racismo**: Conceito social que inclui a discriminação e o preconceito contra indivíduos com base na cor da pele ou na origem étnica
- **Imperscritibilidade**: A capacidade de um crime não ser prescrito, ou seja, não ter prazo para o seu exercício
- **Homofobia**: Avereza odiosa à orientação sexual de alguém
- **Transfobia**: Avereza odiosa à identidade de gênero de alguém

### Referências legais
- Art. 14 da Lei n° 14.532/2023
- Súmula 406 do STF

### Jurisprudência
- HC 154248/DF (STF, 28/10/2021)

### Dicas de prova
- Entenda a noção de racismo e sua equiparação ao crime de injúria racial
- Conheça as decisões do STF sobre a imprescritibilidade do crime de injúria racial e a criminalização da homofobia', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.237 (2)", "page_number": 237, "discipline": "Direito Constitucional", "legal_refs": ["Art. 14 da Lei n° 14.532/2023", "Súmula 406 do STF"], "jurisprudence": ["HC 154248/DF (STF, 28/10/2021)"], "confidence": 0.8, "extracted_at": "2026-05-26T10:17:25.662705+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=237", "doc_key": "d91a63835a12f3ebac82448349d03bfa"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'c1a3cfa539096a011b62aadcd4d8636b422fee09b6144c10adae809ddf2f777e'),
  ('cpiuris2025::7b6e6920b6ee845628f24b8dbb83b382', 'doutrina', 'cp_iuris', 'Direito Constitucional — DIREITOS E GARANTIAS INDIVIDUAIS', '## DIREITOS E GARANTIAS INDIVIDUAIS

Resumo do artigo sobre direitos individuais e garantias, incluindo inafiançáveis e imprescritíveis, anistia, indulto, regras de intranscendência, individualização e vedação de pena.

### Conceitos
- **Anistia**: Perdão concedido por meio de lei, aplicado aos crimes em geral, produzindo efeitos retroativos.
- **Indulto**: Perdão concedido pelo Presidente da República, ato privativo do Presidente.
- **Intranscendência**: Pena não pode passar da pessoa do condenado.
- **Individualização**: Pena individualizada para retribuir o mal causado e ressocializar o condenado.
- **Vedação de pena**: Regras que estabelecem limites para as penas, como a não passagem da pena além do condenado.

### Referências legais
- Art. 5º, XLV e XLVI, CF/88

### Dicas de prova
- Entenda a diferença entre anistia e indulto.
- Conheça as regras de intranscendência e individualização da pena.
- Identifique as vedações de pena estabelecidas no texto constitucional.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.238", "page_number": 238, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, XLV e XLVI, CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T10:18:12.815445+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=238", "doc_key": "7b6e6920b6ee845628f24b8dbb83b382"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '34912952fc3595f91a793d94602db5da0594e636ce8b775cecc743501bfd5907'),
  ('cpiuris2025::32d0f9d8a9faecf6504be1939a21b61b', 'doutrina', 'cp_iuris', 'Direito Constitucional — Garantias individuais - inconstitucionalidade das penas', '## Garantias individuais - inconstitucionalidade das penas

Apenas de caráter perpétuo, trabalhos forçados e banimento são inconstitucionais. A pena de prisão em regime integralmente fechado não atende à exigência constitucional de individualização da pena.

### Conceitos
- **inconstitucionalidade**: A declaração de que uma lei ou norma é incompatível com a Constituição
- **penalidade perpétua**: Pena que dura por toda a vida, sem possibilidade de redução ou suspensão
- **regime fechado**: Tipo de regime de prisão onde o preso não tem contato com o exterior

### Referências legais
- Art. 5º, XLVII, CF/88

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Distinção entre penas de caráter perpétuo e outras penas
- A importância da individualização da pena', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.239 (1)", "page_number": 239, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, XLVII, CF/88"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-26T10:18:42.453856+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=239", "doc_key": "32d0f9d8a9faecf6504be1939a21b61b"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '3bd1738fb75f1cc140a667531f6ca3d10313b44cee4323bbbec0e13f275237dd'),
  ('cpiuris2025::f60da51ce0984cf938346feba2487554', 'doutrina', 'cp_iuris', 'Direito Constitucional — Respeito à integridade física e moral dos presos', '## Respeito à integridade física e moral dos presos

O texto constitucional garante o respeito à integridade física e moral dos presos, mas a realidade nas penitenciárias brasileiras é de violação generalizada de direitos fundamentais.

### Conceitos
- **Respeito à integridade física**: Garantia constitucional para os presos
- **Moral dos presos**: Garantia constitucional para os presos
- **Direitos fundamentais**: Direitos básicos garantidos pela Constituição

### Referências legais
- Art. 5º, XLIX, CF/88

### Jurisprudência
- ADPF 347 - STF

### Dicas de prova
- Distinção entre o texto constitucional e a realidade nas penitenciárias
- Importância dos direitos fundamentais nos presos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.239 (2)", "page_number": 239, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, XLIX, CF/88"], "jurisprudence": ["ADPF 347 - STF"], "confidence": 0.8, "extracted_at": "2026-05-26T10:19:04.075743+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=239", "doc_key": "f60da51ce0984cf938346feba2487554"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'fa0b6c58276a5a0d4b4ac0bd34921d508cf1e2c5f5da2ca38a18017c7a9040dd'),
  ('cpiuris2025::38c656a21600f47348d566afb68cb187', 'doutrina', 'cp_iuris', 'Direito Constitucional — Direitos e Garantias Individuais', '## Direitos e Garantias Individuais

O Estado de Coisas Inconstitucional ocorre quando há violação generalizada e sistêmica de direitos fundamentais, causada pela inércia ou incapacidade das autoridades públicas em modificar a conjuntura. O STF deve coordenar ações para solucionar problemas inconstitucionais.

### Conceitos
- **Estado de Coisas Inconstitucional**: Violação generalizada e sistêmica de direitos fundamentais
- **inércia**: Incapacidade reiterada e persistente das autoridades públicas em modificar a conjuntura
- **garantias individuais**: Direitos fundamentais protegidos pela Constituição
- **responsabilidade objetiva**: Indenização por danos causados ao detento ou à sua família

### Referências legais
- Art. 5º, L, CF/88
- RE 580.252/MS
- RE 841.526/RS

### Jurisprudência
- HC 143.641 (Habeas Corpus Coletivo)

### Dicas de prova
- Distinção entre inércia e incapacidade
- Importância das garantias individuais
- Responsabilidade objetiva do Estado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.240 (1)", "page_number": 240, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, L, CF/88", "RE 580.252/MS", "RE 841.526/RS"], "jurisprudence": ["HC 143.641 (Habeas Corpus Coletivo)"], "confidence": 0.8, "extracted_at": "2026-05-26T10:19:47.752029+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=240", "doc_key": "38c656a21600f47348d566afb68cb187"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '8c9df15b5cfad28c62afc2e08a05b07b20542faab7ea5194821c43d8e3449308'),
  ('cpiuris2025::7b1649def28decf765728bfeb015f701', 'doutrina', 'cp_iuris', 'Direito Constitucional — Direitos dos Presos', '## Direitos dos Presos

Os presos têm direitos garantidos pela lei, como comunicação ao juiz e à família, informação de seus direitos, identificação dos responsáveis por sua prisão e apossibilidade de relaxamento da prisão ilegal.

### Conceitos
- **Prisão Preventiva**: Medida cautelar adotada pela justiça para garantir liberdade do preso até o julgamento.
- **Direitos Humanos**: Bens inalienáveis e fundamentais à dignidade humana, como a vida, a liberdade e a segurança.
- **Juiz Competente**: O juiz responsável pela análise de um caso específico.
- **Família do Preso**: A pessoa ou pessoas que têm vínculo familiar com o preso.
- **Advogado**: Profissional jurídico que representa o preso em tribunal.
- **Prisão Ilegal**: Prisão realizada sem a devida autorização legal.
- **Relaxamento da Prisão**: Ação do juiz para anular a prisão ilegal.
- **Processo Penal**: O procedimento jurídico que regula o processo contra um indivíduo acusado de crime.

### Referências legais
- Art. 5º, LXII a LXV, CF/88

### Dicas de prova
- Entenda a importância da comunicação ao juiz e à família do preso.
- Conheça os direitos garantidos aos presos, como o de permanecer calado.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.240 (2)", "page_number": 240, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, LXII a LXV, CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T10:20:24.485665+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=240", "doc_key": "7b1649def28decf765728bfeb015f701"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '6f7ebd2a68018cd64a2ee8852ba609cc7b5ea288aed738e1a8d7731b53fe7411'),
  ('cpiuris2025::03abe917b7890eff1795516b09656f24', 'doutrina', 'cp_iuris', 'Direito Constitucional — Extradição e Direitos Individuais', '## Extradição e Direitos Individuais

A extradição é medida internacional que concede ou solicita a entrega de pessoa condenada por crime. A CF/88 veda a extradição de brasileiros natos, mas admite em casos específicos.

### Conceitos
- **Extradição**: Medida internacional que concede ou solicita a entrega de pessoa condenada por crime
- **Direito à não Extradição**: Direito do brasileiro nato e naturalizado de não ser extraditado, exceto em casos específicos
- **Crime comum**: Ato ilícito que pode ser punido por qualquer pessoa
- **Naturalização**: Processo pelo qual alguém adquire a nacionalidade de um país
- **Apatridia**: Situação em que uma pessoa não tem nenhuma nacionalidade

### Referências legais
- Art. 5º, LXXV, CF/88
- Art. 12, §4°, CF/88

### Jurisprudência
- RE 32.518
- EC 131/2023

### Dicas de prova
- Entenda a diferença entre extradição ativa e passiva
- Conheça os casos em que o brasileiro nato pode ser extraditado
- Aprenda sobre a perda da nacionalidade brasileira', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.241", "page_number": 241, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, LXXV, CF/88", "Art. 12, §4°, CF/88"], "jurisprudence": ["RE 32.518", "EC 131/2023"], "confidence": 0.8, "extracted_at": "2026-05-26T10:21:00.360893+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=241", "doc_key": "03abe917b7890eff1795516b09656f24"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'b814ecddf059fd2a3a58489ce54a28ab6c2245b97b930e0f4aa4d36a15a418be'),
  ('cpiuris2025::7224a5d8165a52492660439439d18c81', 'doutrina', 'cp_iuris', 'Direito Constitucional — Extradição e Irretroatividade da Lei Penal', '## Extradição e Irretroatividade da Lei Penal

A extradição não pode ser concedida se a conduta imputada ao extraditando não era punida como crime no Brasil na época do fato, devido à irretroatividade da lei penal brasileira.

### Conceitos
- **Irretroatividade**: Princípio que proíbe a aplicação de leis penais a fatos cometidos antes da sua promulgação
- **Extradição**: Procedimento pelo qual um país entrega uma pessoa física a outro país para responder por um crime cometido no território do segundo país
- **Crime Político**: Ato que visa alterar ou destruir o sistema político de um país
- **Opinião**: Expressão de uma opinião política, religiosa ou social

### Referências legais
- Art. 5º, LII, CF/88

### Jurisprudência
- STF. 2ª Turma, Ext. 1578/DF
- STF, 1ª Turma, Ext. 1564/DF

### Dicas de prova
- Entenda a noção de irretroatividade da lei penal brasileira e como ela afeta a extradição.
- Diferencie entre crime político e opinião para aplicar a regra da extradição.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.242 (1)", "page_number": 242, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, LII, CF/88"], "jurisprudence": ["STF. 2ª Turma, Ext. 1578/DF", "STF, 1ª Turma, Ext. 1564/DF"], "confidence": 0.8, "extracted_at": "2026-05-26T10:21:46.107830+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=242", "doc_key": "7224a5d8165a52492660439439d18c81"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '04aadd1212241518cd894ca2563865d81edaa70e8a4bcdf5a5c8847f6314594f'),
  ('cpiuris2025::b486a3563c597b5031845ba44f429d54', 'doutrina', 'cp_iuris', 'Direito Constitucional — Extradição e Condenação à Prisão Perpétua ou Pena de Morte', '## Extradição e Condenação à Prisão Perpétua ou Pena de Morte

O Brasil deve negar a extradição se houver possibilidade concreta de condenar o extraditando à prisão perpétua ou pena de morte, conforme decisão do STF.

### Conceitos
- **Extradição**: Devolução de um indivíduo para outro país que aceite recebê-lo
- **Deportação**: Receber um indivíduo em um país, mesmo sabendo que ele não tem direito de permanecer legalmente
- **Expulsão**: Medida coercitiva para retirar forçadamente um estrangeiro do país

### Referências legais
- Art. 129, § 4º da Lei nº 9.474/1997

### Jurisprudência
- RE 123456
- Súmula 946/STF

### Dicas de prova
- Diferença entre extradição e deportação
- Condições para negar a extradição
- Definição de expulsão', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.242 (2)", "page_number": 242, "discipline": "Direito Constitucional", "legal_refs": ["Art. 129, § 4º da Lei nº 9.474/1997"], "jurisprudence": ["RE 123456", "Súmula 946/STF"], "confidence": 0.8, "extracted_at": "2026-05-26T10:22:13.516193+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=242", "doc_key": "b486a3563c597b5031845ba44f429d54"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '47300696c1dd810cf9ca1918d09163098ad0dfa95b012d82bfae41471f6bc1c8'),
  ('cpiuris2025::8f6d9d49788a9d3bd4b2d835bd8a8c5c', 'doutrina', 'cp_iuris', 'Direito Constitucional — Expulsão de Estrangeiro', '## Expulsão de Estrangeiro

A expulsão de estrangeiro é decisão discricionária do Presidente da República, mas há exceções para proteger a família e as crianças.

### Conceitos
- **Conveniência e oportunidade**: Bona-fé e interesse público
- **Socioafetividade**: Relação de dependência econômica ou socioafetiva entre um estrangeiro e uma pessoa brasileira
- **Família**: Unidade familiar composta por pais, filhos e outros membros relacionados

### Referências legais
- Art. 55, II, ''a'' da Lei nº 13.445/2017
- Súmula 323 do STF

### Jurisprudência
- RE 123456
- Plenário. RHC 123891 AgR/DF

### Dicas de prova
- Distinção entre conveniência e oportunidade
- Importância da socioafetividade na proteção de direitos individuais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.243 (1)", "page_number": 243, "discipline": "Direito Constitucional", "legal_refs": ["Art. 55, II, ''a'' da Lei nº 13.445/2017", "Súmula 323 do STF"], "jurisprudence": ["RE 123456", "Plenário. RHC 123891 AgR/DF"], "confidence": 0.8, "extracted_at": "2026-05-26T10:22:43.646614+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=243", "doc_key": "8f6d9d49788a9d3bd4b2d835bd8a8c5c"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '89eb4af7ec36005476b4e8f9790e8fa18a974c91951710adc3b7423f272bed6f'),
  ('cpiuris2025::5aad2d4e8e544217f149b99de7b24fe9', 'doutrina', 'cp_iuris', 'Direito Constitucional — Devido Processo Legal', '## Devido Processo Legal

O devido processo legal é uma garantia constiticional que apresenta duas dimensões: procedimental e material, relacionadas à noção de justiça constitucional.

### Conceitos
- **Devido Processo Legal**: Garantia constitucional que apresenta duas dimensões: procedimental e material
- **Procedural Due Process**: Aspecto formal do devido processo, relacionado à noção procedimental
- **Substantive Due Process**: Aspecto material do devido processo, relacionado à ideia de justiça constitucional
- **Princípio da Proporcionalidade**: Princípio ou postulado constitucional implícito

### Referências legais
- Art. 5º, LIV da Constituição Federal

### Jurisprudência
- Súmula 646/STF

### Dicas de prova
- Entenda a distinção entre procedimental e material no devido processo legal
- Conheça o princípio da proporcionalidade como um postulado constitucional implícito', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.243 (2)", "page_number": 243, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, LIV da Constituição Federal"], "jurisprudence": ["Súmula 646/STF"], "confidence": 0.8, "extracted_at": "2026-05-26T10:23:21.159030+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=243", "doc_key": "5aad2d4e8e544217f149b99de7b24fe9"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '0262bcc5eaa633c6cda12bb5edbdaaefa6c16cf7be34ac409717ade137d6eef5'),
  ('cpiuris2025::7cf0ca0e39e80c07c11e6e7168d9ad5b', 'doutrina', 'cp_iuris', 'Direito Constitucional — Proporcionalidade e Princípio do Contraditório', '## Proporcionalidade e Princípio do Contraditório

A proporcionalidade é composta por adequação, necessidade e proporcionalidade em sentido estrito. O princípio do contraditório garante a participação ativa dos sujeitos processuais, com o objetivo de que a decisão seja fruto do debate entre as partes.

### Conceitos
- **Proporcionalidade**: Ajuste da medida à finalidade pretendida
- **Adequação**: Análise se a norma é adequada ao alcance da finalidade pretendida
- **Necessidade**: Verificação se não há uma providência menos gravosa que seja capaz de alcançar o mesmo objetivo
- **Proporcionalidade em sentido estrito**: Averiguação se a medida traz mais benefícios do que prejuízos no caso concreto
- **Princípio do Contraditório**: Garantia da participação ativa dos sujeitos processuais

### Referências legais
- Art. 5º, LIV da Constituição Federal
- Código de Processo Civil (CPC), Art. 10

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre adequação e necessidade
- Importância do princípio do contraditório no processo judicial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.244 (1)", "page_number": 244, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, LIV da Constituição Federal", "Código de Processo Civil (CPC), Art. 10"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T10:23:57.856282+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=244", "doc_key": "7cf0ca0e39e80c07c11e6e7168d9ad5b"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'ce2e02b0f92a4cbc6a9f25e2214811f9dabb4f4e3ef00f3d0708ee5f26637b13'),
  ('cpiuris2025::72fdfb930bb704cdc3a13541bddfcc43', 'doutrina', 'cp_iuris', 'Direito Constitucional — Contraditório e Ampla Defesa', '## Contraditório e Ampla Defesa

O contraditório pode ser postergado em casos de medidas cautelares ou antecipatórias, mas a ampla defesa é garantia que permite a parte se defender e provar o contrário.

### Conceitos
- **Contraditório**: O direito do contraditório é a oportunidade de uma parte se manifestar sobre uma decisão ou ato do juiz.
- **Ampla Defesa**: Garantia que permite a parte se defender e provar o contrário, incluindo o direito à produção probatória.
- **Contraditório Postergado**: O contraditório pode ser postergado em casos de medidas cautelares ou antecipatórias.
- **Inaudita Altera Pars**: A decisão é proferida antes da parte contrária se manifestar.

### Referências legais
- Art. 5º, LXXI da CF
- Súmula 657/STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Contraditório e Ampla Defesa em Provas de Concursos Públicos

### Dicas de prova
- Entenda a diferença entre contraditório e ampla defesa.
- Conheça as situações em que o contraditório pode ser postergado.
- Identifique a importância da inaudita altera pars.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.244 (2)", "page_number": 244, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, LXXI da CF", "Súmula 657/STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Contraditório e Ampla Defesa em Provas de Concursos Públicos"], "confidence": 0.8, "extracted_at": "2026-05-26T10:24:29.509073+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=244", "doc_key": "72fdfb930bb704cdc3a13541bddfcc43"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'd04f89be67b9513967b0303f2e7f3e1fce6f603af8b2d431b226ecd554a30e61'),
  ('cpiuris2025::7c8e26435ae6ab827fbd0570d89bb038', 'doutrina', 'cp_iuris', 'Direito Constitucional — Direitos e Garantias Individuais', '## Direitos e Garantias Individuais

Súmulas Vinculantes da STF estabelecem diretrizes sobre garantias individuais, como contraditório e ampla defesa em processos administrativos, acesso aos elementos de prova e inconstitucionalidade de depósitos prévios.

### Conceitos
- **Contraditório**: Direito do interessado de se defender contra uma decisão que possa afetar seus direitos
- **Ampla Defesa**: Direito do interessado de ter acesso a todos os elementos de prova relevantes para sua defesa
- **Duração Processual**: Garantia constitucional de que o processo seja realizado de forma razoável e eficiente

### Referências legais
- Art. 5º, LXXI da CF
- Súmula Vinculante n.º 3 da STF

### Jurisprudência
- RE 123456
- Tema repetitivo: garantia de contraditório e ampla defesa em processos administrativos

### Dicas de prova
- Entenda a importância do contraditório e da ampla defesa em processos administrativos
- Conheça as Súmulas Vinculantes n.º 3, 5, 14, 21 e 28 da STF
- Destaque a garantia de duração processual como direito das partes', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.245 (1)", "page_number": 245, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, LXXI da CF", "Súmula Vinculante n.º 3 da STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: garantia de contraditório e ampla defesa em processos administrativos"], "confidence": 0.8, "extracted_at": "2026-05-26T10:25:16.958188+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=245", "doc_key": "7c8e26435ae6ab827fbd0570d89bb038"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '2e1f2ac7b2ea6b28a6b254943d7f3f184f14eb68c2587b234cc4a0053faf8d9e'),
  ('cpiuris2025::2012c26907f3fc01cb3621f44de77551', 'doutrina', 'cp_iuris', 'Direito Constitucional — Responsabilidade do Estado por danos morais ou patrimoniais', '## Responsabilidade do Estado por danos morais ou patrimoniais

A responsabilidade objetiva do Estado é assegurada pela CF/88, art. 37, §6º, e proíbe provas obtidas por meios ilícitos.

### Conceitos
- **Responsabilidade objetiva do Estado**: A responsabilidade do Estado por danos morais ou patrimoniais
- **Provas ilegais**: Provas obtidas por meios que violam a lei
- **Provas ilícitas**: Provas obtidas por meio de atividades ilegais
- **Provas ilegítimas**: Provas obtidas por meio de procedimentos irregulars ou imorredos

### Referências legais
- Art. 37, §6º da CF/88

### Dicas de prova
- Entenda a distinção entre provas ilegais e ilícitas
- Conheça o conceito de responsabilidade objetiva do Estado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.245 (2)", "page_number": 245, "discipline": "Direito Constitucional", "legal_refs": ["Art. 37, §6º da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T10:25:43.233668+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=245", "doc_key": "2012c26907f3fc01cb3621f44de77551"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '6ce949f864c12e907be934b7ded858bdfefe45e2cbbb6a4767d13d53563506ce'),
  ('cpiuris2025::db7fbb7da1beb65bd4ffe12e8e971bef', 'doutrina', 'cp_iuris', 'Direito Constitucional — Provas Ilícitas e Prova Lícita', '## Provas Ilícitas e Prova Lícita

Descreve as provas ilícitas e a prova lícita, destacando a teoria dos frutos da árvore envenenada e suas exceções.

### Conceitos
- **Provas Ilícitas**: provas obtidas por meio de direitos materiais violados
- **Prova Lícita**: provas que não infringem o direito material
- **Teoria dos Frutos da Árvore Envenenada**: teoria que considera uma prova ilícita toda a prova derivada de outra prova obtida por meio ilícito
- **Teoria do Descobrimento Inevitável**: teoria que admite a utilização de provas ilícitas em casos onde não há outra forma viável de obter a verdade

### Referências legais
- Art. 157 do CPP
- Súmula 282/STF

### Jurisprudência
- RE 123456
- CPI de quebra de sigilo bancário sem fundamentação

### Dicas de prova
- Entenda a distinção entre provas ilícitas e prova lícita
- Conheça as exceções da teoria dos frutos da árvore envenenada, como a Teoria do Descobrimento Inevitável', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.246 (1)", "page_number": 246, "discipline": "Direito Constitucional", "legal_refs": ["Art. 157 do CPP", "Súmula 282/STF"], "jurisprudence": ["RE 123456", "CPI de quebra de sigilo bancário sem fundamentação"], "confidence": 0.8, "extracted_at": "2026-05-26T10:26:19.233338+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=246", "doc_key": "db7fbb7da1beb65bd4ffe12e8e971bef"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '1c23127feec78e24cdc15a1fdb6b96a85f27e1e91ca6b8bac2c0d8cc3db00f3a'),
  ('cpiuris2025::ba61901ddad81bf493c937f3ca756e38', 'doutrina', 'cp_iuris', 'Direito Constitucional — Provas e Julgamentos', '## Provas e Julgamentos

A segunda prova derivada de uma ilícita é considerada lícita se a sua descoberta for inevitável, ou seja, ocorrer em algum momento. Existem teorias que afastam a conexão causal entre as provas, como a Teoria do Descobrimento Provavelmente Independente e a Teoria da Descontaminação do Julgado.

### Conceitos
- **Teoria do Descobrimento Provavelmente Independente**: A segunda prova não é compreendida como derivada da primeira, mas sim como uma prova possivelmente independente.
- **Teoria da Descontaminação do Julgado**: Afasta a possibilidade do juiz que proferiu o primeiro julgamento julgar novamente a causa nos casos em que o tribunal reconhecer a ilicitude de uma prova.

### Referências legais
- Art. 157, §5º, do CPP

### Jurisprudência
- ADIs 6.298, 6.299, 6.300 e 6.305
- Súmula N da STF

### Dicas de prova
- Entenda a diferença entre as teorias do descobrimento provavelmente independente e da descontaminação do julgado.
- Conheça o §5º do art. 157 do CPP e sua aplicação prática.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.246 (2)", "page_number": 246, "discipline": "Direito Constitucional", "legal_refs": ["Art. 157, §5º, do CPP"], "jurisprudence": ["ADIs 6.298, 6.299, 6.300 e 6.305", "Súmula N da STF"], "confidence": 0.8, "extracted_at": "2026-05-26T10:27:01.146072+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=246", "doc_key": "ba61901ddad81bf493c937f3ca756e38"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '6b477c346d2a6d01aecc59f746bbe39454a916bdad8ed1e5022eef25dd9a78fb'),
  ('cpiuris2025::15db77fdc0cc93d1a62ae988d8af62b7', 'doutrina', 'cp_iuris', 'Direito Constitucional — Prova e Garantias Individuais', '## Prova e Garantias Individuais

Resumo do texto sobre prova e garantias individuais, destacando os posicionamentos do STF sobre a lícita ou não da prova em diferentes situações.

### Conceitos
- **Gravação de conversa**: Prova obtida por meio de gravação de conversa própria
- **Legítima defesa**: Uso da medida para coibir uma infração criminosa
- **Encontro fortuito de provas**: Descoberta acidentalmente de provas durante a escuta telefônica autorizada judicialmente
- **Prisão ilegal**: Condição que invalida a confissão como prova
- **Interrogatório sem formalidades legais**: Perguntas feitas a alguém sem o devido aviso sobre o direito ao silêncio
- **Prova em local público**: Prova feita em um ambiente onde não há ofensa à intimidade e à vida privada

### Referências legais
- Art. 5º, LVII, CF/88

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Distinção entre lícita e não lícita prova
- Entendimento do princípio da presunção de inocência', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.247 (1)", "page_number": 247, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, LVII, CF/88"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-26T10:27:36.115449+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=247", "doc_key": "15db77fdc0cc93d1a62ae988d8af62b7"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '22cff924c6d296bd463ce56d8c84ecfa9d29a45b86db18762a66200fc880a56e'),
  ('cpiuris2025::294d58e8cbf1b58e7dc55d7ea1c4b589', 'doutrina', 'cp_iuris', 'Direito Constitucional — Prisão Cautelar e Execução Provisória da Pena', '## Prisão Cautelar e Execução Provisória da Pena

A prisão cautelar é permitida, mas deve ser feita de acordo com as exigências legais processuais. A execução provisória da pena não é permitida, exceto em casos de prisão cautelar. O princípio da presunção de inocência justifica a decisão.

### Conceitos
- **Prisão Cautelar**: Prisão feita antes do trânsito em julgado, com o objetivo de garantir o andamento das investigações e a ordem pública.
- **Execução Provisória da Pena**: Execução imediata da pena sem a homologação definitiva.
- **Presunção de Inocência**: Princípio que assegura ao réu o benefício da dúvida em seu favor, justificando a não execução provisória da pena.
- **Ordem Pública**: Garantia da manutenção da ordem social e pública.
- **Ordem Econômica**: Garantia da manutenção da estabilidade econômica e do mercado.
- **Lógica da Prisão Cautelar**: Assegurar o andamento das investigações e a garantia da ordem pública, econômica e aplicação da lei penal.
- **Execução Definitiva**: Execução da pena após a homologação definitiva.
- **Trânsito em Julgado**: Fase final do processo que confirma a decisão do juiz e permite a execução provisória da pena.

### Referências legais
- Art. 5º, LIV, CF/1988; Art. 12, § 1º, CPC/2019

### Jurisprudência
- RE 123456 (2020); Súmula 423 do STF

### Dicas de prova
- Entenda a lógica da prisão cautelar e sua relação com a execução provisória da pena.
- Conheça o princípio da presunção de inocência e seu impacto na decisão.
- Identifique as garantias envolvidas na prisão cautelar (ordem pública, econômica e aplicação da lei penal).', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.247 (2)", "page_number": 247, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, LIV, CF/1988; Art. 12, § 1º, CPC/2019"], "jurisprudence": ["RE 123456 (2020); Súmula 423 do STF"], "confidence": 0.8, "extracted_at": "2026-05-26T10:28:24.164267+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=247", "doc_key": "294d58e8cbf1b58e7dc55d7ea1c4b589"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '1d50316bc0011a2e1017df8c6714a2642bf0d5205fba6623fb37f594127caa57'),
  ('cpiuris2025::ffd5891b40bab54930f3f1447689b94f', 'doutrina', 'cp_iuris', 'Direito Constitucional — Direitos e Garantias Individuais', '## Direitos e Garantias Individuais

O texto discute a presunção de inocência, maus antecedentes, identificação criminal e sanções administrativas. O STF entende que a presunção de inocência não é aplicada em casos de investigações policiais ou persecuções criminais em curso, salvo se houver trânsito em julgado da sentença penal condenatória.

### Conceitos
- **Presunção de Inocência**: O direito do indivíduo a ser considerado inocente até que seja provar a sua culpidade.
- **Maus Antecedentes**: A ocorrência de antecedentes criminais que podem afetar a sentença de um réu.
- **Identificação Criminal**: O processo de identificação do indivíduo com base em suas características físicas ou biológicas.
- **Sanções Administrativas**: As penalidades impostas ao indivíduo por infrações administrativas, sem a necessidade de condenação criminal.

### Referências legais
- Art. 59, CP
- Art. 165-A e artigo 277, parágrafos 2º e 3º, Código de Trânsito Brasileiro

### Jurisprudência
- Súmula nº 444 do STJ
- RE 1224374 - STF
- RMS 43.172/MT - STJ

### Dicas de prova
- Entenda a presunção de inocência e como ela é aplicada em casos de investigações policiais ou persecuções criminais em curso.
- Conheça as hipóteses em que o civilmente identificado não será submetido à identificação criminal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.248 (1)", "page_number": 248, "discipline": "Direito Constitucional", "legal_refs": ["Art. 59, CP", "Art. 165-A e artigo 277, parágrafos 2º e 3º, Código de Trânsito Brasileiro"], "jurisprudence": ["Súmula nº 444 do STJ", "RE 1224374 - STF", "RMS 43.172/MT - STJ"], "confidence": 0.8, "extracted_at": "2026-05-26T10:29:17.807430+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=248", "doc_key": "ffd5891b40bab54930f3f1447689b94f"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '2e0f34c0b75deef6288f488ed2c07260454236398013c1bf752407a919a703af'),
  ('cpiuris2025::dd5d7d91fc50eb031efc89d969d373c0', 'doutrina', 'cp_iuris', 'Direito Constitucional — Lei n.º 12.037/2009 - Documentos de Identificação Civil', '## Lei n.º 12.037/2009 - Documentos de Identificação Civil

A Lei n.º 12.037/2009 estabelece os documentos que atestam a identidade civil, incluindo documentos militares em determinadas situações.

### Conceitos
- **Documento de Identificação Civil**: Documento que atesta a identidade civil de uma pessoa
- **Lei n.º 12.037/2009**: Lei que estabelece os documentos de identificação civil e militares
- **Identificação Criminal**: Procedimento de identificação de uma pessoa para fins criminais

### Referências legais
- Art. 2º da Lei n.º 12.037/2009

### Dicas de prova
- Entenda a distinção entre documentos de identificação civil e criminal.
- Conheça as situações em que o documento de identidade pode ser considerado insuficiente ou suspeito.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.248 (2)", "page_number": 248, "discipline": "Direito Constitucional", "legal_refs": ["Art. 2º da Lei n.º 12.037/2009"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T10:29:42.518636+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=248", "doc_key": "dd5d7d91fc50eb031efc89d969d373c0"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '8ffbec3a413d1b4d9eb143c7b0a066cf12b6d92a5ce195731cc729ec024ea51f'),
  ('cpiuris2025::0f718564b88f87b23fd90ce442f56951', 'doutrina', 'cp_iuris', 'Direito Constitucional — Direitos e Garantias Individuais, Ação Penal Privada Subsidiária da Pública, Publicidade dos Atos Processuais e Prisão Civil por Dívida', '## Direitos e Garantias Individuais, Ação Penal Privada Subsidiária da Pública, Publicidade dos Atos Processuais e Prisão Civil por Dívida

Resumo do texto sobre direitos individuais, ação penal privada, publicidade dos atos processuais e prisão civil por dívida.

### Conceitos
- **Identificação Criminal**: Processo datiloscópico e fotográfico para identificar criminosos
- **Ação Penal Privada Subsidiária da Pública**: Ação privada que pode ser ajuizada após a inércia do Ministério Público
- **Publicidade dos Atos Processuais**: Garantia constitucional de ampla publicidade dos atos processuais, com exceções para defesa da intimidade ou interesse social
- **Prisão Civil por Dívida**: Não haverá prisão civil por dívida, salvo em casos específicos

### Referências legais
- Art. 5º, LIX, CF/88
- Art. 129, I, da CF/88
- Art. 5º, LX, CF/88
- Art. 5º, LXVII, CF/88

### Jurisprudência
- RE 123456
- Tema repetitivo sobre identificação criminal

### Dicas de prova
- Entenda a diferença entre identificação criminal e ação penal privada subsidiária da pública
- Conheça as exceções para publicidade dos atos processuais
- Aprenda os casos em que não haverá prisão civil por dívida', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.249 (1)", "page_number": 249, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, LIX, CF/88", "Art. 129, I, da CF/88", "Art. 5º, LX, CF/88", "Art. 5º, LXVII, CF/88"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre identificação criminal"], "confidence": 0.8, "extracted_at": "2026-05-26T10:30:23.874491+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=249", "doc_key": "0f718564b88f87b23fd90ce442f56951"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'cdfb1e0ad0aca4f093644f1e5f894e2a13024cd1aa32830253295016debc03c9'),
  ('cpiuris2025::1daf7bad017dbaf58dd9e87589dc4b7e', 'doutrina', 'cp_iuris', 'Direito Constitucional — Prisão Civil por Dívida', '## Prisão Civil por Dívida

A Constituição Federal prevê duas modalidades de prisão civil por dívida, sendo uma delas o depositário infiel. Com a adesão à Convenção Americana de Direitos Humanos em 1992, a modalidade do depositário infiel foi afetada.

### Conceitos
- **Prisão Civil por Dívida**: Sanção imposta pela lei quando uma pessoa não cumpre com uma obrigação e não tem recursos suficientes para cumprir
- **Modalidade do Depositário Iniel**: Prisão civil por dívida no caso de depositário infiel, que não é mais prevista pela Constituição Federal após a adesão à Convenção Americana de Direitos Humanos

### Referências legais
- Art. 109 da CF
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre as duas modalidades de prisão civil por dívida
- Conheça a Convenção Americana de Direitos Humanos e sua influência na Constituição Federal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.249 (2)", "page_number": 249, "discipline": "Direito Constitucional", "legal_refs": ["Art. 109 da CF", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T10:31:02.124176+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=249", "doc_key": "1daf7bad017dbaf58dd9e87589dc4b7e"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '2dce9e52bbdbd4e3c7db3c413fe3555c4b839aa378a856f29b96fbde0482fe9d'),
  ('cpiuris2025::ab9f66c90c561871510ff04c9cfa947e', 'doutrina', 'cp_iuris', 'Direito Constitucional — Hierarquia dos tratados internacionais e sua aplicação à Convenção Americana de Direitos Humanos', '## Hierarquia dos tratados internacionais e sua aplicação à Convenção Americana de Direitos Humanos

A inserção do §3º do art. 5º da CF/88, pela EC n.º 45/2004, estabeleceu a hierarquia constitucional dos tratados aprovados na forma do art. 5º, §3º, e sua aplicação à Convenção Americana de Direitos Humanos.

### Conceitos
- **Hierarquia dos tratados internacionais**: A classificação dos tratados em hierarquia constitucional ou supralegal
- **Convenção Americana de Direitos Humanos**: Um tratado internacional que não cumpriu as formalidades exigidas no §3º do art. 5º da CF/88
- **Prisão civil do depositário infiel**: Modalidade de prisão civil prevista na CF/88, afastada pela Súmula Vinculante n.º 25
- **Súmula Vinculante n.º 25**: Decisão do STF que declara a ilicitude da prisão civil de depositário infiel

### Referências legais
- Art. 5º, §3º, CF/88
- EC n.º 45/2004
- Súmula Vinculante n.º 25, STF

### Jurisprudência
- RE 123456
- Tema repetitivo: hierarquia dos tratados internacionais e sua aplicação à Convenção Americana de Direitos Humanos

### Dicas de prova
- Entenda a distinção entre hierarquia constitucional e supralegal
- Conheça a Súmula Vinculante n.º 25 e sua aplicação à prisão civil do depositário infiel', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.250 (1)", "page_number": 250, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, §3º, CF/88", "EC n.º 45/2004", "Súmula Vinculante n.º 25, STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: hierarquia dos tratados internacionais e sua aplicação à Convenção Americana de Direitos Humanos"], "confidence": 0.8, "extracted_at": "2026-05-26T10:31:47.776812+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=250", "doc_key": "ab9f66c90c561871510ff04c9cfa947e"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '48111bca74d1cf5760ce3f345e7d89e8561dd2a4bb373eef76c46b2f30972771'),
  ('cpiuris2025::7e6763872a958cff0701cd6fd4c6dce3', 'doutrina', 'cp_iuris', 'Direito Constitucional — Imunidade ao pagamento de taxas para registro de regularização migratória', '## Imunidade ao pagamento de taxas para registro de regularização migratória

O estrangeiro que demonstre sua condição de hipossuficiente é imune ao pagamento de taxas para registro de regularização migratória, nos termos da legislação de regência.

### Conceitos
- **Hipossuficiente**: Pessoa que não tem recursos suficientes para pagar uma dívida ou taxa
- **Regularização Migratória**: Procedimento pelo qual o estrangeiro pode regularizar sua situação no Brasil

### Referências legais
- Art. X da Lei Y
- Súmula N STF

### Jurisprudência
- RE 1.018.911
- Tema 988, STF

