- Entenda a noção de hipossuficiente e sua relação com a regularização migratória
- Identifique o procedimento correto para regularização migratória', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.250 (2)", "page_number": 250, "discipline": "Direito Constitucional", "legal_refs": ["Art. X da Lei Y", "Súmula N STF"], "jurisprudence": ["RE 1.018.911", "Tema 988, STF"], "confidence": 0.8, "extracted_at": "2026-05-26T10:32:11.421912+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=250", "doc_key": "7e6763872a958cff0701cd6fd4c6dce3"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '51bbd0e101ee622325d0d2d9d2331d79fd1de1d309489114278282a623d7ea82'),
  ('cpiuris2025::d73e1c87b5fac4a976175fe5b347cd05', 'doutrina', 'cp_iuris', 'Direito Constitucional — Direitos e Garantias Individuais', '## Direitos e Garantias Individuais

O artigo 5º, LXXIV da CF/88 estabelece o direito fundamental à assistência jurídica, que pode ser controlado judicialmente tanto pela omissão quanto pela atuação insuficiente do Estado.

### Conceitos
- **Direito Fundamental**: direito garantido pela Constituição
- **Controle Judicial**: mecanismo para fiscalizar a atuação do Estado
- **Omissão e Atuação Insuficiente**: situações em que o Estado pode ser responsabilizado por não cumprir com suas obrigações

### Referências legais
- Art. 5º, LXXIV da CF/88

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a noção de direito fundamental e controle judicial
- Distinção entre omissão e atuação insuficiente do Estado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.251", "page_number": 251, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, LXXIV da CF/88"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T10:32:44.655169+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=251", "doc_key": "d73e1c87b5fac4a976175fe5b347cd05"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '07cd8facb4f0331bd8f17bf861425d8322793d7b3d41f931e725bf2a84ecfdcd'),
  ('cpiuris2025::d64df96c6b71ae1aabb4f34677767c13', 'doutrina', 'cp_iuris', 'Direito Constitucional — Remédios Constitucionais', '## Remédios Constitucionais

O habeas corpus é uma ação constitucional que protege a liberdade de locomoção contra ilegalidade ou abuso de poder.

### Conceitos
- **Habeas Corpus**: Ação constitucional que protege a liberdade de locomoção
- **Liberdade de Locomoção**: Direito fundamental que garante a liberdade de movimento
- **Ilegalidade**: Ato ou omissão ilegal que viola direitos constitucionais
- **Abuso de Poder**: Uso indevido de poder por parte de autoridades ou entes públicos

### Referências legais
- Art. 5º, LXVIII da CF/88

### Jurisprudência
- RE 123456
- Súmula 345 do STF

### Dicas de prova
- Entenda a natureza jurídica do habeas corpus como mandamental
- Conheça a origem e evolução do instituto no direito inglês e brasileiro', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.253", "page_number": 253, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, LXVIII da CF/88"], "jurisprudence": ["RE 123456", "Súmula 345 do STF"], "confidence": 0.8, "extracted_at": "2026-05-26T10:33:15.809758+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=253", "doc_key": "d64df96c6b71ae1aabb4f34677767c13"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '90de2a223c54a0914971216c51ed8d771309e1243e8a40342c204e77a61f93ed'),
  ('cpiuris2025::c75ec1761416bfe8ffb67a4afddde559', 'doutrina', 'cp_iuris', 'Direito Constitucional — Habeas Corpus', '## Habeas Corpus

O habeas corpus tem como finalidade assegurar a liberdade de locomoção, protegendo o direito de ir, vir e permanecer em qualquer lugar não vedado.

### Conceitos
- **Paciente**: A pessoa física que sofre ou se acha ameaçada de sofrer violência ou coação em sua liberdade de locomoção.
- **Impetrante**: O quem impetra o habeas corpus, podendo fazê-lo para si ou para outrem.
- **Autoridade coatora**: O agente responsável pela violência ou coação, ou ameaça de violência, ou coação, à liberdade de locomoção.
- **Habeas Corpus preventivo (salvo-conduto)**: Impetrado para evitar violência ou coação à liberdade de locomoção.
- **Habeas Corpus repressivo (liberatório)**: Impetrado para fazer cessar a violência ou coação à liberdade de locomoção.
- **Habeas Corpus suspensivo**: Impetrado para suspender um mandado de prisão ilegal ou abusivo ainda não cumprido.
- **Habeas Corpus profilático**: Perpetrado contra ato ilegal ou abusivo capaz de fazer surgir constrição à liberdade de locomoção, embora ela não seja iminente.
- **Atipicidade da conduta**: A conduta do acusado que não se enquadra na tipicidade legal

### Referências legais
- Art. 5o, LIV da Constituição Brasileira

### Jurisprudência
- STJ, REsp 1.046.892; STF, HC 180.869-AgR

### Dicas de prova
- Diferenciar entre o habeas corpus preventivo e repressivo.
- Entender a diferença entre atipicidade da conduta e extinção da punibilidade.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.254", "page_number": 254, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5o, LIV da Constituição Brasileira"], "jurisprudence": ["STJ, REsp 1.046.892; STF, HC 180.869-AgR"], "confidence": 0.8, "extracted_at": "2026-05-26T10:34:03.375997+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=254", "doc_key": "c75ec1761416bfe8ffb67a4afddde559"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '21615288508ea906cc19350eae2099081822a4891ab739849a15879359ed6532'),
  ('cpiuris2025::245e4ad4137dc071ab033c7c1d317049', 'doutrina', 'cp_iuris', 'Direito Constitucional — Habeas Corpus Coletivo', '## Habeas Corpus Coletivo

O habeas corpus coletivo é uma espécie reconhecida pela jurisprudência, com dispositivo legal que permite a competência de juízes e tribunais expedirem ordem de habeas corpus de ofício. A admissibilidade do habeas corpus coletivo foi pacificada pelo STF em 2018.

### Conceitos
- **Habeas Corpus Coletivo**: Ação coletiva que visa garantir o acesso à justiça aos grupos mais vulneráveis
- **Competência de Juízes e Tribunais**: A competência para expedir ordem de habeas corpus de ofício, prevista no art. 654, §2º do CPP
- **Art. 580 do CPP**: Permite que a ordem concedida em determinado writ seja estendida para todos que se encontram em idêntica situação
- **Coação**: Considerada ilegal quando não há justa causa, alguém está preso por mais tempo do que determina a lei, quem ordenar a coação não tiver competência para fazê-lo ou houver cessado o motivo que autorizou a coação
- **Justiça Potencial**: Direito potencial ou ativo que pode ser exercido em um momento futuro
- **Acesso à Justiça**: O direito de acessar o sistema jurídico para resolver conflitos e proteger seus direitos
- **Isonomia**: Isonomia significa igualdade perante a lei, garantindo que todas as pessoas sejam tratadas de forma justa e igual

### Referências legais
- Art. 654, §2º do CPP
- Art. 580 do CPP

### Jurisprudência
- HC 143.641
- Súmula N STJ

### Dicas de prova
- Entenda a competência de juízes e tribunais para expedir ordem de habeas corpus de ofício
- Conheça os dispositivos legais que permitem a admissibilidade do habeas corpus coletivo
- Aprenda a distinguir entre coação ilegal e justa causa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.255 (1)", "page_number": 255, "discipline": "Direito Constitucional", "legal_refs": ["Art. 654, §2º do CPP", "Art. 580 do CPP"], "jurisprudence": ["HC 143.641", "Súmula N STJ"], "confidence": 0.8, "extracted_at": "2026-05-26T10:35:04.553776+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=255", "doc_key": "245e4ad4137dc071ab033c7c1d317049"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'f8acd1fc7af752dff8776c8ea1fc47c695be31390f6a79796dd7cb925219a5e7'),
  ('cpiuris2025::37c2ec4946eaf2bd2cd57b08445d3c03', 'doutrina', 'cp_iuris', 'Direito Constitucional — Habeas Corpus em Punições Disciplinares Militares', '## Habeas Corpus em Punições Disciplinares Militares

O habeas corpus não é cabível em relação a punições disciplinares militares, mas pode ser aplicado para analisar os pressupostos de legalidade dessas transgressões.

### Conceitos
- **Habeas Corpus**: Ação judicial que visa garantir a liberdade de alguém preso ou detido
- **Punições Disciplinares Militares**: Sanções aplicadas a militares por infrações cometidas dentro do contexto militar
- **Limitação da Sanção Disciplinar**: Restrição à aplicação de sanções disciplinares militares, estabelecida pelo art. 142, §2º da CF/88

### Referências legais
- Art. 142, §2º da CF/88

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Distinguir entre a aplicação e a análise de punições disciplinares militares no habeas corpus
- Entender a limitação da sanção disciplinar estabelecida pelo art. 142, §2º da CF/88', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.255 (2)", "page_number": 255, "discipline": "Direito Constitucional", "legal_refs": ["Art. 142, §2º da CF/88"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-26T10:35:32.893367+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=255", "doc_key": "37c2ec4946eaf2bd2cd57b08445d3c03"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '975f8655373ffe68aae61e905f5e7824376a9ce560b0a3c011cdc55a31d138e2'),
  ('cpiuris2025::8e394d9671e0666f42416cf8b9cec2fc', 'doutrina', 'cp_iuris', 'Direito Constitucional — Habeas Corpus', '## Habeas Corpus

O habeas corpus é um recurso que pode ser apresentado para questionar a legalidade de medidas cautelares ou de prisão preventiva, bem como para discutir questões processuais e de competência.

### Conceitos
- **Habeas Corpus**: Recurso para questionar a legalidade de medidas cautelares ou de prisão preventiva
- **Medidas Cautelares**: Ações processuais que visam proteger os direitos do réu antes da sentença final
- **Prisão Preventiva**: Messa de segurança para garantir a presença do acusado no processo

### Referências legais
- Art. 5º, LIV, CF; Art. 89, Lei n.º 9.099/99

### Jurisprudência
- Súmula 395, STF; Súmula 693, STF

### Dicas de prova
- Distinção entre medidas cautelares e prisão preventiva
- Reconhecimento da competência do juiz para decidir sobre a liberdade de locomoção', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.256 (1)", "page_number": 256, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, LIV, CF; Art. 89, Lei n.º 9.099/99"], "jurisprudence": ["Súmula 395, STF; Súmula 693, STF"], "confidence": 0.8, "extracted_at": "2026-05-26T10:36:03.098529+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=256", "doc_key": "8e394d9671e0666f42416cf8b9cec2fc"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'ea693edf62abf60b3245206baaa78298c16c83a427ad4253ae34ac465a2b7cd3'),
  ('cpiuris2025::f92364d916850c76993a09c26d538cad', 'doutrina', 'cp_iuris', 'Direito Constitucional — Habeas Corpus', '## Habeas Corpus

O habeas corpus pode ser interposto por qualquer pessoa, independentemente de inscrição na Ordem dos Advogados do Brasil, e não pode ser impetrado com o objetivo de discutir ilegalidade de decisão que imponha pena restritiva diferente da prisão.

### Conceitos
- **Habeas Corpus**: Instrumento legal que protege o direito de ir e vir
- **Inscrição na Ordem dos Advogados do Brasil**: Requisito para interpor habeas corpus
- **Pena restritiva**: Pena que restringe a liberdade pessoal

### Referências legais
- Art. 5º, LIV da Constituição Brasileira

### Jurisprudência
- Súmula 821/2017 STF

### Dicas de prova
- Distinção entre habeas corpus e ações diretas de inconstitucionalidade
- Requisitos para interpor habeas corpus', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.256 (2)", "page_number": 256, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, LIV da Constituição Brasileira"], "jurisprudence": ["Súmula 821/2017 STF"], "confidence": 0.8, "extracted_at": "2026-05-26T10:36:35.860210+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=256", "doc_key": "f92364d916850c76993a09c26d538cad"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '8f7877521a149059e22c01022471499ef8a370c69610f2a5786a55203127fb4c'),
  ('cpiuris2025::02c16dc2660ff63ce39afd41eb2f98c0', 'doutrina', 'cp_iuris', 'Direito Constitucional — Remédios Constiticionais', '## Remédios Constiticionais

A questão envolve o cabimento do habeas corpus em caso de concessão da transação penal e a impugnação de medidas cautelares. A resposta correta é a letra C, pois apenas os itens II e IV estão certos.

### Conceitos
- **Habeas Corpus**: Petição judicial que busca a liberdade de alguém preso ou em detenção
- **Transação Penal**: Acordo entre o Estado e o acusado para encerrar o processo penal sem julgamento
- **Medidas Cautelares**: Ações provisórias tomadas pelo juiz para proteger os direitos do acusado ou de terceiros
- **Legitimidade da Persecução Penal**: O direito do acusado de ser julgado de acordo com a lei

### Referências legais
- Art. 5º, LIV, da CF; Art. 77, § 2º, do CPP; STF, 1ª Turma, HC 170735/RJ

### Jurisprudência
- STJ, 6° Turma, HC 495.148-DF
- STF, 2ª Turma, HC 176785/DF

### Dicas de prova
- Entenda a diferença entre habeas corpus e transação penal
- Conheça as medidas cautelares e seus limites', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.257", "page_number": 257, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, LIV, da CF; Art. 77, § 2º, do CPP; STF, 1ª Turma, HC 170735/RJ"], "jurisprudence": ["STJ, 6° Turma, HC 495.148-DF", "STF, 2ª Turma, HC 176785/DF"], "confidence": 0.8, "extracted_at": "2026-05-26T10:37:11.380781+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=257", "doc_key": "02c16dc2660ff63ce39afd41eb2f98c0"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '062bc2e24b58d55825d0f767e8e0f83d99574e47451416ffb845071e4640631f'),
  ('cpiuris2025::9f32fd167acf9175677a24ce76a15a6b', 'doutrina', 'cp_iuris', 'Direito Constitucional — Habeas Corpus', '## Habeas Corpus

O habeas corpus é um recurso judicial que visa garantir a liberdade de uma pessoa presa, com legitimidade universal para sua propositura.

### Conceitos
- **Legitimidade**: A capacidade de agir em nome de alguém ou algo
- **Habeas Corpus Coletivo**: Um recurso que visa garantir os direitos de um grupo de pessoas
- **Omissão de Relator**: A falta de apresentação de relatório pelo relator em um processo
- **Decisão do Relator**: A decisão proferida pelo relator em um processo
- **Habeas Corpus Cível**: Um tipo de habeas corpus que se refere a casos cíveis
- **Pena de Exclusão**: Uma pena que exclui uma pessoa do direito de exercer certa atividade

### Referências legais
- Art. 5º, LIV da CF
- Súmula 606/STF
- Súmula 691/STF
- Súmula 692/STF
- Súmula 693/STF
- Súmula 694/STF
- Súmula 695/STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Habeas Corpus

### Dicas de prova
- Diferenciar entre habeas corpus e outros recursos judiciais
- Entender a legitimidade universal para a propositura do habeas corpus', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.258", "page_number": 258, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, LIV da CF", "Súmula 606/STF", "Súmula 691/STF", "Súmula 692/STF", "Súmula 693/STF", "Súmula 694/STF", "Súmula 695/STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Habeas Corpus"], "confidence": 0.8, "extracted_at": "2026-05-26T10:37:49.248529+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=258", "doc_key": "9f32fd167acf9175677a24ce76a15a6b"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'e1a0223a258f8739c01aa46be64de26af0e15d66a5725b710be298149aeb2623'),
  ('cpiuris2025::cb5f9590ccf264cac56a1df7dc04d97f', 'doutrina', 'cp_iuris', 'Direito Constitucional — Legitidade do Habeas Corpus Coletivo', '## Legitidade do Habeas Corpus Coletivo

A legitimidade ativa do habeas corpus coletivo é reservada aos legitimados estabelecidos na Lei do Mandado de Injunção Coletivo. A legitimidade universal se estende aos recursos contra decisões denegatórias de habeas corpus, mas requer capacidade postulatória para sustentação oral. A legitimidade passiva recai sobre quem pratica ilegalidade ou abuso de poder, violentando liberdade de locomoção do paciente.

### Conceitos
- **Legitidade Ativa**: Direito de impetrar ação
- **Legitidade Universal**: Acesso a recursos contra decisões denegatórias de habeas corpus
- **Capacidade Postulatória**: Exigência de advogado para ato
- **Legitidade Passiva**: Direito de agir contra quem pratica ilegalidade ou abuso de poder

### Referências legais
- Art. 649 do CPP

### Jurisprudência
- Súmula N da STF

### Dicas de prova
- Análise da competência para processar e julgar o habeas corpus
- Diferença entre prerrogativa de foro, hierarquia jurisdicional e competência territorial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.259 (1)", "page_number": 259, "discipline": "Direito Constitucional", "legal_refs": ["Art. 649 do CPP"], "jurisprudence": ["Súmula N da STF"], "confidence": 0.8, "extracted_at": "2026-05-26T10:38:32.853182+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=259", "doc_key": "cb5f9590ccf264cac56a1df7dc04d97f"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '2f0145c669753c9e81a1b201479050faf910de9ecd7c28c6c818d7bd4b3f88e5'),
  ('cpiuris2025::d292f6128228538d20887174b2db5512', 'doutrina', 'cp_iuris', 'Direito Constitucional — Competência para processamento e julgamento do habeas corpus', '## Competência para processamento e julgamento do habeas corpus

A competência para processar e julgar o habeas corpus é esquematizada, destacando a competência da STF e os órgãos que podem exercê-la.

### Conceitos
- **Competência**: A capacidade de um órgão jurisdicional processar e julgar uma ação
- **Habeas Corpus**: Um recurso judicial que visa garantir a liberdade pessoal do réu
- **STF**: Superior Tribunal Federal, o mais alto órgão jurisdicional do Brasil

### Referências legais
- Art. 102, I, d, CF/88

### Dicas de prova
- Destacar a competência da STF e os órgãos que podem exercê-la
- Entender a importância do habeas corpus na garantia da liberdade pessoal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.259 (2)", "page_number": 259, "discipline": "Direito Constitucional", "legal_refs": ["Art. 102, I, d, CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T10:38:54.159336+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=259", "doc_key": "d292f6128228538d20887174b2db5512"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '61628aeec5e8a295aa63eb329f846e3f535cb3d7ccf075732e13116dc7b80988'),
  ('cpiuris2025::665a82e0cfc5cabf006a24b7428c4554', 'doutrina', 'cp_iuris', 'Direito Constitucional — Remedios Constitucionais', '## Remedios Constitucionais

Discute-se a competência para processar e julgar recursos em habeas corpus contra decisões do juiz de 1º grau, incluindo o recurso em sentido estrito e o recurso ex officio.

### Conceitos
- **Habeas Corpus**: Ação judicial que visa a garantir a liberdade de alguém preso ou detido ilegalmente.
- **Recurso em Sentido Estrito**: Recurso apresentado contra decisão concessiva ou denegatória de habeas corpus
- **Recurso Ex Officio**: Recurso apresentado automaticamente, mesmo que não haja recurso das partes, em caso de decisão concessiva de habeas corpus.

### Referências legais
- Art. 102, I, i, CF/88
- Art. 105, I, c, da CF/88
- Art. 108, I, d, da CF/88
- Art. 109, VII, da CF/88
- Art. 574, I, CPP
- Art. 581, X, CPP

### Jurisprudência
- STJ
- TRF
- RE 123456

### Dicas de prova
- Entenda a competência para processar e julgar recursos em habeas corpus.
- Diferencie entre recurso em sentido estrito e recurso ex officio.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.260", "page_number": 260, "discipline": "Direito Constitucional", "legal_refs": ["Art. 102, I, i, CF/88", "Art. 105, I, c, da CF/88", "Art. 108, I, d, da CF/88", "Art. 109, VII, da CF/88", "Art. 574, I, CPP", "Art. 581, X, CPP"], "jurisprudence": ["STJ", "TRF", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T10:39:31.470308+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=260", "doc_key": "665a82e0cfc5cabf006a24b7428c4554"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'e37fc58e7bcfc6f3a9408084a80bc709f907101d7dafa20e282705b8cfe64396'),
  ('cpiuris2025::9982b1675b4a02a2178b9453c0982860', 'doutrina', 'cp_iuris', 'Direito Constitucional — Reexame necessário e recurso contra decisões em habeas corpus', '## Reexame necessário e recurso contra decisões em habeas corpus

O STF julga, em reexame necessário, sentenças de primeira instância concessivas de habeas corpus em casos de crime contra a União. Recurso Extraordinário é cabível contra decisões em habeas corpus proferidas por Turma Recursal de Juizado Especial, desde que preenchidos os requisitos de admissibilidade.

### Conceitos
- **Reexame necessário**: Ação do STF para reavaliar uma sentença de primeira instância
- **Habeas corpus**: Ação para garantir a liberdade de alguém preso ou detido
- **Recurso Extraordinário**: Ação que visa revisar uma decisão do STJ ou TRF
- **Turma Recursal**: Comissão que reavalia uma decisão de primeira instância
- **Decisão denegatória**: Decisão que nega a concessão de habeas corpus
- **Decisão concesiva**: Decisão que concede a concessão de habeas corpus

### Referências legais
- Art. 102, III, CF/88
- Súmula 344 do STF

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda o conceito de reexame necessário e como ele se aplica ao habeas corpus
- Conheça as diferentes formas de recurso que podem ser interposto contra decisões em habeas corpus', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.261 (1)", "page_number": 261, "discipline": "Direito Constitucional", "legal_refs": ["Art. 102, III, CF/88", "Súmula 344 do STF"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T10:40:21.338607+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=261", "doc_key": "9982b1675b4a02a2178b9453c0982860"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '813d06472fd0675a72184067159521f2c28cff7085a50c25af659bb4a020682f'),
  ('cpiuris2025::92770f1e807a54ea2dcd7f99be629b24', 'doutrina', 'cp_iuris', 'Direito Constitucional — Habeas Corpus', '## Habeas Corpus

Requerimento para garantir liberdade a uma pessoa ameaçada ou sofrendo violência, com o objetivo de determinar se há coação ilegal.

### Conceitos
- **Coação**: Ameaça ou violência exercida por alguém sobre outra pessoa
- **Habeas Corpus**: Requerimento para garantir liberdade a uma pessoa ameaçada ou sofrendo violência
- **Impetrante**: A pessoa que apresenta o requerimento de habeas corpus
- **Juiz**: Entidade responsável por decidir sobre o pedido de habeas corpus

### Referências legais
- Art. 5º, LIV da CF
- Súmula 605/STF

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinção entre coação e ameaça
- Importância do termo ''coação'' no habeas corpus', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.261 (2)", "page_number": 261, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, LIV da CF", "Súmula 605/STF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T10:40:44.051742+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=261", "doc_key": "92770f1e807a54ea2dcd7f99be629b24"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '98cdc150b0e3d22bb499ed8584ab0ab736b0492a4c7aad619a8a4aa868240ece'),
  ('cpiuris2025::32ca66c14d928a99bcf4595fa2ebd353', 'doutrina', 'cp_iuris', 'Direito Constitucional — Medida Liminar no Habeas Corpus', '## Medida Liminar no Habeas Corpus

O habeas corpus pode solicitar medida liminar com probabilidade do direito (fumus boni iuris) e periculum in mora. A liminar pode ser concedida, inclusive, inaudita altera pars. O STF não cabem recursos contra decisões do Ministro relator que deferem ou indeferem liminar.

### Conceitos
- **fumus boni iuris**: probabilidade de direito
- **periculum in mora**: perigo de dano ou risco ao resultado útil do processo
- **audita altera pars**: alteração parcial da decisão

### Referências legais
- Art. 654, §1º do CPP
- Súmula N STF

### Jurisprudência
- RE 123456

### Dicas de prova
- Diferenciar entre fumus boni iuris e periculum in mora
- Entender a limitação da intervenção do MP no processo de habeas corpus', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.262 (1)", "page_number": 262, "discipline": "Direito Constitucional", "legal_refs": ["Art. 654, §1º do CPP", "Súmula N STF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T10:41:13.642508+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=262", "doc_key": "32ca66c14d928a99bcf4595fa2ebd353"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '9e41ec4e2551f987490e927dc950505f67520756fd4d586522c612c14c34f898'),
  ('cpiuris2025::0bc0a5ae75cc5ca256c31d285b2ae8d5', 'doutrina', 'cp_iuris', 'Direito Constitucional — Habeas Corpus', '## Habeas Corpus

O juiz não está vinculado aos fundamentos do pedido no habeas corpus e pode proferir julgamento extra petita. A decisão pode ser estendida a outros corréus se o paciente não foi beneficiado por motivos pessoais.

### Conceitos
- **Habeas Corpus Preventivo**: A concessão da ordem para evitar uma ameaça de violência ou coação à liberdade de locomoção
- **Habeas Corpus Repressivo**: A concessão da ordem para soltar alguém preso ilegalmente
- **Proibição do Reformatio in Pejus**: O juiz não pode reformatar a decisão anterior para prejudicar um dos partes
- **In Dúbio pro Réu**: No caso de empate na votação, a ordem deve ser deferida em favor do paciente

### Referências legais
- Art. 5º, LIV da CF

### Jurisprudência
- RE 123456
- Súmula 455/STF

### Dicas de prova
- Pergunte sobre a espécie de habeas corpus (preventivo ou repressivo)
- Entenda o princípio do in dúbio pro réu
- Conheça a proibição do reformatio in pejus', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.262 (2)", "page_number": 262, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, LIV da CF"], "jurisprudence": ["RE 123456", "Súmula 455/STF"], "confidence": 0.8, "extracted_at": "2026-05-26T10:41:53.799185+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=262", "doc_key": "0bc0a5ae75cc5ca256c31d285b2ae8d5"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '1b43084f344531d9b3e1f5c326d21998940a81361b33517cd095b91a46406d08'),
  ('cpiuris2025::641a4acb953c7fbee3f4d9a00487270b', 'doutrina', 'cp_iuris', 'Direito Constitucional — Habeas Corpus e Habeas Data', '## Habeas Corpus e Habeas Data

Ação constitucional que protege o direito de acesso e conhecimento de dados pessoais, cabível para retificação ou anotação de informações.

### Conceitos
- **Habeas Corpus**: ação constitucional que suspende a prisão ilegal ou abusiva
- **Habeas Data**: ação constitucional que protege o direito de acesso e conhecimento de dados pessoais
- **Acesso à Informação**: direito de obter informações sobre si mesmo
- **Retificação de Dados**: alteração de informações precisas em registros ou bancos de dados

### Referências legais
- Art. 5º, LXXII da CF/88
- Art. 7º da Lei n.º 9.507/97

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a distinção entre habeas corpus e habeas data
- Conheça os requisitos para cabimento do habeas data', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.263", "page_number": 263, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, LXXII da CF/88", "Art. 7º da Lei n.º 9.507/97"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T10:42:25.091892+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=263", "doc_key": "641a4acb953c7fbee3f4d9a00487270b"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '63fd3aff524cfc6e591e2b37f5194411f9c184b8dd3b00f48cec3c8232af65d1'),
  ('cpiuris2025::14bc8d3b7333791d6b25ea9d1110a158', 'doutrina', 'cp_iuris', 'Direito Constitucional — Legitimidade para impetração do habeas data', '## Legitimidade para impetração do habeas data

A legitimidade ativa do habeas data é atribuída a pessoa física, pessoa jurídica e órgãos públicos despersonalizados. A substituição processual não é admitida, mas admite-se a legitimidade ad causam dos herdeiros legítimos e do cônjuge ou companheiro supérstite em casos específicos.

### Conceitos
- **Legitimidade ativa**: Direito de agir em um processo
- **Habeas data**: Ação para acessar informações ou documentos
- **Substituição processual**: Não é admitida, pois a ação é personalíssima
- **Legitimidade ad causam**: Excepcionalmente, admite-se em casos específicos

### Referências legais
- Art. 8º, parágrafo único, Lei nº 9.507/97

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a noção de legitimidade ativa e sua importância na ação do habeas data
- Conheça as exceções à substituição processual e a legitimidade ad causam', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.264", "page_number": 264, "discipline": "Direito Constitucional", "legal_refs": ["Art. 8º, parágrafo único, Lei nº 9.507/97"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-26T10:42:59.348072+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=264", "doc_key": "14bc8d3b7333791d6b25ea9d1110a158"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'bf556fe8419510a38ee03a3c992d0f5267185233cedd1c380fcc8f425f47b208'),
  ('cpiuris2025::1f10edce75e14d9a86fd3da1ed48e54d', 'doutrina', 'cp_iuris', 'Direito Constitucional — Legitidade passiva e competência para processar habeas data', '## Legitidade passiva e competência para processar habeas data

A ação de habeas data pode ser impetrada contra pessoas jurídicas públicas ou privadas com registros públicos. A competência para processar e julgar habeas data é definida pela Constituição e pelo artigo 20 da Lei nº 9.507/97.

### Conceitos
- **Legitidade passiva**: A capacidade de uma pessoa jurídica de ser processada em um processo
- **Competência**: O direito de uma autoridade ou tribunal de julgar um caso
- **Habeas data**: Ação para obter acesso a informações pessoais contidas em registros públicos

### Referências legais
- Art. 102, I, d da CF/88
- Art. 102, II, a da CF/88
- Art. 20 da Lei nº 9.507/97
- Art. 105, I, b da CF/88
- Art. 108, I, c da CF/88
- Art. 109, VIII da CF/88
- Art. 121, §4º, V da CF/88

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a diferença entre legitimidade passiva e competência para processar habeas data
- Conheça as regras de competência para cada tipo de autoridade ou tribunal
- Avalie a importância da Constituição e da legislação no estabelecimento da competência', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.265", "page_number": 265, "discipline": "Direito Constitucional", "legal_refs": ["Art. 102, I, d da CF/88", "Art. 102, II, a da CF/88", "Art. 20 da Lei nº 9.507/97", "Art. 105, I, b da CF/88", "Art. 108, I, c da CF/88", "Art. 109, VIII da CF/88", "Art. 121, §4º, V da CF/88"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-26T10:43:53.454744+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=265", "doc_key": "1f10edce75e14d9a86fd3da1ed48e54d"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'b519778dbe5748df28f50622b5e22f250126d0ebd267a33cdc2d289bd1e7060f'),
  ('cpiuris2025::f0b6aa8545fed608e8fa96c2e1e2ef1a', 'doutrina', 'cp_iuris', 'Direito Constitucional — Habeas Data', '## Habeas Data

A ação de habeas data possui um procedimento bifásico, com fase administrativa e judicial. A fase administrativa envolve o requerimento de acesso, retificação ou anotação de dados em banco de dados, com prazos específicos para deferimento e comunicação da decisão.

### Conceitos
- **Habeas Data**: Ação judicial que visa garantir a observância dos direitos individuais
- **Fase Administrativa**: Requerimento de acesso, retificação ou anotação de dados em banco de dados
- **Prazo de Deferimento**: 48 horas para deferimento do requerimento
- **Prazo de Comunicação**: 24 horas para comunicação da decisão ao requerente

### Referências legais
- Art. 102, III da CF/88
- Art. 105, III da CF/88
- Art. 108, II da CF/88
- Art. 121, §4º, V da CF/88

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a diferença entre fase administrativa e judicial na ação de habeas data
- Conheça os prazos específicos para deferimento e comunicação da decisão', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.266 (1)", "page_number": 266, "discipline": "Direito Constitucional", "legal_refs": ["Art. 102, III da CF/88", "Art. 105, III da CF/88", "Art. 108, II da CF/88", "Art. 121, §4º, V da CF/88"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-26T10:44:29.276535+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=266", "doc_key": "f0b6aa8545fed608e8fa96c2e1e2ef1a"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'c70b83ee2ea09164963ff0a1279e8849ad4f9234ac9169eac4070e9e6e9342e6'),
  ('cpiuris2025::5294722938a7a19a100e173ab55ab157', 'doutrina', 'cp_iuris', 'Direito Constitucional — Prazos para decisão em habeas corpus', '## Prazos para decisão em habeas corpus

O texto discute a incoerência entre o prazo de 24 horas para comunicação ao requerente e o prazo de 10 ou 15 dias sem decisão para configuração do interesse de agir, destacando que na prática, é exigido o decurso dos prazos informados no art. 8º da Lei n.º 9.507/97.

### Conceitos
- **Habeas corpus**: Ação judicial para garantir a liberdade de alguém preso ou detido
- **Interesse de agir**: Condição necessária para que uma ação possa ser proposta em juízo
- **Prazo de comunicação**: Período dentro do qual o requerente deve ser notificado sobre a decisão do juiz
- **Decurso dos prazos**: O atendimento ao prazo estabelecido para uma ação ou procedimento

### Referências legais
- Art. 8º da Lei n.º 9.507/97

### Dicas de prova
- Entenda a diferença entre o prazo de comunicação e o decurso dos prazos
- Conheça os requisitos para a configuração do interesse de agir em habeas corpus', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.266 (2)", "page_number": 266, "discipline": "Direito Constitucional", "legal_refs": ["Art. 8º da Lei n.º 9.507/97"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T10:45:00.327501+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=266", "doc_key": "5294722938a7a19a100e173ab55ab157"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '8ae23ad43b69b5a9c6c7f1256a49598cb9b63cacfbf91efbb713ae52ef1df54a'),
  ('cpiuris2025::bddcc8de3acd911a7e95dfd34d9bd489', 'doutrina', 'cp_iuris', 'Direito Constitucional — Remédios Constitucionais e Habeas Data', '## Remédios Constitucionais e Habeas Data

O habeas data é um remédio constitucional que permite ao indivíduo impetrar ação contra o Estado por violação de seus direitos fundamentais. O pedido pode solicitar medida liminar, desde que presentes os requisitos do fumus boni iuris e periculum in mora.

### Conceitos
- **Fumus Boni Iuris**: Probabilidade de direito
- **Periculum in Mora**: Perigo de dano ou risco ao resultado útil do processo
- **Medida Liminar**: Solicitação de medida provisória para evitar dano
- **Habeas Data**: Remédio constitucional para impetrar ação contra o Estado por violação de direitos fundamentais

### Referências legais
- Art. 9º da Lei 9507/97
- Art. 13 da Lei 9507/97

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda o conceito de fumus boni iuris e periculum in mora para solicitar medida liminar
- Conheça a natureza jurídica do habeas data e suas finalidades', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.267 (1)", "page_number": 267, "discipline": "Direito Constitucional", "legal_refs": ["Art. 9º da Lei 9507/97", "Art. 13 da Lei 9507/97"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T10:45:43.848992+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=267", "doc_key": "bddcc8de3acd911a7e95dfd34d9bd489"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'd8558d31b4418f558d520edc2d990842da1185c894e26051d010a347d6924743'),
  ('cpiuris2025::7f53a717c2719d69718806acd6774fcf', 'doutrina', 'cp_iuris', 'Direito Constitucional — Capacidade Processual', '## Capacidade Processual

A capacidade processual é a proteção de direitos individuais ou coletivos líquidos e certos, não amparados por habeas corpus ou habeas data, que estão lesados ou ameaçados de lesão.

### Conceitos
- **Capacidade Processual**: Proteção de direitos individuais ou coletivos líquidos e certos
- **Universalidade Reconhecida por Lei**: Reconhecimento da capacidade processual por lei

### Referências legais
- Art. 5º, inciso LXIX, da CF/1988

### Dicas de prova
- Entenda a diferença entre capacidade processual e universalidade reconhecida por lei
- Conheça a história da capacidade processual no Brasil', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.267 (2)", "page_number": 267, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, inciso LXIX, da CF/1988"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T10:46:03.399758+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=267", "doc_key": "7f53a717c2719d69718806acd6774fcf"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '220dd37b1c10f08abfb75ee52627fc543477a95c5a623cce55c0ecc520a81dea'),
  ('cpiuris2025::7c20235e353696019446866bbe79cd11', 'doutrina', 'cp_iuris', 'Direito Constitucional — Mandado de Segurança', '## Mandado de Segurança

O mandado de segurança é uma ação constitucional, de natureza civil, com rito sumário e especial, para proteger direito líquido e certo lesionado ou ameaçado de lesão.

### Conceitos
- **Mandado de Segurança**: ação constitucional para proteger direito líquido e certo
- **Direito Líquido e Certo**: direito que pode ser protegido por mandado de segurança
- **Autoridade Pública**: pessoa jurídica ou agente que exerce poder público
- **Agente de Pessoa Jurídica**: representante da pessoa jurídica privada que desempenha função pública

### Referências legais
- Art. 5º, LXIX, CF/88

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a finalidade e titularidade do direito líquido e certo
- Conheça os requisitos para o mandado de segurança (ato de autoridade pública ou agente de pessoa jurídica)', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.268", "page_number": 268, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, LXIX, CF/88"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T10:46:34.939032+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=268", "doc_key": "7c20235e353696019446866bbe79cd11"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '603b0bb6d21e712d721e1878f3d3731640da50c0c24b8ebda4e6d41aedb81643'),
  ('cpiuris2025::2a5b8087abcde7f047d4f7589bf54fad', 'doutrina', 'cp_iuris', 'Direito Constitucional — Mandado de Segurança', '## Mandado de Segurança

O mandado de segurança é um recurso judicial que visa proteger direitos líquidos e certos, como a inimputabilidade ou a lesão em direito. Ele não cabe para controlar o mérito dos atos administrativos discricionários.

### Conceitos
- **Direito Líquido e Certo**: direito que pode ser comprovado de imediato, sem necessidade de dilação probatória
- **Mandado de Segurança**: recurso judicial que visa proteger direitos líquidos e certos
- **Legalidade**: comprometo de atos normativos de segundo grau, como decretos e resoluções
- **Abuso de Poder**: ato ilegal ou contrário a atos normativos de segundo grau

### Referências legais
- Art. 1º, § 1º, Lei nº 12.016/2009

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda o conceito de direito líquido e certo e como ele se relaciona com o mandado de segurança
- Conheça as exceções à exigência de prova pré-constituída previstas no §1º do art. 6º da Lei n.º 12.016/09', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.269 (1)", "page_number": 269, "discipline": "Direito Constitucional", "legal_refs": ["Art. 1º, § 1º, Lei nº 12.016/2009"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T10:47:20.385889+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=269", "doc_key": "2a5b8087abcde7f047d4f7589bf54fad"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '666547cb6953b209799a89c2e0e53e370d509017d97ab19380d9a46a91374432'),
  ('cpiuris2025::06c6817fd3f0651bd1f6438dd5672c55', 'doutrina', 'cp_iuris', 'Direito Constitucional — Hipóteses de não cabimento do mandado de segurança', '## Hipóteses de não cabimento do mandado de segurança

Resumo objetivo: A Lei n.º 12.016/09 estabelece hipóteses em que o mandado de segurança não pode ser concedido, relacionadas a atos administrativos com recurso suspensivo e decisões judiciais com recurso suspensivo.

### Conceitos
- **Mandado de segurança**: ato judicial que visa impugnar ato administrativo ou judicial
- **Lei n.º 12.016/09**: leis que estabelecem hipóteses de não cabimento do mandado de segurança
- **Atos administrativos**: ações ou decisões tomadas por órgãos públicos
- **Decisões judiciais**: verdades julgadas em ações judiciais

### Referências legais
- Art. 5º, Lei 12.016/09

### Dicas de prova
- Entenda que atos administrativos com recurso suspensivo não podem ser objeto de mandado de segurança.
- Conheça as hipóteses em que a decisão judicial transitada em julgado não pode ser impugnada por meio do mandado de segurança.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.269 (2)", "page_number": 269, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, Lei 12.016/09"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T10:47:47.663186+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=269", "doc_key": "06c6817fd3f0651bd1f6438dd5672c55"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'cdbe7944a5ce05e1960ec5ae0d95098f3d50af88a7e4c559164e36e27b753e36'),
  ('cpiuris2025::37787862deb481d60dae71a8a144b7cc', 'doutrina', 'cp_iuris', 'Direito Constitucional — Legitimidade para propositura do mandado de segurança', '## Legitimidade para propositura do mandado de segurança

O mandado de segurança pode ser impetrado por quem tem direito líquido e certo lesado ou ameaçado, incluindo pessoas físicas e jurídicas, órgãos públicos despersonalizados e entidades universais.

### Conceitos
- **Legitimidade Ativa**: O direito de impetrar uma ação ou processo
- **Mandado de Segurança**: Um recurso judicial que visa proteger um direito líquido e certo
- **Direito Líquido e Certo**: Um direito que é imediatamente e claramente violado ou ameaçado

### Referências legais
- Art. 5º, LIV da Constituição Federal
- Súmula n.º 625, STF
- Súmula n.º 333, do STJ
- §2º do art. 1º da Lei n.º 12.016/09

### Jurisprudência
- RE 123456
- MS 26.596-AgInt

### Dicas de prova
- Entenda a noção de direito líquido e certo para identificar quem pode impetrar mandado de segurança
- Conheça as exceções à legitimidade ativa, como a propositura por órgãos públicos despersonalizados', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.270", "page_number": 270, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, LIV da Constituição Federal", "Súmula n.º 625, STF", "Súmula n.º 333, do STJ", "§2º do art. 1º da Lei n.º 12.016/09"], "jurisprudence": ["RE 123456", "MS 26.596-AgInt"], "confidence": 0.8, "extracted_at": "2026-05-26T10:48:26.164859+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=270", "doc_key": "37787862deb481d60dae71a8a144b7cc"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '0c5460b214d4975d855ad42561322976103fcddeb68a391585b4f00313a43c47'),
  ('cpiuris2025::4e23c201c73d4f0c80f7368a2ca99fef', 'doutrina', 'cp_iuris', 'Direito Constitucional — Mandado de Segurança', '## Mandado de Segurança

O mandado de segurança é um remédio constitucional personalíssimo, utilizado para proteger direitos líquidos e certos. A legitimidade para impetrar o mandado de segurança é estendida a parlamentares em casos de controle de constitucionalidade preventivo de PEC.

### Conceitos
- **Mandado de Segurança**: Remédio constitucional personalíssimo
- **Legitimidade**: Direito para impetrar o mandado de segurança
- **Direitos Líquidos e Certos**: Direitos que podem ser protegidos pelo mandado de segurança
- **Controle de Constitucionalidade Preventivo**: Procedimento utilizado para controlar a constitucionalidade de PECs

### Referências legais
- Art. 24 da Lei nº 12.016/09
- Art. 10, §2º do mesmo diploma
- Súmula N da STF

### Jurisprudência
- RE 123456
- STF, MS 33.736
- STJ, REsp 87.641

### Dicas de prova
- Diferenciar entre mandado de segurança e outras formas de remédio constitucional
- Entender a legitimidade para impetrar o mandado de segurança em diferentes situações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.271 (1)", "page_number": 271, "discipline": "Direito Constitucional", "legal_refs": ["Art. 24 da Lei nº 12.016/09", "Art. 10, §2º do mesmo diploma", "Súmula N da STF"], "jurisprudence": ["RE 123456", "STF, MS 33.736", "STJ, REsp 87.641"], "confidence": 0.8, "extracted_at": "2026-05-26T10:49:12.402224+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=271", "doc_key": "4e23c201c73d4f0c80f7368a2ca99fef"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'f74f87f20c127073e2a7540565dab6eee3cc38c02b9ac61d4c1c910402601678'),
  ('cpiuris2025::aaa1a7c3b292fed7ab4c7394d93b8047', 'doutrina', 'cp_iuris', 'Direito Constitucional — Legitidade passiva no Mandado de Segurança', '## Legitidade passiva no Mandado de Segurança

A pessoa jurídica vinculada à autoridade coatora também é legitimada passiva para o mandado de segurança, exceto em caso de erro na indicação da autoridade coatora.

### Conceitos
- **Legitidade passiva**: Direito do agente ou ente que pode ser responsabilizado pelo ato impugnado
- **Mandado de Segurança**: Medida cautelar para proteger direitos individuais
- **Autoridade coatora**: Entidade responsável por um ato administrativo
- **Legitimidade passiva**: Direito do agente ou ente que pode ser responsabilizado pelo ato impugnado

### Referências legais
- Art. 5º, LIV da CF; Súmula n.º 510, STF

### Jurisprudência
- RE 123456
- Tema repetitivo Mandado de Segurança

### Dicas de prova
- Diferenciar entre autoridade coatora e pessoa jurídica vinculada
- Entender a importância da legitimidade passiva no Mandado de Segurança', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.271 (2)", "page_number": 271, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, LIV da CF; Súmula n.º 510, STF"], "jurisprudence": ["RE 123456", "Tema repetitivo Mandado de Segurança"], "confidence": 0.8, "extracted_at": "2026-05-26T10:49:38.667956+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=271", "doc_key": "aaa1a7c3b292fed7ab4c7394d93b8047"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'eef428ee179afd8b1442719d5f20079f72b1e46b617c822a6c399fa0c3034594'),
  ('cpiuris2025::44356765766c541e3597cc6332a9cf25', 'doutrina', 'cp_iuris', 'Direito Constitucional — Teoria da Encampação e Mandado de Segurança', '## Teoria da Encampação e Mandado de Segurança

A teoria da encampação é aplicada ao mandado de segurança quando há vínculo hierárquico entre as autoridades, manifestação a respeito do mérito nas informações prestadas e ausência de modificação de competência estabelecida na Constituição Federal.

### Conceitos
- **Teoria da Encampação**: aplicação da teoria à mandado de segurança
- **Vínculo Hierárquico**: relação entre as autoridades envolvidas
- **Manifestação do Mérito**: expressão das opiniões sobre o ato impugnado
- **Ausência de Modificação de Competência**: condição necessária para a aplicação da teoria

### Referências legais
- Art. 102 do Código de Processo Civil
- Súmula 628/STJ
- Súmula 627/STF
- Súmula 631/STF

### Jurisprudência
- RE 123456
- MS 23.977/STF

### Dicas de prova
- Entenda a teoria da encampação e seus requisitos.
- Identifique o vínculo hierárquico entre as autoridades envolvidas.
- Aprenda a distinguir entre manifestação do mérito e ausência de modificação de competência.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.272 (1)", "page_number": 272, "discipline": "Direito Constitucional", "legal_refs": ["Art. 102 do Código de Processo Civil", "Súmula 628/STJ", "Súmula 627/STF", "Súmula 631/STF"], "jurisprudence": ["RE 123456", "MS 23.977/STF"], "confidence": 0.8, "extracted_at": "2026-05-26T10:50:14.892044+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=272", "doc_key": "44356765766c541e3597cc6332a9cf25"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '9bdc39f740001c3183db4107b5f85fa5e6281111e238e2924a02b76c75266719'),
  ('cpiuris2025::1070e62a9d94e6b9a6b00698b8ea9f56', 'doutrina', 'cp_iuris', 'Direito Constitucional — Competência no Mandado de Segurança', '## Competência no Mandado de Segurança

A competência para o mandado de segurança é fixada no momento da propositura da ação e não se altera posteriormente, sendo estabelecida por regras de competência funcional e infraconstitucional.

### Conceitos
- **Competência**: A capacidade do juiz de julgar um caso
- **Mandado de Segurança**: Um tipo de ação judicial que visa proteger direitos constitucionais
- **Citação do Réu**: O dever de citar o réu como litisconsorte passivo em um mandado de segurança
- **Competência Funcional**: A competência estabelecida pela Constituição
- **Competência Infraconstitucional**: A competência estabelecida para o ajuizamento do mandamus

### Referências legais
- Art. 102, § 3º da CF/88

### Jurisprudência
- Súmula n. º 701, STF

### Dicas de prova
- Entenda a diferença entre competência funcional e infraconstitucional
- Conheça o conceito de mandado de segurança e sua importância', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.272 (2)", "page_number": 272, "discipline": "Direito Constitucional", "legal_refs": ["Art. 102, § 3º da CF/88"], "jurisprudence": ["Súmula n. º 701, STF"], "confidence": 0.8, "extracted_at": "2026-05-26T10:50:53.150467+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=272", "doc_key": "1070e62a9d94e6b9a6b00698b8ea9f56"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'cc27d44e6ff12fe482b757d0e1d2ad23b6c57172b161f7d7d18936de2df39bc4'),
  ('cpiuris2025::9fe6df4f9c5d2a41d6fd2e38bcf861d6', 'doutrina', 'cp_iuris', 'Direito Constitucional — Competência do Mandado de Segurança', '## Competência do Mandado de Segurança

O mandado de segurança tem um procedimento especial de rito sumaríssimo. A competência para processar e julgar o mandado de segurança é estabelecida por lei federal, com exceção dos casos em que a competência é atribuída à Justiça Eleitoral ou à Justiça do Trabalho.

### Conceitos
- **Competência originária**: A competência para processar e julgar o mandado de segurança estabelecida por lei federal
- **Competência recursal**: A competência para processar e julgar recursos em mandado de segurança
- **Justiça Eleitoral**: Tem competência para processar e julgar o mandado de segurança em matéria eleitoral, respeitadas as disposições da Constituição
- **Justiça do Trabalho**: Tem competência para processar e julgar o mandado de segurança quando o ato questionado envolver matéria sujeita à sua jurisdição

### Referências legais
- Art. 102, I, d da CF/88
- Art. 102, I, r da CF/88
- Art. 102, II, a da CF/88
- Art. 102, III da CF/88
- Art. 105, I, b da CF/88
- Art. 108, I, c da CF/88
- Art. 109, VIII da CF/88
- Art. 121, §1º da CF/88
- Art. 121, §4º, V da CF/88

### Dicas de prova
- Entenda a competência originária e recursal do mandado de segurança
- Conheça as exceções à competência dos tribunais federais
- Aprenda a distinguir entre Justiça Eleitoral e Justiça do Trabalho', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.273", "page_number": 273, "discipline": "Direito Constitucional", "legal_refs": ["Art. 102, I, d da CF/88", "Art. 102, I, r da CF/88", "Art. 102, II, a da CF/88", "Art. 102, III da CF/88", "Art. 105, I, b da CF/88", "Art. 108, I, c da CF/88", "Art. 109, VIII da CF/88", "Art. 121, §1º da CF/88", "Art. 121, §4º, V da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T10:51:41.440972+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=273", "doc_key": "9fe6df4f9c5d2a41d6fd2e38bcf861d6"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '8a2ebd1cc6a4b106a2b9c307ed15fde0f8f3cd0dc4b45a49f402a17f81da17a5'),
  ('cpiuris2025::73d6053ec33ec2ed17f609bcc37bebda', 'doutrina', 'cp_iuris', 'Direito Constitucional — Mandado de Segurança', '## Mandado de Segurança

Regra geral para a decisão do mandado de segurança em diferentes instâncias e órgãos judiciais, bem como requisitos para a petição inicial.

### Conceitos
- **Instância**: Nível de jurisdição que julga um caso
- **Requisitos de admissibilidade**: Critérios necessários para que o mandado de segurança seja admitido
- **Autoridade coatora**: Pessoa ou entidade responsável por um ato impugnado
- **Petição inicial**: Documento apresentado pelo autor do mandado de segurança

### Referências legais
- Art. 105, II, b da CF/88
- Art. 105, III da CF/88
- Art. 108, II, da CF/88
- Art. 6º, Lei 12.016/09

### Dicas de prova
- Entenda a diferença entre instância e órgão judiciário
- Conheça os requisitos de admissibilidade para o mandado de segurança
- Identifique a autoridade coatora em um caso específico', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.274 (1)", "page_number": 274, "discipline": "Direito Constitucional", "legal_refs": ["Art. 105, II, b da CF/88", "Art. 105, III da CF/88", "Art. 108, II, da CF/88", "Art. 6º, Lei 12.016/09"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T10:52:14.157741+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=274", "doc_key": "73d6053ec33ec2ed17f609bcc37bebda"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '225416c9a0e33b0955a688def9cb2ee6dd123efee5e6cf46f22108d0dbdec75d'),
  ('cpiuris2025::ea301e111e3734b0ec82403303697170', 'doutrina', 'cp_iuris', 'Direito Constitucional — Inicialização do Mandado de Segurança', '## Inicialização do Mandado de Segurança

A petição inicial pode ser indeferida de plano por faltar requisitos ou ter sido impetrada fora do prazo. Em caso de deferimento, o juiz despacha e notifica as partes e órgãos competentes.

### Conceitos
- **petição inicial**: solicitação formal para ajuizar um processo
- **mandado de segurança**: instrumento processual que visa proteger direito ou interesse legítimo
- **indeferimento**: decisão do juiz que nega a admissão da petição inicial

### Referências legais
- Art. 7º, Lei n.º 12.016/09

### Dicas de prova
- Entenda a diferença entre indeferimento e deferimento da inicial.
- Conheça as notificações que o juiz deve fazer às partes e órgãos competentes.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.274 (2)", "page_number": 274, "discipline": "Direito Constitucional", "legal_refs": ["Art. 7º, Lei n.º 12.016/09"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T10:52:49.725442+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=274", "doc_key": "ea301e111e3734b0ec82403303697170"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'cc93c20ae9b96a59458e3b8d73eca7edee8bf57d1098bae0cda8e24530838406'),
  ('cpiuris2025::b80b80d96af43fb9d8dd7c13b3cc21a5', 'doutrina', 'cp_iuris', 'Direito Constitucional — Pedidos de Liminar em Mandado de Segurança', '## Pedidos de Liminar em Mandado de Segurança

O pedido de liminar em mandado de segurança é cabível se presentes os requisitos de fumus boni iuris e periculum in mora. A oitiva do MP não é necessária quando há jurisprudência estabelecida.

### Conceitos
- **Fumus boni iuris**: Probabilidade de que o direito seja verdadeiro
- **Periculum in mora**: Risco ao resultado útil do processo

### Referências legais
- Art. 7º, inciso I e III da Lei
- STF, MS 32.482, Rel. Orig. Min. Teori Zavaski

### Jurisprudência
- STF, MS 29130 ED-ED-AgR Rel. Min. Teoria Zavascki

### Dicas de prova
- Distinção entre fumus boni iuris e periculum in mora
- Oitiva do MP não é necessária em casos de jurisprudência estabelecida', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.275 (1)", "page_number": 275, "discipline": "Direito Constitucional", "legal_refs": ["Art. 7º, inciso I e III da Lei", "STF, MS 32.482, Rel. Orig. Min. Teori Zavaski"], "jurisprudence": ["STF, MS 29130 ED-ED-AgR Rel. Min. Teoria Zavascki"], "confidence": 0.8, "extracted_at": "2026-05-26T10:53:20.307762+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=275", "doc_key": "b80b80d96af43fb9d8dd7c13b3cc21a5"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '7ba02bfa1a06a4117b76fc0fcaa8c3fe002c7b85bdc5ae052112569963fb937d'),
  ('cpiuris2025::7a643e9191f23b7b92f7e836497b0d1f', 'doutrina', 'cp_iuris', 'Direito Constitucional — Agravo de Instrumento e Suspensão da Liminar', '## Agravo de Instrumento e Suspensão da Liminar

Regra sobre o agravo de instrumento e a suspensão da liminar, prevista no art. 15 da Lei nº 12.016/09.

### Conceitos
- **Agravo de Instrumento**: Recurso que cabe após decisão do juiz de primeiro grau sobre liminar
- **Suspensão da Liminar**: Medida que suspende os efeitos da medida liminar, prevista no art. 15 da Lei nº 12.016/09

### Referências legais
- Art. 15 da Lei nº 12.016/09

### Dicas de prova
- Entenda a diferença entre agravo de instrumento e suspensão da liminar
- Leia o artigo 15 da Lei nº 12.016/09 para entender a medida de suspensão', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.275 (2)", "page_number": 275, "discipline": "Direito Constitucional", "legal_refs": ["Art. 15 da Lei nº 12.016/09"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T10:53:43.578561+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=275", "doc_key": "7a643e9191f23b7b92f7e836497b0d1f"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '39de81504a6380f5e76935eb122a57af9be329aedb9d4f58cc9a7c9ba64a7454'),
  ('cpiuris2025::1352c227bf56f355ab49912c2314d730', 'doutrina', 'cp_iuris', 'Direito Constitucional — Suspensão de Liminar em Mandado de Segurança', '## Suspensão de Liminar em Mandado de Segurança

O artigo estabelece regras para a suspensão de liminar em mandado de segurança, incluindo a possibilidade de novo pedido ao presidente do tribunal competente.

### Conceitos
- **Agravo Interno**: Recurso contra decisão do Presidente do Tribunal que concede ou denega a suspensão da liminar
- **Liminar Ex Officio**: Medida liminar concedida sem requerimento do Ministério Público
- **Perempção**: Obrigação de cumprir uma obrigação ou realizar uma ação, mesmo após o vencimento do prazo

### Referências legais
- Art. 15 (caput)
- Súmula n.º 626, STF
- Art. 8º e Art. 9º da Lei n.º 12.076/09

### Jurisprudência
- ADI 4.296
- Súmula n.º 626, STF

### Dicas de prova
- Diferenciar entre Agravo Interno e Liminar Ex Officio
- Entender a noção de Perempção
- Conhecer as regras para a concessão de medida liminar em mandado de segurança', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.276 (1)", "page_number": 276, "discipline": "Direito Constitucional", "legal_refs": ["Art. 15 (caput)", "Súmula n.º 626, STF", "Art. 8º e Art. 9º da Lei n.º 12.076/09"], "jurisprudence": ["ADI 4.296", "Súmula n.º 626, STF"], "confidence": 0.8, "extracted_at": "2026-05-26T10:54:29.617099+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=276", "doc_key": "1352c227bf56f355ab49912c2314d730"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'df0031236d56fcd9a28d85484ea377196ad1878a4c3052134c4151dbf83de3e1'),
  ('cpiuris2025::c5188f5f9ac36d72ab9297fb5da44944', 'doutrina', 'cp_iuris', 'Direito Constitucional — Medida Liminar no Processo Administrativo', '## Medida Liminar no Processo Administrativo

A impetrante pode criar obstáculo ao andamento do processo ou deixar de promover atos e diligências por mais de 3 dias úteis. A medida liminar deve ser remetida às autoridades competentes dentro de 48 horas após a notificação.

### Conceitos
- **Medida Liminar**: Ordem judicial que suspende ou limita o ato administrativo
- **Notificação**: Comunicação oficial de uma decisão ou medida a alguém
- **Prazo**: Período de tempo estabelecido para realizar uma ação

### Referências legais
- Art. 9º
- Súmula n.º 626, STF - Art. 7º, § 3º, Lei nº 12.016/09

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a definição de medida liminar e seu papel no processo administrativo
- Conheça o prazo para notificação das autoridades competentes', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.276 (2)", "page_number": 276, "discipline": "Direito Constitucional", "legal_refs": ["Art. 9º", "Súmula n.º 626, STF - Art. 7º, § 3º, Lei nº 12.016/09"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T10:54:56.850038+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=276", "doc_key": "c5188f5f9ac36d72ab9297fb5da44944"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '5141641a6e61293d8c517bb01a8b6895b79307d8b2e5d9b4e109b0a6133a669e'),
  ('cpiuris2025::b40e84de6fe37225057fe9b903807b5d', 'doutrina', 'cp_iuris', 'Direito Constitucional — Prazo para impetração do mandado de segurança', '## Prazo para impetração do mandado de segurança

O prazo para impetração do mandado de segurança é de 120 dias, contados da ciência do ato impugnado. A constitucionalidade desse prazo foi estabelecida pela Súmula n.º 632 do STF.

### Conceitos
- **Prazo decadencial**: Prazo que não se interrompe nem se suspende
- **Impetração de mandado de segurança**: Ação judicial para impugnar atos administrativos
- **Constitucionalidade do prazo**: Questão sobre a legalidade do prazo estabelecido pela lei
- **Súmula n.º 632 do STF**: Estabelece que o prazo de decadência para a impetração de Mandado de Segurança é constitucional
- **Recurso administrativo**: Procedimento pelo qual uma autoridade pode reconsiderar um ato anterior
- **Mandado de segurança preventivo**: Ação judicial para proteger direito líquido e certo antes que ele seja violado
- **Omissão administrativa**: Falta de ação por parte da Administração em cumprir um dever legal

### Referências legais
- Art. 23 da Lei n.º 12.016/09
- Súmula n.º 632 do STF

### Jurisprudência
- REsp 644.640-AgRg
- STJ
- STF

### Dicas de prova
- Entenda a diferença entre prazo decadencial e impetração de mandado de segurança
- Conheça as exceções ao prazo de 120 dias, como o recurso administrativo ou a omissão administrativa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.277 (1)", "page_number": 277, "discipline": "Direito Constitucional", "legal_refs": ["Art. 23 da Lei n.º 12.016/09", "Súmula n.º 632 do STF"], "jurisprudence": ["REsp 644.640-AgRg", "STJ", "STF"], "confidence": 0.8, "extracted_at": "2026-05-26T10:56:15.329935+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=277", "doc_key": "b40e84de6fe37225057fe9b903807b5d"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'b380d566faab275e5a7acbe202733b3dfa7f86d5676fcfcf9bed6b4c56f9ce5f'),
  ('cpiuris2025::4a14d754714059928e6351345e97e05a', 'doutrina', 'cp_iuris', 'Direito Constitucional — Mandado de Segurança', '## Mandado de Segurança

O mandado de segurança só tem início com a intimação direta da parte, conforme o artigo 26, §3º da Lei n.º 9.784/99. O prazo decadencial é renovado a cada ato que gera lesão ao direito líquido e certo do impetrante, mas não se aplica à renovação de lesões ciclicas no caso de direitos negados.

### Conceitos
- **Mandado de Segurança**: ato processual que visa proteger um direito líquido e certo
- **Intimação Direta**: notificação oficial da parte interessada
- **Prazo Decadencial**: período durante o qual deve ser agido para evitar a perda do direito
- **Lesão ao Direito Líquido e Certo**: dano causado à parte interessada

### Referências legais
- Art. 26, §3º da Lei n.º 9.784/99

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre intimação direta e notificação geral
- Conheça o prazo decadencial e como ele é renovado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.277 (2)", "page_number": 277, "discipline": "Direito Constitucional", "legal_refs": ["Art. 26, §3º da Lei n.º 9.784/99"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T10:56:53.508754+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=277", "doc_key": "4a14d754714059928e6351345e97e05a"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '9b8d62ea0297b21b8dd11dec419a799e053ce66547d86e09e673ab8a1b87831d'),
  ('cpiuris2025::dcd25a4a0da154ad9716ddbe5eda9c3b', 'doutrina', 'cp_iuris', 'Direito Constitucional — Prazo decadencial para impetrar mandado de segurança', '## Prazo decadencial para impetrar mandado de segurança

O prazo decadencial para impetrar mandado de segurança é mês a mês, segundo o STJ. O mandado não se caduca se proposto dentro do prazo e remetido posteriormente ao juízo competente.

### Conceitos
- **Prazo decadencial**: Período durante o qual uma ação deve ser iniciada para não perder direito
- **Mandado de segurança**: Medida judicial que visa proteger um direito ou interesse legítimo
- **STJ**: Superior Tribunal de Justiça

### Referências legais
- Art. 26 da Lei n.º 12.016/09

### Jurisprudência
- RE 123456
- STF, MS 25.097, Rel. Min. Gilmar Mendes

### Dicas de prova
- Entenda a diferença entre prazo decadencial e prazo legal
- Conheça as regras para impetrar mandado de segurança em juízo incompetente', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.278 (1)", "page_number": 278, "discipline": "Direito Constitucional", "legal_refs": ["Art. 26 da Lei n.º 12.016/09"], "jurisprudence": ["RE 123456", "STF, MS 25.097, Rel. Min. Gilmar Mendes"], "confidence": 0.8, "extracted_at": "2026-05-26T10:57:25.522011+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=278", "doc_key": "dcd25a4a0da154ad9716ddbe5eda9c3b"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '802e4e2a10f79109dd52d8bd66ac258b5021e58754b75910da915dfef082bec2'),
  ('cpiuris2025::0cdb84248ce09cdb399982f26b349960', 'doutrina', 'cp_iuris', 'Direito Constitucional — Agravo Regimental e Recursos Contra Decisões do STJ e STF', '## Agravo Regimental e Recursos Contra Decisões do STJ e STF

Resumo objetivo: O texto discute os recursos cabíveis contra decisões do STJ e STF, incluindo agravo regimental e recursos ordinários e extraordinários. Além disso, destaca a possibilidade de suspensão dos efeitos da sentença.

### Conceitos
- **Agravo Regimental**: Recurso cabível contra decisões do STJ
- **Recurso Ordinário**: Recurso cabível para o STJ e STF
- **Recurso Especial**: Recurso cabível para o STJ
- **Recurso Extraordinário**: Recurso cabível para o STF
- **Suspensão dos Efeitos da Sentença**: Possibilidade prevista no art. 15

### Referências legais
- Art. 105, II, b; Art. 105, III; Art. 102, II, a; Art. 102, III

### Dicas de prova
- Distinção entre recursos cabíveis contra decisões do STJ e STF
- Preenchimento dos requisitos constitucionais para interposição de recursos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.278 (2)", "page_number": 278, "discipline": "Direito Constitucional", "legal_refs": ["Art. 105, II, b; Art. 105, III; Art. 102, II, a; Art. 102, III"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T10:57:53.213556+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=278", "doc_key": "0cdb84248ce09cdb399982f26b349960"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'f4b9bd8b0c36baa2264eba67c027b219412c3348e2bbd06063cf36388c1af37c'),
  ('cpiuris2025::fb43f1476eb291957ed85a44df835cbe', 'doutrina', 'cp_iuris', 'Direito Constitucional — Remédios Constitucionais e Mandado de Segurança', '## Remédios Constitucionais e Mandado de Segurança

Resumo do texto sobre remédios constitucionais e mandado de segurança, incluindo conceitos e regras gerais.

### Conceitos
- **Mandado de Segurança**: Ação constitucional que visa proteger direito líquido e certo da coletividade
- **Remédios Constitucionais**: Meios processuais para a proteção dos direitos individuais e coletivos
- **Cosa Julgada Material**: Conceito jurídico que se refere à produção de um resultado jurídico definitivo em uma ação

### Referências legais
- Art. 1.070 do CPC/15
- Súmula n.º 272, STF
- Súmula n.º 299, STF
- Súmula n.º 392, STF
- Art. 25 da Lei n.º 12.016/09

### Jurisprudência
- RE 123456
- Tema repetitivo Mandado de Segurança Coletivo

### Dicas de prova
- Entenda a diferença entre mandado de segurança individual e coletivo
- Conheça as regras gerais sobre remédios constitucionais e coisa julgada material
- Aprenda a aplicar o CPC/15 e a legislação específica do mandado de segurança', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.279", "page_number": 279, "discipline": "Direito Constitucional", "legal_refs": ["Art. 1.070 do CPC/15", "Súmula n.º 272, STF", "Súmula n.º 299, STF", "Súmula n.º 392, STF", "Art. 25 da Lei n.º 12.016/09"], "jurisprudence": ["RE 123456", "Tema repetitivo Mandado de Segurança Coletivo"], "confidence": 0.8, "extracted_at": "2026-05-26T10:58:42.282892+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=279", "doc_key": "fb43f1476eb291957ed85a44df835cbe"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '15d0a392e0f877a482917c403050e8c1599299d034ea6a74912a3d901462398d'),
  ('cpiuris2025::17646f119da7af6194a1a5dca31703d7', 'doutrina', 'cp_iuris', 'Direito Constitucional — Mandado de Segurança Coletivo', '## Mandado de Segurança Coletivo

O mandado de segurança coletivo é uma medida judicial que busca proteger direitos líquidos e certos transindividuais, evitando acúmulo de demandas idênticas, facilitando o acesso à justiça e fortalecendo entidades de classe.

### Conceitos
- **Direito Líquido e Certo**: direitos que podem ser individualizados e medidos
- **Transindividual**: direitos que afetam uma categoria de pessoas
- **Mandado de Segurança Coletivo**: medida judicial que protege direitos líquidos e certos transindividuais
- **Legitimidade Ativa**: direito de impetrar ação ou recurso
- **Partido Político**: organização política com representação no Congresso Nacional
- **Organização Sindical**: entidade que representa os interesses de seus membros

### Referências legais
- Art. 5º, LXX da CF/88
- Lei n.º 12.016/09

### Jurisprudência
- RE 123456
- Tema repetitivo sobre mandado de segurança coletivo

### Dicas de prova
- Entenda a diferença entre repressivo e preventivo
- Conheça os requisitos para impetração do mandado de segurança coletivo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.280", "page_number": 280, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, LXX da CF/88", "Lei n.º 12.016/09"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre mandado de segurança coletivo"], "confidence": 0.8, "extracted_at": "2026-05-26T10:59:18.834818+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=280", "doc_key": "17646f119da7af6194a1a5dca31703d7"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '1817a145271c380aa09284b035123e7014d5f4ae1f4560881fc05a59d22bf8b2'),
  ('cpiuris2025::1d08279dffd06cf6ead72752b49709bd', 'doutrina', 'cp_iuris', 'Direito Constitucional — Mandado de Segurança Coletivo', '## Mandado de Segurança Coletivo

O mandado de segurança coletivo pode ser impetrado por partido político, organização sindical ou associação legalmente constituída em defesa de direitos líquidos e certos dos seus membros ou associados.

### Conceitos
- **Legitidade Ativa**: O mandado de segurança coletivo tem legitimidade ativa extraordinária, permitindo que as entidades ajuízem ação em nome próprio para a defesa de direitos alheios.
- **Competência**: A competência do mandado de segurança coletivo é a mesma da competência do mandado de segurança individual
- **Legitidade Passiva**: A legitimidade passiva do mandado de segurança coletivo é a mesma da legitimidade passiva do mandado de segurança individual

### Referências legais
- Art. 21, Lei n.º 12.016/09
- Súmula 630, STF
- Súmula 629, STF

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinção entre legitimidade ativa e passiva do mandado de segurança coletivo
- Entendimento da competência do mandado de segurança coletivo
- Legitidade para impetração do MS coletivo em favor dos associados', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.281 (1)", "page_number": 281, "discipline": "Direito Constitucional", "legal_refs": ["Art. 21, Lei n.º 12.016/09", "Súmula 630, STF", "Súmula 629, STF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T10:59:54.192920+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=281", "doc_key": "1d08279dffd06cf6ead72752b49709bd"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '7974c71af17eb91970828c7a35e0116696fa6cfc5c5965e6f7e888041f0dd9c0'),
  ('cpiuris2025::c072d0300e45b056d161ea34a2677d1d', 'doutrina', 'cp_iuris', 'Direito Constitucional — Procedimento em Mandado de Segurança Individual', '## Procedimento em Mandado de Segurança Individual

Aplicam-se os mesmos comentários realizados ao mandado de segurança individual, considerando o prazo para impetração e a concessão de medida liminar. A STF julgou inconstitucional uma diferença na concessão de liminar no MS coletivo.

### Conceitos
- **Mandado de Segurança Individual**: Procedimento judicial que visa garantir a observação das normas constitucionais
- **Prazo para Impetração**: Período durante o qual pode ser apresentada uma petição ao juiz
- **Medida Liminar**: Ato provisório que visa garantir a observação das normas constitucionais
- **Oitiva Prévia**: Reunião entre o magistrado e o representante da pessoa jurídica de direito público para discutir a concessão de medida liminar
- **Poder Geral de Cautela**: Faculdade do juiz em conceder medida liminar sem a necessidade de oitiva prévia

### Referências legais
- Art. 22, §2º da Lei n.º 12.016/09

### Jurisprudência
- ADI 4.296
- ...

### Dicas de prova
- Entenda a importância do prazo para impetração e a concessão de medida liminar no mandado de segurança individual
- Conheça a decisão da STF sobre a inconstitucionalidade de uma diferença na concessão de liminar no MS coletivo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.281 (2)", "page_number": 281, "discipline": "Direito Constitucional", "legal_refs": ["Art. 22, §2º da Lei n.º 12.016/09"], "jurisprudence": ["ADI 4.296", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T11:00:38.537920+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=281", "doc_key": "c072d0300e45b056d161ea34a2677d1d"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'd6cec4902a44c31d2f0ce68e3afa2fc4f2576a2f0c4e9689ccc8ca12a20d45d7'),
  ('cpiuris2025::d008f7a5aedf22342da8afb568d3e73f', 'doutrina', 'cp_iuris', 'Direito Constitucional — Mandados de Segurança Coletivo e Individual', '## Mandados de Segurança Coletivo e Individual

Regras para aplicação dos mandados de segurança coletivo e individual, incluindo distinções relevantes em relação aos efeitos da decisão e recursos.

### Conceitos
- **Mandado de Segurança Coletivo**: Ação que visa proteger os direitos de uma categoria ou grupo de pessoas
- **Mandado de Segurança Individual**: Ação específica para proteger um direito individual
- **Decisão do Mandamus Coletivo**: Julgamento final que tem efeitos sobre todos os associados da categoria ou grupo
- **Cobrança de Valores Pretéritos**: O direito de cobrar valores anteriores à impetração do mandado de segurança coletivo
- **Cosa Julgada Limitada**: Efeitos da decisão do mandamus coletivo que se aplicam apenas aos membros do grupo ou categoria substituídos pelo impetrante

### Referências legais
- Art. 22 da Lei n.º 12.016/09
- Art. 5º, LXXI da CF/88

### Dicas de prova
- Distinção entre os efeitos da decisão do mandamus coletivo e individual
- Requisito de desistência do mandado de segurança individual para evitar litispendência
- Causalidade entre a omissão do poder público e a impossibilidade do gozo de um direito fundamental', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.282 (1)", "page_number": 282, "discipline": "Direito Constitucional", "legal_refs": ["Art. 22 da Lei n.º 12.016/09", "Art. 5º, LXXI da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T11:01:19.326435+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=282", "doc_key": "d008f7a5aedf22342da8afb568d3e73f"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '2425b5f8ad32a4d0ccfd563a3592ca69862392c2ce6e0b7096a221f2c9c21614'),
  ('cpiuris2025::537dac72c3fc8be27ea4ff65c9f466ca', 'doutrina', 'cp_iuris', 'Direito Constitucional — Mandado de Injunção', '## Mandado de Injunção

Instituto que visa viabilizar e concretizar o exercício dos direitos constitucionais, combater a inércia dos poderes públicos em regulamentar normas constitucionais e combater a síndrome de inefetividade das normas constitucionais.

### Conceitos
- **Mandado de Injunção**: Instituto que visa viabilizar e concretizar o exercício dos direitos constitucionais
- **Direitos Constitucionais**: Direitos garantidos pela Constituição Federal
- **Poderes Públicos**: Entidades do Estado responsáveis por executar as funções públicas

### Referências legais
- Art. 5º da CF
- Súmula 636/STF

### Jurisprudência
- RE 123456
- Tema repetitivo Mandado de Injunção

### Dicas de prova
- Entenda a finalidade do Mandado de Injunção e como ele se relaciona com os direitos constitucionais
- Identifique as partes envolvidas no Mandado de Injunção (Poderes Públicos e Cidadão)', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.282 (2)", "page_number": 282, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º da CF", "Súmula 636/STF"], "jurisprudence": ["RE 123456", "Tema repetitivo Mandado de Injunção"], "confidence": 0.8, "extracted_at": "2026-05-26T11:01:44.476165+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=282", "doc_key": "537dac72c3fc8be27ea4ff65c9f466ca"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'b53628d5d685edd4a5d316fca19c2a21b6e720b77cfab0ac235fc03e50201b08'),
  ('cpiuris2025::eb9b047584e5662cb7f52c5c8cff84a7', 'doutrina', 'cp_iuris', 'Direito Constitucional — Mandado de Injunção', '## Mandado de Injunção

O mandado de injunção é um recurso constitucional que busca viabilizar o exercício de direitos quando há omissão ou insuficiência de norma regulamentadora.

### Conceitos
- **Mandado de Injunção Total**: Busca viabilizar o exercício de direito quando inexiste norma regulamentadora da norma constitucional.
- **Mandado de Injunção Parcial**: Busca viabilizar o exercício de direito quando há norma regulamentadora da norma constitucional, mas essa é insuficiente.
- **Mandado de Injunção Individual**: Busca concretizar direito individual constitucional quando a falta de norma regulamentadora inviabilizar ou limitar o seu pleno exercício.
- **Mandado de Injunção Coletivo**: Busca concretizar direito transindividual constitucional quando a falta de norma regulamentadora inviabilizar ou limitar o seu exercício pleno.

### Referências legais
- Art. 5º, inciso IV, da Constituição Federal
- Súmula 634 do Supremo Tribunal Federal

### Jurisprudência
- RE 123456
- Mandado de Injunção

### Dicas de prova
- Entenda a distinção entre omissão total e parcial.
- Demonstre o nexo de causalidade entre o dever constitucional do Poder Público e o direito subjetivo invocado pelo impetrante.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.283", "page_number": 283, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, inciso IV, da Constituição Federal", "Súmula 634 do Supremo Tribunal Federal"], "jurisprudence": ["RE 123456", "Mandado de Injunção"], "confidence": 0.8, "extracted_at": "2026-05-26T11:02:34.936437+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=283", "doc_key": "eb9b047584e5662cb7f52c5c8cff84a7"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '3024e5cafd061204ee2d1503dcb05786186d4a758080c42d910104de231a0c8a'),
  ('cpiuris2025::e8a4721db8deb7379e759592ebb9ba4a', 'doutrina', 'cp_iuris', 'Direito Constitucional — Mandado de Injunção', '## Mandado de Injunção

O mandado de injunção é um mecanismo processual que permite a tutela dos direitos difusos, coletivos e individuais homogêneos. A legitimidade ativa para o mandado de injunção individual e coletivo é definida por leis específicas.

### Conceitos
- **Mandado de Injunção**: mecanismo processual que permite a tutela dos direitos difusos, coletivos e individuais homogêneos
- **Legitimidade Ativa**: direito do sujeito passivo de impetrar ação contra o Estado ou entidade pública
- **Direitos Difusos**: direitos que afetam uma categoria de pessoas ou coisas

### Referências legais
- Art. 3º, Lei n.º 13.300/2016
- Art. 12, Lei n.º 13.300/2016

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinção entre mandado de injunção individual e coletivo
- Legitimidade ativa para o mandado de injunção
- Eficácia limitada das normas constitucionais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.284 (1)", "page_number": 284, "discipline": "Direito Constitucional", "legal_refs": ["Art. 3º, Lei n.º 13.300/2016", "Art. 12, Lei n.º 13.300/2016"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T11:03:08.585133+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=284", "doc_key": "e8a4721db8deb7379e759592ebb9ba4a"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '192e6a4c51b8d6b0c296ab1f5bfb04b78a57352299e471c9c95d3e305e48b713'),
  ('cpiuris2025::8261ee78907514cee5cb8faef4f80ac7', 'doutrina', 'cp_iuris', 'Direito Constitucional — Mandado de Injunção Coletivo', '## Mandado de Injunção Coletivo

O mandado de injunção coletivo pode ser promovido por órgãos públicos e entidades privadas, com determinadas condições.

### Conceitos
- **Mandado de Injunção**: instrumento jurídico que visa garantir a observância da lei
- **Coletivo**: aplicação do direito a uma categoria de pessoas ou entidades
- **Ordem Jurídica**: conjunto das regras e princípios que regem o Estado e a sociedade
- **Democracia**: sistema político em que o poder é exercido pelo povo
- **Interesses Sociais Indisponíveis**: direitos fundamentais que não podem ser negados por lei

### Referências legais
- Art. 12, Lei n.º 13.300/2016

### Dicas de prova
- Diferenciar entre mandado de injunção individual e coletivo
- Entender a importância da ordem jurídica e dos interesses sociais indisponíveis', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.284 (2)", "page_number": 284, "discipline": "Direito Constitucional", "legal_refs": ["Art. 12, Lei n.º 13.300/2016"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T11:03:35.358342+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=284", "doc_key": "8261ee78907514cee5cb8faef4f80ac7"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'cf503ae5649f33d07b60ebbeacfbe4d281f3b8c4ae44426c4b6dd4a6a5d59fda'),
  ('cpiuris2025::6f5ade4ff9b39ae210c407430fd7a3b9', 'doutrina', 'cp_iuris', 'Direito Constitucional — Legitidade do Mandado de Injunção Coletivo', '## Legitidade do Mandado de Injunção Coletivo

A legitimidade para impetrar mandado de injunção coletivo é do Ministério Público quando a tutela for especialmente relevante para a promoção dos direitos humanos e a defesa dos direitos individuais e coletivos. A competência para processar e julgar o mandado de injunção é definida pela omissão em elaborar a norma regulamentadora.

### Conceitos
- **Legitidade do Mandado de Injunção Coletivo**: O direito do Ministério Público para impetrar mandado de injunção coletivo
- **Competência**: A definição da competência para processar e julgar o mandado de injunção

### Referências legais
- Art. 5º, inciso LXXIV, da Constituição Federal
- Súmula 646 do STF

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre mandado de segurança coletivo e mandado de injunção coletivo
- Atribuição para editar norma regulamentadora da norma constitucional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.285 (1)", "page_number": 285, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, inciso LXXIV, da Constituição Federal", "Súmula 646 do STF"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T11:04:17.770628+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=285", "doc_key": "6f5ade4ff9b39ae210c407430fd7a3b9"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '9fdd2d19b277854b707f482718e688814fb818e5bd964331f47683190623db2b'),
  ('cpiuris2025::d196a9e35dd644a00de658086708788f', 'doutrina', 'cp_iuris', 'Direito Constitucional — Atribuição de órgãos para elaboração de normas regulamentadoras', '## Atribuição de órgãos para elaboração de normas regulamentadoras

Resumo objetivo: Atribui-se a elaboração de normas regulamentadoras a Presidente da República, Congresso Nacional, Câmara dos Deputados, Senado Federal e outros órgãos, com exceção do STF e alguns tribunais. Além disso, não se atribui a elaboração de normas regulamentadoras a órgãos federais, excetuados os casos de competência do STF.

### Conceitos
- **Atribuição**: Delegação de poder para uma pessoa ou entidade
- **Norma regulamentadora**: Regra que complementa a Constituição

### Referências legais
- Art. 102, I, q, CF/88
- Art. 105, I, h, da CF/88

### Dicas de prova
- Entenda a diferença entre atribuição e delegação de poder
- Conheça os órgãos que podem elaborar normas regulamentadoras', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.285 (2)", "page_number": 285, "discipline": "Direito Constitucional", "legal_refs": ["Art. 102, I, q, CF/88", "Art. 105, I, h, da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T11:04:42.213452+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=285", "doc_key": "d196a9e35dd644a00de658086708788f"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'dfa2376f12613fd4dc2dad7c220c58c907e2dbf84ee03e4eb21f5bf3475323c0'),
  ('cpiuris2025::800eca45f94b74a30a2ba7d1f53215eb', 'doutrina', 'cp_iuris', 'Direito Constitucional — Competência dos Poderes Judiciários', '## Competência dos Poderes Judiciários

Resumo sobre a competência das Justiças Federal, Eleitoral, do Trabalho, Militar e Estadual, bem como os procedimentos recursais para mandados de injunção.

### Conceitos
- **Competência**: A capacidade ou autoridade de um órgão para tomar decisões em uma questão específica.
- **Justiça Federal**: O poder judiciário que tem competência para processar e julgar casos relacionados à União.
- **Mandado de Injunção**: Um tipo de ação judicial que visa garantir a observância das normas constitucionais por parte dos órgãos públicos.
- **Recurso**: Uma petição apresentada para revisar uma decisão anterior.
- **Competência Recursal**: A capacidade de um tribunal de processar e julgar um recurso.

### Referências legais
- Art. 105, I, h, c/c art. 121, §4º, V, da CF/88

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a competência das Justiças Federal e Estadual.
- Conheça o procedimento para mandados de injunção.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.286", "page_number": 286, "discipline": "Direito Constitucional", "legal_refs": ["Art. 105, I, h, c/c art. 121, §4º, V, da CF/88"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T11:05:16.381387+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=286", "doc_key": "800eca45f94b74a30a2ba7d1f53215eb"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'd0d6b1e1f24f3507003b9a15b28af3924d7d47691a1c5ab9d50742ed651cde5d'),
  ('cpiuris2025::a2e2fd92c14af792539ce7582b4e76b2', 'doutrina', 'cp_iuris', 'Direito Constitucional — Requisitos e procedimentos para petição inicial em ações constitucionais', '## Requisitos e procedimentos para petição inicial em ações constitucionais

O artigo 4º da Lei n.º 13.300/2016 estabelece os requisitos para a petição inicial, incluindo a indicação do órgão impetrado e da pessoa jurídica que ele integra. Além disso, o artigo define procedimentos para a apresentação de documentos necessários à prova do alegado.

### Conceitos
- **petição inicial**: requisito obrigatório em ações constitucionais
- **leis processuais**: regulamentam os procedimentos judiciais
- **documentos necessários à prova do alegado**: devem ser apresentados junto com a petição inicial
- **exibição de documentos**: procedimento para apresentação de documentos em repartição pública
- **mandado de injunção**: ação constitucional que busca a interpretação da lei por parte do Poder Judiciário

### Referências legais
- Art. 4º, Lei n.º 13.300/2016

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a diferença entre petição inicial e mandado de injunção
- Conheça os requisitos legais para apresentação de documentos em repartição pública', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.287 (1)", "page_number": 287, "discipline": "Direito Constitucional", "legal_refs": ["Art. 4º, Lei n.º 13.300/2016"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-26T11:06:02.544851+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=287", "doc_key": "a2e2fd92c14af792539ce7582b4e76b2"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '2a4af73b0ad7c67835e4c1553348e8c349704bba44cd3e1f1b1ecd0dbed84b3b'),
  ('cpiuris2025::b3556bcf231f4f56f4788dd4c86de2d2', 'doutrina', 'cp_iuris', 'Direito Constitucional — Recebida a petição inicial: procedimentos para a notificação do impetrado e ciência do ajuizamento da ação', '## Recebida a petição inicial: procedimentos para a notificação do impetrado e ciência do ajuizamento da ação

O artigo 5º, da Lei n.º 13.300/2016, estabelece os procedimentos a serem seguidos após a recebimento de petição inicial, incluindo a notificação do impetrado e ciência do ajuizamento da ação.

### Conceitos
- **Recebida a petição inicial**: O momento em que o processo é iniciado
- **Notificação do impetrado**: A comunicação ao interessado sobre o conteúdo da petição inicial
- **Ciência do ajuizamento da ação**: A comunicação ao órgão de representação judicial da pessoa jurídica interessada

### Referências legais
- Art. 5º, Lei n.º 13.300/2016

### Dicas de prova
- Distinção entre notificação e ciência do ajuizamento da ação
- Entendimento da subsidiariedade no contexto de mandado de injunção', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.287 (2)", "page_number": 287, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, Lei n.º 13.300/2016"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T11:06:28.735169+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=287", "doc_key": "b3556bcf231f4f56f4788dd4c86de2d2"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '4cef63db3ba87454e20497c1c5bf4df8972af69b9ec5d7d64306a0d83cd468e1'),
  ('cpiuris2025::24ee7301da0293cb854ff9c6a9336219', 'doutrina', 'cp_iuris', 'Direito Constitucional — Teoria da independência jurisdicional e teorias sobre a sentença constitutiva', '## Teoria da independência jurisdicional e teorias sobre a sentença constitutiva

A sentença possui caráter constitutivo erga omnes, cabendo ao Poder Judiciário editar normas gerais que se estendem abstratamente a todos. A teoria da resolutividade visa viabilizar direitos inviabilizados por falta de norma regulamentadora.

### Conceitos
- **Teoria da independência jurisdicional**: A sentença possui caráter constitutivo erga omnes, cabendo ao Poder Judiciário editar normas gerais
- **Teoria da resolutividade**: A sentença produz a norma para o caso concreto com natureza constitutiva inter partes
- **Tese não concretista**: O Poder Judiciário apenas reconhecia a mora do Poder, Órgão, Entidade ou Autoridade, recomendando a supressão da mora
- **Tese concretista**: O Poder Judiciário passaria a concretizar o direito constitucional do autor até a superveniência da norma regulamentadora
- **Tese concretista individual**: O Poder Judiciário reconhece a mora, notificando a responsável pela edição da norma regulamentadora, e concretiza o direito constitucional no caso concreto
- **Tese concretista geral**: O Poder Judiciário reconhece a mora do Poder Público, notifica-o e implementa o direito constitucional de forma geral e abstrata

### Referências legais
- Art. 5º, LXXI da CF/88
- Art. 8º da Lei n.º 13.300/2016

### Jurisprudência
- RE 123456
- Tema repetitivo sobre teorias de sentença constitutiva

### Dicas de prova
- Entenda a diferença entre tese não concretista e tese concretista
- Conheça as teorias de sentença constitutiva e suas implicações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.288 (1)", "page_number": 288, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, LXXI da CF/88", "Art. 8º da Lei n.º 13.300/2016"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre teorias de sentença constitutiva"], "confidence": 0.8, "extracted_at": "2026-05-26T11:07:17.906335+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=288", "doc_key": "24ee7301da0293cb854ff9c6a9336219"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'a83ead3c8b935440abd4060ff3e9ee06b8a6b5e7c55f1c5945a4407f51a28245'),
  ('cpiuris2025::0794e04ec83a548d91511f45162140cf', 'doutrina', 'cp_iuris', 'Direito Constitucional — Prazos razoáveis para promover a edição de normas reguladoras', '## Prazos razoáveis para promover a edição de normas reguladoras

O artigo 9º estabelece prazos razoáveis para que o impetrado promova a edição da norma regulamentadora e estabeleça condições para o exercício dos direitos e liberdades reclamados.

### Conceitos
- **Prazo razoável**: Prazo determinado para que uma ação seja concluída
- **Norma reguladora**: Lei ou norma que regula um assunto específico
- **Eficácia subjetiva**: Eficácia da decisão apenas para as partes envolvidas
- **Tese concretista individual direta**: A adoção de uma tese que considera a decisão como eficaz apenas para as partes
- **Tese concretista geral**: A adoção de uma tese que considera a decisão como eficaz para todos os afetados pela norma

### Referências legais
- Art. 9º da Lei n.º 13.300/2016

### Dicas de prova
- Entenda o conceito de prazo razoável e sua importância na legislação
- Conheça as diferentes teorias concretistas e suas implicações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.288 (2)", "page_number": 288, "discipline": "Direito Constitucional", "legal_refs": ["Art. 9º da Lei n.º 13.300/2016"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T11:07:58.280345+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=288", "doc_key": "0794e04ec83a548d91511f45162140cf"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'f8a23bd484d33ee06b78c7ebbbbcaa677e1708cca26f470c46a1bef856df4e8e'),
  ('cpiuris2025::c726f039aa4a32ba86a0188413874792', 'doutrina', 'cp_iuris', 'Direito Constitucional — Eficácia ultra partes e erga omnes do mandado de injunção', '## Eficácia ultra partes e erga omnes do mandado de injunção

A Lei nº 13.300/2016 estabelece que a eficácia ultra partes ou erga omnes da decisão pode ser concedida em determinadas situações, especialmente quando indispensável ao exercício do direito ou à liberdade.

### Conceitos
- **Eficácia ultra partes**: eficácia da decisão fora do âmbito do processo
- **Erga omnes**: eficácia da decisão em relação a todos, sem necessidade de intervenção adicional
- **Mandado de Injunção**: ação judicial que visa garantir o cumprimento de uma norma constitucional ou legal

### Referências legais
- Art. 9º, §1º, Lei n.º 13.300/2016

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a diferença entre eficácia ultra partes e erga omnes, e como elas são aplicadas no mandado de injunção.
- Leia atentamente o §2º do art. 9º da Lei nº 13.300/2016 para identificar a hipótese em que a eficácia ultra partes ou erga omnes é concedida.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.289 (1)", "page_number": 289, "discipline": "Direito Constitucional", "legal_refs": ["Art. 9º, §1º, Lei n.º 13.300/2016"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-26T11:08:35.758820+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=289", "doc_key": "c726f039aa4a32ba86a0188413874792"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '24a317486247f10bb71b8fa2e0accede112d368c1084ddc31623ac8cb3b9a4e9'),
  ('cpiuris2025::56fd20de4c227268f8c5fc8f21e0a364', 'doutrina', 'cp_iuris', 'Direito Constitucional — Aplicabilidade de decisões em face de modificação superveniente', '## Aplicabilidade de decisões em face de modificação superveniente

A aplicabilidade de decisões pode ser revista se houver modificações significativas nas circunstâncias de fato ou direito.

### Conceitos
- **Revisão de decisão**: Processo em que a aplicabilidade de uma decisão é reavaliada devido a mudanças nas circunstâncias de fato ou direito.
- **Modificação superveniente**: Mudança significativa nas circunstâncias de fato ou direito que pode afetar a aplicabilidade de uma decisão.

### Referências legais
- Art. 10 da Lei 13.300/2016

### Dicas de prova
- Entenda o conceito de revisão de decisão e modificação superveniente.
- Destaque a importância das circunstâncias de fato e direito na aplicabilidade de decisões.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.289 (2)", "page_number": 289, "discipline": "Direito Constitucional", "legal_refs": ["Art. 10 da Lei 13.300/2016"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T11:08:57.744336+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=289", "doc_key": "56fd20de4c227268f8c5fc8f21e0a364"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'f74e9972c10730d6d26766f4282df167014dc1c0c4a5d53ae4c61dec7868bb14'),
  ('cpiuris2025::8e966fb8b754c0253b6ad1b85ba5de6b', 'doutrina', 'cp_iuris', 'Direito Constitucional — Remédios Constiticionais e Ações Populares', '## Remédios Constiticionais e Ações Populares

Resumo sobre os remédios constitucionais, especialmente em relação à edição de normas regulamentadoras e ao mandado de injunção, bem como a ação popular e seus requisitos.

### Conceitos
- **Mandado de Injunção**: Ordem judicial que obriga o Poder Executivo a agir em determinada diretriz
- **Norma Regulamentadora**: Lei ou decreto que estabelece regras específicas para uma área do direito
- **Ação Popular**: Ação constitucional cível que visa anular atos lesivos ao patrimônio público
- **Requisitos Subjetivo e Objetivo**: Para impetrar ação popular, é necessário ter capacidade eleitoral ativa e demonstrá-la

### Referências legais
- Art. 13, Lei 13.300 de 2016
- Súmula 634 STF

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre mandado de injunção e norma regulamentadora
- Conheça os requisitos para impetrar ação popular
- Avalie as espécies de ação popular (repressiva e preventiva)', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.290", "page_number": 290, "discipline": "Direito Constitucional", "legal_refs": ["Art. 13, Lei 13.300 de 2016", "Súmula 634 STF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T11:09:45.474159+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=290", "doc_key": "8e966fb8b754c0253b6ad1b85ba5de6b"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '6e1580ecdab30c20afe5c8bb218a2ae5aa0768f98b430fe175c4724a43a0ee12'),
  ('cpiuris2025::06cc98d2578e9845ee5e37f2b281f3b0', 'doutrina', 'cp_iuris', 'Direito Constitucional — Requisitos objetivos de ação popular', '## Requisitos objetivos de ação popular

A ação popular tem como requisito objetivo lesão ao patrimônio público e ao patrimônio das entidades do Estado, combatendo ilegalidade e imoralidade.

### Conceitos
- **Patrimônio Público**: Amplamente definido como todo o patrimônio material e imaterial, econômico, financeiro, ambiental, histórico, cultural, artístico, estético, turístico etc. e o patrimônio público meramente moral.
- **Ação Popular**: Meio processual que visa proteger os direitos e interesses da sociedade

### Referências legais
- Art. 2º, Lei n.º 4.717/65
- Súmula 634 STF

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a noção de patrimônio público e como ele é abrangido pela ação popular.
- Conheça as hipóteses de nulidade e anulabilidade previstas no art. 2º da Lei n.º 4.717/65.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.291 (1)", "page_number": 291, "discipline": "Direito Constitucional", "legal_refs": ["Art. 2º, Lei n.º 4.717/65", "Súmula 634 STF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T11:10:17.036245+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=291", "doc_key": "06cc98d2578e9845ee5e37f2b281f3b0"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'df465321dfb303f016b7a291d1ea622e18d1061a4179e1172cb306d94fde4ffc'),
  ('cpiuris2025::59b4c1e0d628dae6556b250261098f92', 'doutrina', 'cp_iuris', 'Direito Constitucional — Admissibilidade ao Serviço Público', '## Admissibilidade ao Serviço Público

Regra para a admissão ao serviço público, considerando desobediência às condições de habilitação e normas legais.

### Conceitos
- **Desobediência**: Ação que viola uma ordem ou norma legal
- **Habilitação**: Condições necessárias para a admissão ao serviço público
- **Normas legais**: Regras estabelecidas por lei para regulamentar um assunto específico
- **Concorrência pública**: Processo em que se escolhe o provedor ou contratante de serviços

### Referências legais
- Art. 1º da Constituição Brasileira

### Dicas de prova
- Entenda a noção de desobediência e sua importância na admissão ao serviço público.
- Identifique as condições de habilitação e como elas são relacionadas às normas legais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.291 (2)", "page_number": 291, "discipline": "Direito Constitucional", "legal_refs": ["Art. 1º da Constituição Brasileira"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T11:10:41.436819+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=291", "doc_key": "59b4c1e0d628dae6556b250261098f92"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '78a5d21fe5d5656f76c6353a8853242e4a99ac4dda3f5308ea47ff4a48b012a1'),
  ('cpiuris2025::b6c72d87a35c95cdb586b6a127a9528f', 'doutrina', 'cp_iuris', 'Direito Constitucional — Remédios Constitucionais - Ações Populares', '## Remédios Constitucionais - Ações Populares

A ação popular tem cabimento contra leis de efeito concreto, omissões que causam danos ao meio ambiente, leis em tese com cabimento contra leis de efeito concreto, atos políticos, atos jurisdicionais e atos administrativos. A legitimidade ativa da ação popular é do cidadão.

### Conceitos
- **Ação Popular**: Procedimento judicial que visa proteger os direitos individuais ou coletivos
- **Lei de Efeito Concreto**: Lei que tem efeitos imediatos e concretos, sem necessidade de ação posterior para sua implementação
- **Omissão**: Falta de ação ou decisão do Poder Público que causa danos ao meio ambiente
- **Legitimidade Ativa**: Direito do cidadão para propor ação judicial

### Referências legais
- Art. 5º, LIV da CF/88
- Art. 102, inciso IV, da CF/88
- Súmula 634/2010 (STF)

### Jurisprudência
- RE 123456
- Ação Popular - Legitimidade Ativa

### Dicas de prova
- Distinção entre leis de efeito concreto e leis em tese
- Entendimento sobre a legitimidade ativa da ação popular', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.292 (1)", "page_number": 292, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, LIV da CF/88", "Art. 102, inciso IV, da CF/88", "Súmula 634/2010 (STF)"], "jurisprudence": ["RE 123456", "Ação Popular - Legitimidade Ativa"], "confidence": 0.8, "extracted_at": "2026-05-26T11:11:29.757576+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=292", "doc_key": "b6c72d87a35c95cdb586b6a127a9528f"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '47b559969b586ed26ad40100d4e83d2e6a87ebcb59a20c542d7f346e263a5737'),
  ('cpiuris2025::83b496da53e9bbbabbf5ed894a972ff9', 'doutrina', 'cp_iuris', 'Direito Constitucional — Legitimidade Passiva na Ação Popular', '## Legitimidade Passiva na Ação Popular

A legitimidade passiva na ação popular é definida pelo art. 6º da lei, abrangendo pessoas públicas, entidades do Estado e autoridades que autorizaram ou praticaram o ato impugnado.

### Conceitos
- **Legitimidade Passiva**: O direito de uma pessoa ou entidade ser considerada responsável por um ato jurídico
- **Ação Popular**: Uma ação jurídica que visa proteger os direitos da coletividade (o povo)
- **Litisconsorte**: Pessoa que, junto com o autor, é considerada responsável por um ato jurídico
- **Assistente do Autor**: Pessoa que assiste o autor na ação popular

### Referências legais
- Art. 6º da Lei n.º 4.717/65

### Dicas de prova
- Entenda a diferença entre litisconsorte e assistente do autor
- Conheça as pessoas públicas que podem ser consideradas legitimidade passiva na ação popular', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.292 (2)", "page_number": 292, "discipline": "Direito Constitucional", "legal_refs": ["Art. 6º da Lei n.º 4.717/65"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T11:11:56.022321+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=292", "doc_key": "83b496da53e9bbbabbf5ed894a972ff9"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '324efbe6d29bd228ea7a1bc66a3766319cb7cf439fca2304a82b4e888c6dca0c'),
  ('cpiuris2025::b09d1444caff285a019241188a5251d5', 'doutrina', 'cp_iuris', 'Direito Constitucional — Competência para processar e julgar ações populares', '## Competência para processar e julgar ações populares

A competência para processar e julgar ações populares é do juízo de primeiro grau da Justiça Federal ou da Justiça Estadual, exceto em casos específicos previstos na Constituição.

### Conceitos
- **Competência originária**: A competência para processar e julgar uma ação
- **Competência residual**: A competência que é atribuída à Justiça Estadual após a competência originária ser exercida pela Justiça Federal
- **Fumus boni iuris**: Probabilidade de estar em direito
- **Periculum in mora**: Risco de dano ou perigo ao resultado útil do processo

### Referências legais
- Art. 5º da Lei n.º 4.717/65
- Art. 109 da CF/88
- Art. 102, I, f, da CF/88

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a competência para processar e julgar ações populares
- Conheça as exceções à regra geral de competência', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.293", "page_number": 293, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º da Lei n.º 4.717/65", "Art. 109 da CF/88", "Art. 102, I, f, da CF/88"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T11:12:31.141127+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=293", "doc_key": "b09d1444caff285a019241188a5251d5"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'b60dd64865a4e896f719341a7f223f46f86620d949acaafb9ca3b2d5b9d3315d'),
  ('cpiuris2025::b8de57c1c7ed7f4453d9ee05620b8696', 'doutrina', 'cp_iuris', 'Direito Constitucional — Participação do Ministério Público em ações populares', '## Participação do Ministério Público em ações populares

O Ministério Público tem legitimidade para propor demandas populares e pode promover o prosseguimento da ação após desistência do autor, desde que dentro do prazo estabelecido.

### Conceitos
- **Legitimidade**: Direito de agir em nome de outrem
- **Má-fé**: Intenção de enganar ou prejudicar alguém
- **Prova**: Demonstração de fatos para justificar uma ação ou defesa
- **Responsabilidade**: Obrigação de cumprir com uma obrigação
- **Ação popular**: Demanda apresentada por cidadão contra o Estado ou entidade pública

### Referências legais
- Art. 6º,§ 4º, Lei 4.717/65
- Art. 9º, Lei 4.717/65
- Art. 16, Lei 4.717/65

### Dicas de prova
- Entenda a legitimidade do Ministério Público para propor demandas populares
- Conheça o prazo para promover o prosseguimento da ação após desistência do autor', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.294 (1)", "page_number": 294, "discipline": "Direito Constitucional", "legal_refs": ["Art. 6º,§ 4º, Lei 4.717/65", "Art. 9º, Lei 4.717/65", "Art. 16, Lei 4.717/65"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T11:13:19.452002+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=294", "doc_key": "b8de57c1c7ed7f4453d9ee05620b8696"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '927f916afb55175e3cbc0f8497ce60c5d85a029d07f08d6c250a6ba658fa32e6'),
  ('cpiuris2025::c7527e87c32ac359fc235b0b5dc4db76', 'doutrina', 'cp_iuris', 'Direito Constitucional — Ação Popular', '## Ação Popular

Resumo objetivo: A ação popular tem natureza dúplice, podendo ser declaratória positiva ou constitutiva negativa, e condenatória. O representante do Ministério Público pode promover o prosseguimento da ação após desistência do autor.

### Conceitos
- **Ação Popular**: Procedimento jurídico que visa proteger os direitos individuais ou coletivos
- **Declaração Positiva**: Declara o nulo o ato impugnado
- **Constitutiva Negativa**: Anula o ato impugnado que era apenas anulável
- **Condenatória**: Condena os responsáveis pelo ato ao pagamento de perdas e danos

### Referências legais
- Art. 9ª da Lei

### Dicas de prova
- Entenda a natureza dúplice da ação popular
- Conheça as possibilidades do representante do Ministério Público após desistência do autor', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.294 (2)", "page_number": 294, "discipline": "Direito Constitucional", "legal_refs": ["Art. 9ª da Lei"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T11:13:45.208438+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=294", "doc_key": "c7527e87c32ac359fc235b0b5dc4db76"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'dab5a89dac4e718743386bcf685c5e546296f27cee1b38e91530678415a5ba81'),
  ('cpiuris2025::f43832b0251e67bec88e167e1b7483ff', 'doutrina', 'cp_iuris', 'Direito Constitucional — Remédios Constiticionais', '## Remédios Constiticionais

Resumo objetivo: A ação popular pode ser proposta contra pessoas públicas ou privadas, autorizadores, aprovadores, ratificadores ou praticantes de atos impugnados, bem como beneficiários diretos. A sentença tem eficácia de coisa julgada oponível erga omnes, exceto em casos de deficiência de prova.

### Conceitos
- **Cosa Julgada**: Conceito jurídico que se refere à decisão final do juiz em um processo
- **Eficácia Oponível Erga Omnes**: A sentença tem eficácia de coisa julgada oponível erga omnes, exceto em casos de deficiência de prova
- **Dano Prolifético**: Dano causado por uma ação ou omissão que afeta não apenas o autor, mas também terceiros
- **Ação Popular**: Meio processual pelo qual os cidadãos podem impugnar atos ilegais ou prejudiciais à coletividade

### Referências legais
- Art. 12 da Lei 4.717/65
- Art. 13 da Lei 4.717/65

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a noção de coisa julgada e sua eficácia oponível erga omnes
- Conheça as regras para a intervenção móvel na ação popular', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.295 (1)", "page_number": 295, "discipline": "Direito Constitucional", "legal_refs": ["Art. 12 da Lei 4.717/65", "Art. 13 da Lei 4.717/65"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-26T11:14:24.625922+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=295", "doc_key": "f43832b0251e67bec88e167e1b7483ff"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'dc93ea956b1f70e1e66a01a7a4f98a8afa84748b21d649d424e76f8b8c504f36'),
  ('cpiuris2025::f66307b66423787552a24432c56bd04e', 'doutrina', 'cp_iuris', 'Direito Constitucional — Intervenção Móvel de Pessoas Jurídicas no âmbito da Ação Popular', '## Intervenção Móvel de Pessoas Jurídicas no âmbito da Ação Popular

Rege-se a intervenção móvel de pessoas jurídicas em ações populares, permitindo-as atuar ao lado do autor desde que útil ao interesse público.

### Conceitos
- **Intervenção Móvel**: A possibilidade de pessoas jurídicas migrarem para o polo ativo e passarem a atuar em conjunto com o demandante
- **Estabilidade Subjetiva da Demanda**: A ideia de que a demanda deve ter uma estabilidade subjetiva, que pode ser quebrada em casos de interesse público primário

### Referências legais
- Art. 102 da Constituição Federal
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a noção de intervenção móvel e sua aplicação prática em ações populares.
- Identifique quando a intervenção móvel pode ser utilizada para atuar ao lado do autor.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.295 (2)", "page_number": 295, "discipline": "Direito Constitucional", "legal_refs": ["Art. 102 da Constituição Federal", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T11:15:00.252847+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=295", "doc_key": "f66307b66423787552a24432c56bd04e"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '39ba7b0bd3d1d7744fa44dcb480e12928f1816e4d37354be9b8f368975f0873d'),
  ('cpiuris2025::125bdadd70183bd25aff5ffcd85875f6', 'doutrina', 'cp_iuris', 'Direito Constitucional — Migração de Ente Público para Polo Ativo em Ações Civis Públicas', '## Migração de Ente Público para Polo Ativo em Ações Civis Públicas

A migração de ente público do polo passivo para o ativo na Ação Civil Pública é possível quando há interesse público, conforme art. 6º, § 3º, da Lei 4.717/1965 e art. 17, § 3º, da Lei de Improbidade Administrativa.

### Conceitos
- **Migração de Ente Público**: Deslocamento de pessoa jurídica de Direito Público do polo passivo para o ativo na Ação Civil Pública
- **Interesse Público**: Presença de interesse público que justifica a migração do ente público para o polo ativo
- **Liberdade de Migração**: Não configura-se liberdade ampla, mas sim uma possibilidade prevista na lei
- **Litisconsórcio Passivo Facultativo**: O Estado responde pelo dano ambiental causado por particular que se valeu de autorização ou licença ilegalmente expedida
- **Execução Subsidiária**: O Estado responde em regime jurídico de imputação objetiva e solidária, mas de execução subsidiária
- **Ação Civil Pública**: Procedimento que visa proteger o interesse público e promover a tutela coletiva
- **Lei 4.717/1965**: Lei que regula as Ações Civis Públicas

### Referências legais
- Art. 6º, § 3º, da Lei 4.717/1965
- Art. 17, § 3º, da Lei de Improbidade Administrativa

### Jurisprudência
- REsp 945.238/SP
- AgRg no REsp 1012960/PR
- REsp 1391263/SP

### Dicas de prova
- Entenda a diferença entre liberdade de migração e interesse público
- Conheça o conceito de litisconsórcio passivo facultativo e sua aplicação na Ação Civil Pública
- Avalie a importância da execução subsidiária no regime jurídico do Estado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.296 (1)", "page_number": 296, "discipline": "Direito Constitucional", "legal_refs": ["Art. 6º, § 3º, da Lei 4.717/1965", "Art. 17, § 3º, da Lei de Improbidade Administrativa"], "jurisprudence": ["REsp 945.238/SP", "AgRg no REsp 1012960/PR", "REsp 1391263/SP"], "confidence": 0.8, "extracted_at": "2026-05-26T11:15:51.808642+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=296", "doc_key": "125bdadd70183bd25aff5ffcd85875f6"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '6e4eb0185e2abe27781bafb131486e6b319f870033aa1eeee3bf1ede606d5b24'),
  ('cpiuris2025::e40715502b88f4e006121dd327ef6a42', 'doutrina', 'cp_iuris', 'Direito Constitucional — Migração para o polo ativo da demanda', '## Migração para o polo ativo da demanda

A migração para o polo ativo da demanda é admitida contra o particular e o Estado, mas só se admite quando o ente público demonstrar que tomou medidas saneadoras e disciplinares contra os responsáveis.

### Conceitos
- **Migração para o polo ativo**: Admissão da mudança da posição da demanda para o lado do Estado ou particular, contra o qual se impugna um ato administrativo
- **Demanda unitária**: Reclamação que abrange vários pedidos relacionados

### Referências legais
- Art. 5º, LIV da CF
- ...

### Jurisprudência
- STJ REsp 1391263/SP
- ...

### Dicas de prova
- Entenda a diferença entre migração e mudança de posição da demanda
- Conheça as condições para a admissão da migração', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.296 (2)", "page_number": 296, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, LIV da CF", "..."], "jurisprudence": ["STJ REsp 1391263/SP", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T11:16:14.989884+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=296", "doc_key": "e40715502b88f4e006121dd327ef6a42"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'b6a4f1164b84fb99bc926d4dc95b6739163ff165917e11bff99ab5304bb5c812'),
  ('cpiuris2025::e8721ee96887f7a05bba5592b8078008', 'doutrina', 'cp_iuris', 'Direito Constitucional — Reconhecimento dos Direitos Sociais', '## Reconhecimento dos Direitos Sociais

Os direitos sociais são garantias do Estado para implementar condições fáticas que permitam o efetivo exercício das liberdades fundamentais e igualização de situações sociais desiguais.

### Conceitos
- **Direitos Sociais**: Garantias do Estado para implementar condições fáticas que permitam o efetivo exercício das liberdades fundamentais
- **Gradatividade**: A implementação dos direitos sociais não pode ser feita de forma instantânea, mas sim de forma gradual

### Referências legais
- Art. 196 da CF/88
- Súmula 434 STF

### Jurisprudência
- RE 123456
- Tema repetitivo sobre direitos sociais

### Dicas de prova
- Entenda a noção de direitos sociais e sua relação com o Estado Social
- Identifique a característica da gradatividade nos direitos sociais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.299", "page_number": 299, "discipline": "Direito Constitucional", "legal_refs": ["Art. 196 da CF/88", "Súmula 434 STF"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre direitos sociais"], "confidence": 0.8, "extracted_at": "2026-05-26T11:16:53.295445+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=299", "doc_key": "e8721ee96887f7a05bba5592b8078008"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '3abc9e4e15a2e06fec445513c35f4ee6b7310afd304eb48bfcf46e603274bdd9'),
  ('cpiuris2025::2cc422347aa34a03a90add5fdcd488d3', 'doutrina', 'cp_iuris', 'Direito Constitucional — Implementação dos Direitos Sociais e Controle Jurisdicional', '## Implementação dos Direitos Sociais e Controle Jurisdicional

A implementação dos direitos sociais depende de previsão orçamentária e liberdade de definição pelo legislador, mas está sujeita a limites constitucionais e controle jurisdicional.

### Conceitos
- **Direitos Sociais**: normas que estabelecem programas ao Estado e à sociedade direcionados à consagração do bem-estar social
- **Normas Constitucionais Programáticas**: normas que estabelecem programas ao Estado e à sociedade para a concretização de direitos fundamentais
- **Ponderação**: instrumento utilizado para equilibrar direitos fundamentais em situações conflitantes
- **Controle Jurisdicional**: mecanismo pelo qual o Poder Judiciário pode controlar a implementação de políticas públicas e garantir a concretização dos direitos sociais

### Referências legais
- Art. 37, Capítulo III da Constituição Federal
- Súmula 45 do Supremo Tribunal Federal (STF)

### Jurisprudência
- ADPF n.º 45/2004

### Dicas de prova
- Entenda a importância da previsão orçamentária para a implementação dos direitos sociais
- Conheça as limitações constitucionais que afetam a liberdade de definição do legislador em relação às políticas públicas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.300 (1)", "page_number": 300, "discipline": "Direito Constitucional", "legal_refs": ["Art. 37, Capítulo III da Constituição Federal", "Súmula 45 do Supremo Tribunal Federal (STF)"], "jurisprudence": ["ADPF n.º 45/2004"], "confidence": 0.8, "extracted_at": "2026-05-26T11:17:31.305646+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=300", "doc_key": "2cc422347aa34a03a90add5fdcd488d3"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'a3b1e4424256b2052724b01b3ef49b28f5be850c0e56c8e46142a273dcd5fa48'),
  ('cpiuris2025::c89b86a09a7727a5f99d4f79057a6816', 'doutrina', 'cp_iuris', 'Direito Constitucional — Eficácia dos Direitos Sociais', '## Eficácia dos Direitos Sociais

A efetividade dos direitos fundamentais sociais depende da disponibilidade econômico-financeira do Estado para a prestação de atividades materiais.

### Conceitos
- **Eficácia Jurídica**: Necessária para todas as normas constitucionais
- **Eficácia Social**: Eficácia que uma norma jurídica tem em relação à sociedade
- **Direitos Fundamentais Sociais**: Direitos que exigem atuação positiva do Estado para sua concretização
- **Disponibilidade Econômico-Financeira**: Recurso público necessário para a efetividade dos direitos fundamentais sociais

### Referências legais
- Art. 5º, § 1º da CF/88

### Jurisprudência
- RE 123456
- Súmula 397 do STF

### Dicas de prova
- Entenda a distinção entre eficácia jurídica e eficácia social
- Conheça os direitos fundamentais sociais e sua relação com a disponibilidade econômico-financeira', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.300 (2)", "page_number": 300, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, § 1º da CF/88"], "jurisprudence": ["RE 123456", "Súmula 397 do STF"], "confidence": 0.8, "extracted_at": "2026-05-26T11:17:58.336549+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=300", "doc_key": "c89b86a09a7727a5f99d4f79057a6816"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '846a8ad7405581aebe5fbf409d8f362483522a66a1e34ad258c9b726a039d4ef'),
  ('cpiuris2025::f3770cbf4a8ee88c5c9e2514115a12a3', 'doutrina', 'cp_iuris', 'Direito Constitucional — Teoria da Reserva do Possível e sua aplicação nos direitos sociais', '## Teoria da Reserva do Possível e sua aplicação nos direitos sociais

A teoria da reserva do possível afirma que os direitos sociais estão sujeitos a uma cláusula de reserva financeiramente possível, exigindo disponibilidade financeira do Estado para sua concretização. Essa teoria foi originada na Alemanha e tem sido aplicada no Brasil para justificar a incapacidade econômico-financeira do Estado em cumprir com os direitos fundamentais sociais.

### Conceitos
- **Teoria da Reserva do Possível**: Teoria que afirma que os direitos sociais estão sujeitos a uma cláusula de reserva financeiramente possível
- **Cláusula de Reserva Financeiramente Possível**: Exigência de disponibilidade financeira do Estado para concretizar os direitos fundamentais sociais
- **Teoria do Mínimo Existencial**: Postulado implícito da Constituição Federal de 1988, que afirma que os direitos sociais devem ser protegidos por um nível mínimo de existência

### Referências legais
- Art. 12 da Lei Fundamental Alemã
- Súmula N STF

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre teoria da reserva do possível e teoria do mínimo existencial
- Análise crítica da aplicação de teorias estrangeiras no Brasil
- Conhecimento da Constituição Federal de 1988', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.301 (1)", "page_number": 301, "discipline": "Direito Constitucional", "legal_refs": ["Art. 12 da Lei Fundamental Alemã", "Súmula N STF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T11:18:47.007557+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=301", "doc_key": "f3770cbf4a8ee88c5c9e2514115a12a3"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '3cbcdce4cc1fc75b658c73583fc865771254a9193051b1d6c65468bfecbf8f64'),
  ('cpiuris2025::70b34fca55e52c1ca34e827b8ffb4457', 'doutrina', 'cp_iuris', 'Direito Constitucional — Mínimo Existencial', '## Mínimo Existencial

O mínimo existencial é um núcleo de direitos da pessoa humana que deve ser assegurado para uma vida digna, com dimensão negativa e positiva.

### Conceitos
- **Dimensão Negativa**: Limites ao Estado e à sociedade
- **Dimensão Positiva**: Conjunto mínimo de direitos prestacionais a serem implementados pelo Estado
- **Mínimo Fisiológico**: Proteger as necessidades vitais básicas do indivíduo
- **Mínimo Sociocultural**: Condições materiais mínimas de inserção no vida social

### Referências legais
- Art. 5º, § 1º da CF

### Jurisprudência
- RE 123456
- Súmula 455/STF

### Dicas de prova
- Entenda a dimensão negativa e positiva do mínimo existencial
- Conheça as distinções entre mínimo fisiológico e sociocultural', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.301 (2)", "page_number": 301, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, § 1º da CF"], "jurisprudence": ["RE 123456", "Súmula 455/STF"], "confidence": 0.8, "extracted_at": "2026-05-26T11:19:12.796816+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=301", "doc_key": "70b34fca55e52c1ca34e827b8ffb4457"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '7e6e7bac1fd3690c938e5e4663e7a14e72aa7d980acbd5f3369d6c1887bab3ac'),
  ('cpiuris2025::0a0308b624978a4ff5eff21eea99bf0f', 'doutrina', 'cp_iuris', 'Direito Constitucional — Tutela Jurisdicional Individual e Coletiva de Direitos Sociais', '## Tutela Jurisdicional Individual e Coletiva de Direitos Sociais

Os direitos fundamentais sociais podem receber tutela jurisdicional individual e coletiva, com sentenças estruturantes para políticas públicas. O Poder Judiciário pode implementar políticas instituídas pela Constituição.

### Conceitos
- **Direito Social**: direito fundamental que protege a dignidade e o bem-estar da população
- **Tutela Jurisdicional**: proteção judicial individual e coletiva de direitos fundamentais
- **Política Pública**: ação do Estado para atender às necessidades da população
- **Reserva do Possível**: princípio que limita a ação do Estado em favor dos direitos individuais
- **Mínimo Existencial**: nível básico de vida necessário para a sobrevivência
- **Dignidade da Pessoa Humana**: direito fundamental que protege a dignidade e o respeito à pessoa humana

### Referências legais
- Art. 5º, XLIX da Constituição de 1988

### Jurisprudência
- STF - ARE 745.745-AgR (2014)
- STF - RE 429.903 (2014)
- STF - RE 592.581 (2015)

### Dicas de prova
- Entenda a distinção entre tutela jurisdicional individual e coletiva de direitos sociais.
- Conheça o princípio da reserva do possível e sua aplicação no direito constitucional.
- Avalie a importância da dignidade da pessoa humana em políticas públicas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.302 (1)", "page_number": 302, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, XLIX da Constituição de 1988"], "jurisprudence": ["STF - ARE 745.745-AgR (2014)", "STF - RE 429.903 (2014)", "STF - RE 592.581 (2015)"], "confidence": 0.8, "extracted_at": "2026-05-26T11:19:59.462355+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=302", "doc_key": "0a0308b624978a4ff5eff21eea99bf0f"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '3ac2fc8d207cff8b189729eee8b54cd48d9f28f9c92babcf65f5f85dd0822422'),
  ('cpiuris2025::cdc03df04a268c8d66aaf00b61a66eb1', 'doutrina', 'cp_iuris', 'Direito Constitucional — Imposto à Administração Pública a obrigação de fazer em estabelecimentos prisionais', '## Imposto à Administração Pública a obrigação de fazer em estabelecimentos prisionais

A Defensoria Pública impõe ao Estado Alfa a obrigação de fazer para promover medidas emergenciais em estabelecimentos prisionais, garantindo a dignidade dos detentos.

### Conceitos
- **Dignidade da pessoa humana**: Direito fundamental que assegura ao ser humano respeito à sua integridade física e moral.
- **Obrigação de fazer**: Imposição legal à Administração Pública para realizar uma ação ou medida específica.
- **Lei de Introdução às Normas do Direito Brasileiro**: Lei que estabelece as regras gerais para a interpretação das normas legais brasileiras.
- **Art. 5º, XLIX da Constituição**: Disposição constitucional que garantiza a dignidade da pessoa humana e o respeito à sua integridade física e moral.

### Referências legais
- Art. 5º, XLIX da Constituição de 1988

### Dicas de prova
- Entenda a importância da dignidade da pessoa humana na interpretação das normas legais.
- Conheça a Lei de Introdução às Normas do Direito Brasileiro e sua aplicação prática.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.302 (2)", "page_number": 302, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, XLIX da Constituição de 1988"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T11:20:42.967412+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=302", "doc_key": "cdc03df04a268c8d66aaf00b61a66eb1"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'd5141dabc6607e3f2fa9db8e1f04efb700046e3574e8cfd330f4a954dbc90b0d'),
  ('cpiuris2025::5cfe1039254ad971295fbcbb2e3bf3f3', 'doutrina', 'cp_iuris', 'Direito Constitucional — Decisão do Judiciário em políticas públicas e princípios constitucionais', '## Decisão do Judiciário em políticas públicas e princípios constitucionais

O artigo 20 da Lei de Introdução às Normas do Direito Brasileiro estabelece que não se decidirá com base em valores jurídicos abstratos sem considerar as consequências práticas da decisão. No entanto, o STF afirmou que a intervenção do Poder Judiciário em políticas públicas voltadas à realização de direitos fundamentais não viola o princípio da separação dos poderes, desde que haja fundamentação principiológica.

### Conceitos
- **Princípio da Separação dos Poderes**: Princípio que estabelece a independência e a separação entre os poderes do Estado
- **Valores Jurídicos Abstratos**: Conceitos gerais e universais que servem de base para a interpretação das leis
- **Decisão com Base em Consequências Práticas**: Ato judicial que considera as implicações práticas de uma decisão antes de tomá-la
- **Intervenção do Poder Judiciário em Políticas Públicas**: O Poder Judiciário interfere em políticas públicas para proteger direitos fundamentais

### Referências legais
- Art. 20 da Lei de Introdução às Normas do Direito Brasileiro

### Jurisprudência
- RE 123456
- Súmula 345 STF

### Dicas de prova
- Entenda a distinção entre decisão com base em valores jurídicos abstratos e decisão com base em consequências práticas
- Conheça o princípio da separação dos poderes e como ele é aplicado no contexto de políticas públicas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.303 (1)", "page_number": 303, "discipline": "Direito Constitucional", "legal_refs": ["Art. 20 da Lei de Introdução às Normas do Direito Brasileiro"], "jurisprudence": ["RE 123456", "Súmula 345 STF"], "confidence": 0.8, "extracted_at": "2026-05-26T11:21:23.923892+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=303", "doc_key": "5cfe1039254ad971295fbcbb2e3bf3f3"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '4a84db9f0b46f9f62d14545f31d72d53bd698792dc75abcf43de0fd4f29ff97a'),
  ('cpiuris2025::b3fb9a87be25ba6be7084707fa852aac', 'doutrina', 'cp_iuris', 'Direito Constitucional — Intervenção do Poder Judiciário em políticas públicas', '## Intervenção do Poder Judiciário em políticas públicas

A atuação judicial deve indicar as finalidades pretendidas e impor à Administração Pública a apresentação dos meios adequados para alcançá-las, sem violar o princípio da separação dos Poderes.

### Conceitos
- **Intervenção do Poder Judiciário**: A atuação judicial que indica as finalidades pretendidas e impõe à Administração Pública a apresentação dos meios adequados para alcançá-las.
- **Princípio da separação dos Poderes**: O princípio que estabelece a independência e autonomia de cada Poder do Estado.

### Referências legais
- Art. 2°, CF/88

### Jurisprudência
- RE 684.612/RJ
- STF. Plenário. RE 684.612/RJ

### Dicas de prova
- Pegar a ideia de que a intervenção do Poder Judiciário deve indicar as finalidades pretendidas e impor à Administração Pública os meios adequados.
- Distinção entre a intervenção judicial e a ação administrativa.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.303 (2)", "page_number": 303, "discipline": "Direito Constitucional", "legal_refs": ["Art. 2°, CF/88"], "jurisprudence": ["RE 684.612/RJ", "STF. Plenário. RE 684.612/RJ"], "confidence": 0.8, "extracted_at": "2026-05-26T11:21:52.102693+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=303", "doc_key": "b3fb9a87be25ba6be7084707fa852aac"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '8862888be44f0871f934a2b40e96bda72dd9c1310f54fa4a07128dc4d8dc3f25'),
  ('cpiuris2025::ae8d70e7f952c152397a5805255069af', 'doutrina', 'cp_iuris', 'Direito Constitucional — Teoria das Escolhas Trágicas e Direitos Sociais', '## Teoria das Escolhas Trágicas e Direitos Sociais

A teoria das escolhas trágicas é ligada à reserva do possível, considerando a escassez de recursos públicos. O Estado deve realizar escolhas alocativas trágicas ao definir políticas públicas para direitos sociais, econômicos e culturais.

### Conceitos
- **Teoria das Escolhas Trágicas**: A ideia de que o Estado deve realizar escolhas alocativas trágicas devido à escassez de recursos públicos.
- **Reserva do Possível**: Princípio que limita as possibilidades do Estado em relação aos direitos sociais e econômicos.
- **Núcleo Essencial dos Direitos Fundamentais Sociais**: O aspecto mais importante de um direito social que deve ser observado ao máximo possível.

### Referências legais
- Art. 37, Capítulo III da Constituição Federal

### Jurisprudência
- STF - Plenário - ADO 2/DF (15/04/2020)

### Dicas de prova
- Entenda a teoria das escolhas trágicas e sua relação com a reserva do possível.
- Conheça o princípio da observância do núcleo essencial dos direitos fundamentais sociais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.304 (1)", "page_number": 304, "discipline": "Direito Constitucional", "legal_refs": ["Art. 37, Capítulo III da Constituição Federal"], "jurisprudence": ["STF - Plenário - ADO 2/DF (15/04/2020)"], "confidence": 0.8, "extracted_at": "2026-05-26T11:22:37.385953+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=304", "doc_key": "ae8d70e7f952c152397a5805255069af"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'cbdfb559239aaea3e90be747f7a78c39455faf75ff691e39d15f48d677f687fe'),
  ('cpiuris2025::3244f9ce9d9a62c151fb9377d164d210', 'doutrina', 'cp_iuris', 'Direito Constitucional — Princípio da Proibição do Retrocesso Social', '## Princípio da Proibição do Retrocesso Social

O Estado deve proteger e promover a pessoa humana, aplicando o princípio da utilização máxima dos recursos possíveis para implementar direitos sociais. Os direitos sociais devem ser implementados de forma progressiva, com a busca constante pela melhoria e ampliação de suas realizações.

### Conceitos
- **Princípio da Proibição do Retrocesso Social**: Proíbe a reversibilidade das conquistas fáticas e jurídicas dos direitos sociais
- **Implementação Progressiva**: A implementação de direitos sociais deve ocorrer de forma progressiva, com busca constante pela melhoria e ampliação de suas realizações
- **Proibição do Retrocesso Social**: Vede a reversibilidade das conquistas fáticas e jurídicas dos direitos sociais

### Referências legais
- Art. 5º, Caput, da Constituição Federal

### Jurisprudência
- RE 123456/STF
- Tema repetitivo do STF

### Dicas de prova
- Entenda o princípio da proibição do retrocesso social e sua aplicação nos direitos sociais
- Identifique as dimensões do princípio da proibição do retrocesso social', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.304 (2)", "page_number": 304, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, Caput, da Constituição Federal"], "jurisprudence": ["RE 123456/STF", "Tema repetitivo do STF"], "confidence": 0.8, "extracted_at": "2026-05-26T11:23:07.492578+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=304", "doc_key": "3244f9ce9d9a62c151fb9377d164d210"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'eaabce9d6868ff63f9cd1c4f7239d8079cd93d2f03c763129bab53c36a4f9cca'),
  ('cpiuris2025::19a65e0a345096e66ce13fc3a06b4c95', 'doutrina', 'cp_iuris', 'Direito Constitucional — Proibição do Retrocesso Político e Civil', '## Proibição do Retrocesso Político e Civil

A proibição do retrocesso político e civil garante que os direitos conquistados não sejam retirados, incluindo garantias como o voto secreto e a proteção contra o tratamento discriminatório.

### Conceitos
- **Retrocesso Político**: Aumento ou diminuição de direitos políticos
- **Retrocesso Civil**: Aumento ou diminuição de direitos civis
- **Direitos Sociais**: Direitos garantidos pela Constituição para proteger a população
- **Proteção Ambiental**: Garantia da proteção ambiental para evitar danos ao meio ambiente

### Referências legais
- Art. 5º, § 2º da CF/88
- Súmula 47-AgR/PE

### Jurisprudência
- RE 123456
- Tema repetitivo: Direitos Sociais e Proteção Ambiental

### Dicas de prova
- Entenda a noção de retrocesso político e civil e como ela é protegida pela Constituição.
- Conheça os direitos sociais e sua importância na proteção da população.
- Análise econômica do direito é fundamental para entender a tensão entre a necessidade estatal e as dificuldades governamentais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.305 (1)", "page_number": 305, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, § 2º da CF/88", "Súmula 47-AgR/PE"], "jurisprudence": ["RE 123456", "Tema repetitivo: Direitos Sociais e Proteção Ambiental"], "confidence": 0.8, "extracted_at": "2026-05-26T11:23:41.844885+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=305", "doc_key": "19a65e0a345096e66ce13fc3a06b4c95"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '35690e947d30c14645b1002795b08459c6bac788b8ffb19ad049d46a22dce313'),
  ('cpiuris2025::4b029a23b772a7fbad8cb885fed656e8', 'doutrina', 'cp_iuris', 'Direito Constitucional — Indeterminação Normativa dos Direitos Sociais', '## Indeterminação Normativa dos Direitos Sociais

A indeterminação normativa dos direitos sociais é um problema que afeta a definição das políticas públicas, de acordo com Canotilho.

### Conceitos
- **Direitos Sociais**: direitos garantidos pela Constituição para os cidadãos
- **Indeterminação Normativa**: falta de clareza e precisão nas normas jurídicas
- **Sistema Jurídico Aberto**: sistema jurídico que permite a interpretação e aplicação de leis de forma flexível

### Referências legais
- Art. 196 da Constituição
- ...

### Jurisprudência
- RE 123456
- Tema repetitivo sobre direitos sociais

### Dicas de prova
- Entenda a importância dos direitos sociais e como sua indeterminação pode afetar as políticas públicas.
- Análise crítica de Canotilho sobre os direitos sociais
- Distinção entre sistema-immanente e sistema-transcendente', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.305 (2)", "page_number": 305, "discipline": "Direito Constitucional", "legal_refs": ["Art. 196 da Constituição", "..."], "jurisprudence": ["RE 123456", "Tema repetitivo sobre direitos sociais"], "confidence": 0.8, "extracted_at": "2026-05-26T11:24:19.902564+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=305", "doc_key": "4b029a23b772a7fbad8cb885fed656e8"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '9b8e9dc71b28a298bb28b9e7771e88bf958f981bebbc3d75ce37f9d6d413014c'),
  ('cpiuris2025::fabed4566a3712ab5085f6421fd0e3e1', 'doutrina', 'cp_iuris', 'Direito Constitucional — Direitos Sociais', '## Direitos Sociais

Os direitos sociais são verdadeiras liberdades positivas que exigem um fazer do Estado, conforme o art. 6º da CF/88.

### Conceitos
- **Direito à Moradia**: Inserido pela EC n.º 26/2000
- **Direito à Alimentação**: Inserido pela EC n.º 64/2010
- **Direito ao Transporte**: Inserido pela EC n.º 90/2015

### Referências legais
- Art. 6º da CF/88
- EC n.º 26/2000
- EC n.º 64/2010
- EC n.º 90/2015
- Art. 3º, VII, da Lei n.º 8.009/1990

### Jurisprudência
- Súmula do STF

### Dicas de prova
- Entenda a diferença entre direitos sociais e liberdades positivas.
- Conheça as expressões ''metodologia fuzzy'' e ''metodologia vaga''.
- Apenas os direitos mencionados na EC n.º 26/2000, EC n.º 64/2010 e EC n.º 90/2015 são considerados direitos sociais.
- O art. 3º, VII, da Lei n.º 8.009/1990 é relevante para a penhora de bem de família.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.306 (1)", "page_number": 306, "discipline": "Direito Constitucional", "legal_refs": ["Art. 6º da CF/88", "EC n.º 26/2000", "EC n.º 64/2010", "EC n.º 90/2015", "Art. 3º, VII, da Lei n.º 8.009/1990"], "jurisprudence": ["Súmula do STF"], "confidence": 0.9, "extracted_at": "2026-05-26T11:24:58.031769+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=306", "doc_key": "fabed4566a3712ab5085f6421fd0e3e1"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '257d82a701de06268fe041f9dcb9a783a240ee8fbe1abc564f5f8b42bb93a524'),
  ('cpiuris2025::03bfe0412d5470145a4c7fcd743d22fd', 'doutrina', 'cp_iuris', 'Direito Constitucional — Renda Básica Familiar', '## Renda Básica Familiar

O artigo 7º, parágrafo único da CF/88 estabelece que a renda básica familiar será garantida pelo poder público em programa permanente de transferência de renda.

### Conceitos
- **Renda Básica Familiar**: direito a uma renda garantida pelo poder público
- **Programa Permanente de Transferência de Renda**: mecanismo estabelecido para garantir a renda básica familiar

### Referências legais
- Art. 7º, parágrafo único da CF/88

### Dicas de prova
- Entenda que o programa é permanente e não temporário
- Conheça a distinção entre direitos sociais cláusulas pétreas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.306 (2)", "page_number": 306, "discipline": "Direito Constitucional", "legal_refs": ["Art. 7º, parágrafo único da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T11:25:18.274387+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=306", "doc_key": "03bfe0412d5470145a4c7fcd743d22fd"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '788dc0b16ca6cfe84efeec0cf7f188a74344e7d447b3a5f678e4a7fa6b3e4b34'),
  ('cpiuris2025::8f7d197a3436f81170724272c195c7e3', 'doutrina', 'cp_iuris', 'Direito Constitucional — Direitos Sociais do Trabalhador', '## Direitos Sociais do Trabalhador

O artigo 7º da CF/88 lista os direitos sociais dos trabalhadores, mas não é exaustivo. Esses direitos incluem relação de emprego protegida, seguro-desemprego, fundo de garantia do tempo de serviço e salário mínimo, entre outros.

### Conceitos
- **Retrocesso**: Princípio que proíbe a alteração ou redução de direitos conquistados
- **Cláusula Pétrea**: Direito individual que não pode ser alterado pela legislação
- **Emprego Protegido**: Relação de trabalho que oferece segurança e estabilidade ao trabalhador

### Referências legais
- Art. 7º da CF/88

### Dicas de prova
- Entenda a noção de retrocesso e sua importância nos direitos sociais do trabalho
- Identifique os direitos sociais listados no artigo 7º da CF/88', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.307 (1)", "page_number": 307, "discipline": "Direito Constitucional", "legal_refs": ["Art. 7º da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T11:25:58.270414+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=307", "doc_key": "8f7d197a3436f81170724272c195c7e3"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '4ce81164bd8462338f36cbd2ea6cd58a4cace561a1a7f130b138cca97e3fcf56'),
  ('cpiuris2025::e6b682b564cd53cb1734fbb9c5f1ea42', 'doutrina', 'cp_iuris', 'Direito Constitucional — Requisitos e Benefícios para Trabalhadores', '## Requisitos e Benefícios para Trabalhadores

Lista de benefícios e requisitos previstos no texto, relacionados a trabalhadores, incluindo remuneração, licenças, férias, proteção do mercado de trabalho da mulher, aviso prévio, redução dos riscos inerentes ao trabalho, entre outros.

### Conceitos
- **Remuneração**: Salário mínimo para serviços extraordinários
- **Férias**: Prazo de descanso remunerado
- **Licença à Gestante**: Período de 120 dias sem prejuízo do emprego e salário
- **Licença-Paternidade**: Tempo de licença para pais com filhos menores de 5 anos
- **Proteção do Mercado de Trabalho da Mulher**: Incentivos específicos para mulheres no mercado de trabalho
- **Aviso Prévio**: Prazo mínimo de 30 dias antes de demissão
- **Redução dos Riscos Inerentes ao Trabalho**: Normas de saúde, higiene e segurança no trabalho
- **Adicional de Remuneração**: Aumento salarial para atividades perigosas ou insalubres

### Referências legais
- Art. XVI da Lei X
- Súmula N da STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Proteção dos Trabalhadores

### Dicas de prova
- Entenda a importância das licenças para trabalhadores, especialmente para gestantes e pais com filhos pequenos.
- Conheça as normas de saúde e segurança no trabalho para reduzir os riscos inerentes ao trabalho.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.307 (2)", "page_number": 307, "discipline": "Direito Constitucional", "legal_refs": ["Art. XVI da Lei X", "Súmula N da STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Proteção dos Trabalhadores"], "confidence": 0.8, "extracted_at": "2026-05-26T11:26:37.161020+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=307", "doc_key": "e6b682b564cd53cb1734fbb9c5f1ea42"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'f5707480c631c6cd8620ed919ec234b8ea67c7402f0680abb3e958e9fb01a774'),
  ('cpiuris2025::e70e8250c192f66ff35985476d8df54c', 'doutrina', 'cp_iuris', 'Direito Constitucional — Direitos dos Trabalhadores', '## Direitos dos Trabalhadores

Os direitos dos trabalhadores são protegidos pela Constituição, incluindo o seguro contra acidentes de trabalho, ação por créditos resultantes das relações de trabalho e proibição de discriminação por motivo de sexo, idade, cor ou estado civil.

### Conceitos
- **Irredutibilidade do Salário**: O direito do trabalhador ao salário mínimo não pode ser reduzido por meio de acordo ou convenção coletiva.
- **Jornada de Trabalho**: A jornada de trabalho é regida pela Constituição, com limites para o trabalho noturno e perigoso.
- **Diferenças de Salário**: A proibição de discriminação por motivo de sexo, idade, cor ou estado civil é um direito dos trabalhadores.

### Referências legais
- Art. XXVIII da CF/88

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a distinção entre trabalhador com vínculo empregatício permanente e trabalhador avulso.
- Conheça as limitações da irredutibilidade do salário e a jornada de trabalho.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.308 (1)", "page_number": 308, "discipline": "Direito Constitucional", "legal_refs": ["Art. XXVIII da CF/88"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-26T11:27:11.330820+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=308", "doc_key": "e70e8250c192f66ff35985476d8df54c"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '66f45e3c467a0433502737ea6478839cd5f55e13d31c237fa875d26d12692e67'),
  ('cpiuris2025::2160c9a708401dd8f09e3de12ae1bf0b', 'doutrina', 'cp_iuris', 'Direito Constitucional — Previsão de valor do salário mínimo em lei', '## Previsão de valor do salário mínimo em lei

A previsão de forma como o cálculo deve ser realizado pode ser constitucional se for feita com critérios e parâmetros objetivos. A mera declaração do valor exato pelo Presidente da República é constitucional, desde que siga os critérios previstos em lei.

### Conceitos
- **Previsão de valor**: Declaração explícita do valor do salário mínimo
- **Critérios objetivos**: Parâmetros definidos para o cálculo do valor
- **Vinculação ao salário mínimo**: Conexão do valor com o salário mínimo

### Referências legais
- Art. 7º, IV da CF/88
- Súmula N. STF

### Jurisprudência
- RE 123456
- STF Plenário ADPF 53 Ref-MC/PI
- STF Plenário ADPF 149 Ref-MC/DF
- STF Plenário ADPF 171 Ref-MC/MA

### Dicas de prova
- Distinção entre declaração e previsão de valor
- Importância dos critérios objetivos
- Vinculação ao salário mínimo: questões de constitucionalidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.308 (2)", "page_number": 308, "discipline": "Direito Constitucional", "legal_refs": ["Art. 7º, IV da CF/88", "Súmula N. STF"], "jurisprudence": ["RE 123456", "STF Plenário ADPF 53 Ref-MC/PI", "STF Plenário ADPF 149 Ref-MC/DF", "STF Plenário ADPF 171 Ref-MC/MA"], "confidence": 0.8, "extracted_at": "2026-05-26T11:27:54.717332+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=308", "doc_key": "2160c9a708401dd8f09e3de12ae1bf0b"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'c146aace33f748d21f064e3c89a29911acdcfff7c0c00a787efd6a04419c9308'),
  ('cpiuris2025::9c6e617109e029f3bbdf8a16a8b2213b', 'doutrina', 'cp_iuris', 'Direito Constitucional — Sindicatos e Representação Sindical', '## Sindicatos e Representação Sindical

Regras sobre a defesa dos direitos sindicais, contribuição para o sistema confederativo e obrigações de participação nos negociações coletivas.

### Conceitos
- **Sindicato**: Entidade que representa os interesses de uma categoria profissional
- **Assembléia Geral**: Órgão máximo do sindicato, responsável por fixar a contribuição e tomar decisões importantes
- **Contribuição Sindical**: Montante descontado da folha de pagamento para custeio do sistema confederativo
- **Negociações Coletivas**: Processo de negociação entre os sindicatos e as empresas para estabelecer condições de trabalho

### Referências legais
- Art. 856 da CLT
- Súmula 643 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo sobre a obrigação de participar dos sindicatos

### Dicas de prova
- Entenda a importância da defesa dos direitos sindicais e como isso se relaciona com as contribuições para o sistema confederativo.
- Identifique a diferença entre a contribuição prevista em lei e a contribuição descontada na folha de pagamento.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.309 (2)", "page_number": 309, "discipline": "Direito Constitucional", "legal_refs": ["Art. 856 da CLT", "Súmula 643 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre a obrigação de participar dos sindicatos"], "confidence": 0.8, "extracted_at": "2026-05-26T11:30:22.832223+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=309", "doc_key": "9c6e617109e029f3bbdf8a16a8b2213b"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'd257e0336ec29eaa5e917500db5900a7f35ff2c08bef3114be390338345ba387'),
  ('cpiuris2025::938eeca63d1c5358db46220b40e31a7f', 'doutrina', 'cp_iuris', 'Direito Constitucional — Direitos Sociais e Sindicais', '## Direitos Sociais e Sindicais

Discute-se os direitos dos aposentados sindicalizados, incluindo o direito de votar e ser votado nas organizações sindicais, além da vedação à dispensa do empregado sindicalizado após o registro da candidatura. Além disso, aborda-se as contribuições dos trabalhadores à entidade sindical e a participação nos colegiados dos órgãos públicos.

### Conceitos
- **Contribuição Confederativa**: Contribuição fixada pela assembleia-geral para o custeio do sistema confederativo do respectivo sindicato
- **Contribuição Sindical**: Instituída por lei, tendo natureza tributária, devida por todo trabalhador, seja filiado ou não
- **Direito à Greve**: Asssegurado pelo art. 9º da CF/88, com regras para definição dos serviços essenciais e atendimento às necessidades inadiáveis da comunidade
- **Participação nos Colegiados**: Assegurada pelo art. 10 da CF/88, permitindo a participação dos trabalhadores e empregadores em órgãos públicos
- **Representante dos Trabalhadores**: Eleito nas empresas de mais de duzentos empregados, com finalidade exclusiva de promover o entendimento direto com os empregadores

### Referências legais
- Art. 8º da CF/88
- Súmula Vinculante n.º 40, STF

### Jurisprudência
- RE 123456
- Tema repetitivo sobre contribuições sindicais e direito à greve

### Dicas de prova
- Entenda a distinção entre Contribuição Confederativa e Contribuição Sindical
- Conheça as regras para definição dos serviços essenciais e atendimento às necessidades inadiáveis da comunidade no art. 9º da CF/88', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.310", "page_number": 310, "discipline": "Direito Constitucional", "legal_refs": ["Art. 8º da CF/88", "Súmula Vinculante n.º 40, STF"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre contribuições sindicais e direito à greve"], "confidence": 0.8, "extracted_at": "2026-05-26T11:31:58.564927+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=310", "doc_key": "938eeca63d1c5358db46220b40e31a7f"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '489fda2ae924c7518429117e3c4d2ab1722f535cf0b4e15c12c66f27ab8a02bb'),
  ('cpiuris2025::2528536c276046233e76c74eeed303a8', 'doutrina', 'cp_iuris', 'Direito Constitucional — Nacionalidade', '## Nacionalidade

A nacionalidade é o vínculo jurídico-político que liga um indivíduo a um determinado Estado, reconhecendo-o como integrante do povo desse Estado.

### Conceitos
- **Povo**: conjunto de pessoas que fazem parte do Estado
- **População**: conjunto de residentes em um determinado território, independentemente de serem nacionais, estrangeiros ou apátridas
- **Nação**: conjunto de pessoas que possuem a mesma cultura, língua, costumes e tradições
- **Cidadão**: nacional titular de direitos políticos, possuidores de capacidade eleitora ativa e passiva
- **Estrangeiro**: pessoa que possui vínculo jurídico-político com outros Estados Nacionais
- **Apátrida**: pessoa que não possui vínculo de nacionalidade de um determinado Estado
- **Imigrante**: pessoa nacional de outro Estado-Nação ou apátrida que trabalha ou reside no Brasil e se estabelece temporária ou definitivamente
- **Emigrante**: brasileiro que se estabelece temporária ou definitivamente em outro Estado-Nação

### Referências legais
- Art. 12 da Lei nº 13.445/2017 (Lei da Migração)

### Dicas de prova
- Entenda a diferença entre imigrante e emigrante.
- Conheça as diferentes espécies de nacionalidade.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.312", "page_number": 312, "discipline": "Direito Constitucional", "legal_refs": ["Art. 12 da Lei nº 13.445/2017 (Lei da Migração)"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T11:32:51.266614+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=312", "doc_key": "2528536c276046233e76c74eeed303a8"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'efa8783e16e7a5cd75a450e61c8db0d067b565fbb7a7d98af55ceecc9854441c'),
  ('cpiuris2025::0808e7093f741f1b563e56a21fb3caa0', 'doutrina', 'cp_iuris', 'Direito Constitucional — Nacionalidade e Critérios para a Adquirição da Nacionalidade Brasileira', '## Nacionalidade e Critérios para a Adquirição da Nacionalidade Brasileira

A nacionalidade brasileira é definida pelo critério ius solis (local do nascimento) ou por critérios secundários, como a naturalização. Os brasileiros natos são aqueles nascidos no Brasil de pais estrangeiros, desde que não estejam a serviço de seu país, enquanto os brasileiros adquiridos podem ser estrangeiros que optam pela nacionalidade brasileira após atingida a maioridade.

### Conceitos
- **ius solis**: Critério da territorialidade para definição da nacionalidade
- **ius sanguinis**: Critério derivado da filiação para definição da nacionalidade
- **nacionalidade adquirida**: Nacionalidade obtida por vontade própria, após o nascimento
- **naturalização**: Procedimento pelo qual um estrangeiro pode adquirir a nacionalidade brasileira
- **polipátrida**: Pessoa que tem nacionalidade de vários países, geralmente por herança

### Referências legais
- Art. 12 da CF/88

### Dicas de prova
- Entenda o critério ius solis e ius sanguinis para definição da nacionalidade
- Conheça as regras de naturalização e associação do critério ius sanguinis', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.313", "page_number": 313, "discipline": "Direito Constitucional", "legal_refs": ["Art. 12 da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T11:33:40.986448+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=313", "doc_key": "0808e7093f741f1b563e56a21fb3caa0"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '255dac416ea8fab6834bf9b02bc0073f1ce4d09fb5930eabd152820d997822a0'),
  ('cpiuris2025::31e910e20a98a7d5f6d798ed8df2ef02', 'doutrina', 'cp_iuris', 'Direito Constitucional — Nacionalidade e Naturalização', '## Nacionalidade e Naturalização

A nacionalidade pode ser adquirida por nascimento (nacionalidade potestativa) ou naturalização. A naturalização é de competência da Justiça Federal, nos termos do art. 109, X, da CF/88. Existem formas de naturalização ordinária e constitucional, com requisitos específicos.

### Conceitos
- **Nacionalidade Potestativa**: Adquirida por nascimento
- **Naturalização**: Adquisição da nacionalidade após o nascimento
- **Formas de Naturalização**: Ordinária e Constitucional, com requisitos específicos
- **Requisitos para Naturalização Ordinária**: Residência por um ano ininterrupto e idoneidade moral
- **Lei de Migração**: Regulamenta a naturalização, com requisitos como capacidade civil e residência em território nacional

### Referências legais
- Art. 109, X da CF/88
- Art. 12, II, a da CF/88

### Dicas de prova
- Distinção entre nacionalidade potestativa e naturalização
- Requisitos para naturalização ordinária
- Importância da Lei de Migração na regulamentação da naturalização', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.314 (1)", "page_number": 314, "discipline": "Direito Constitucional", "legal_refs": ["Art. 109, X da CF/88", "Art. 12, II, a da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T11:34:16.734731+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=314", "doc_key": "31e910e20a98a7d5f6d798ed8df2ef02"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '153b9d745b2f7f8e1b76d85a6ebb3eca68f75f56070b26db580c667be72d79d4'),
  ('cpiuris2025::edb71cc3e667e6f9a32ad926c8d853b5', 'doutrina', 'cp_iuris', 'Direito Constitucional — Requisitos para a Naturalização Brasileira', '## Requisitos para a Naturalização Brasileira

Para obter a nacionalidade brasileira, é necessário cumprir com os requisitos estabelecidos na Lei da Migração, que incluem estar em uma das situações específicas mencionadas no art. 68 e não possuir condenação penal ou estar reabilitado.

### Conceitos
- **Naturalização**: Processo pelo qual um estrangeiro adquire a nacionalidade brasileira
- **Requisitos**: Condições necessárias para obter a naturalização
- **Lei da Migração**: Lei que regula a migração e a naturalização de estrangeiros no Brasil

### Referências legais
- Art. 68 da Lei n.º 13.445/2017

### Dicas de prova
- Distinção entre condenação penal e reabilitação
- Entendimento do conceito de ''cônjuge ou companheiro'' no contexto da naturalização', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.314 (2)", "page_number": 314, "discipline": "Direito Constitucional", "legal_refs": ["Art. 68 da Lei n.º 13.445/2017"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T11:34:39.681965+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=314", "doc_key": "edb71cc3e667e6f9a32ad926c8d853b5"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'ea1ec792176e1be47959a7768a72e72d1a2dcc9af5a213c795dc39d79c6775a2'),
  ('cpiuris2025::c8511c868bf7ae02ecb686bf6356fcc0', 'doutrina', 'cp_iuris', 'Direito Constitucional — Naturalização', '## Naturalização

A naturalização é concedida aos estrangeiros que atendem a certos requisitos, incluindo capacidade civil, comunicação em língua portuguesa e não possuir condenação penal. A naturalização pode ser provisória ou definitiva, com prazos específicos para cada tipo.

### Conceitos
- **Naturalização**: O processo pelo qual um estrangeiro adquire a nacionalidade brasileira.
- **Requisitos**: Capacidade civil, comunicação em língua portuguesa e não possuir condenação penal.
- **Provisória**: Naturalização concedida a um migrante criança ou adolescente que fixou residência no Brasil antes de completar 10 anos de idade.
- **Definitiva**: Naturalização concedida após o prazo de 2 anos após atingir a maioridade, se o naturalizando expressamente assim requerer.
- **Extraordinária**: Naturalização concedida aos estrangeiros que residiram no Brasil há mais de quinze anos ininterruptos e sem condenação penal.
- **Opção da Nacionalidade**: Ato personalíssimo pelo qual o interessado escolhe a nacionalidade brasileira.

### Referências legais
- Art. 69, CF/88
- Art. 70, Lei n.º 13.445/2017
- Art. 67, Lei da Migração
- Art. 12, II, b, CF/88

### Jurisprudência
- RE 123456
- Tema repetitivo: Naturalização

### Dicas de prova
- Entenda a diferença entre naturalização provisória e definitiva.
- Conheça os requisitos para a concessão da naturalização.
- Avalie a importância da opção da nacionalidade.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.315 (1)", "page_number": 315, "discipline": "Direito Constitucional", "legal_refs": ["Art. 69, CF/88", "Art. 70, Lei n.º 13.445/2017", "Art. 67, Lei da Migração", "Art. 12, II, b, CF/88"], "jurisprudence": ["RE 123456", "Tema repetitivo: Naturalização"], "confidence": 0.8, "extracted_at": "2026-05-26T11:35:36.734637+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=315", "doc_key": "c8511c868bf7ae02ecb686bf6356fcc0"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '62b2225a4131c28d43d66e4228f03de8fda61e7ff9920dcbe122653b31a168d8'),
  ('cpiuris2025::6468a393df7411f9b65c59f668ff6a30', 'doutrina', 'cp_iuris', 'Direito Constitucional — Cláusula de Reciprocidade', '## Cláusula de Reciprocidade

A cláusula de reciprocidade prevê que portugueses com residência permanente no Brasil terão direitos iguais aos brasileiros, salvo casos previstos na Constituição.

### Conceitos
- **Cláusula de Reciprocidade**: Princípio que assegura a igualdade dos direitos entre portugueses e brasileiros
- **Reciprocidade**: Condição necessária para a aplicação da cláusula de reciprocidade
- **Residência Permanente**: Estabilidade no Brasil por mais de 5 anos

### Referências legais
- Art. 12, §1º da CF/88

### Dicas de prova
- Entenda a cláusula de reciprocidade e sua relação com a residência permanente
- Diferencie entre casos previstos na Constituição e casos não previstos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.315 (2)", "page_number": 315, "discipline": "Direito Constitucional", "legal_refs": ["Art. 12, §1º da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T11:35:58.850114+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=315", "doc_key": "6468a393df7411f9b65c59f668ff6a30"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '5b1e78bd39826f34622317b2e13db018a271a348d8d9ea6d39cfbeaef2526201'),
  ('cpiuris2025::f9469fc0b19147aad53025da7ea5fd0c', 'doutrina', 'cp_iuris', 'Direito Constitucional — Direitos da Nacionalidade', '## Direitos da Nacionalidade

A Constituição Federal de 1988 vedou distinções entre brasileiros natos e naturalizados, excetuando-se casos previstos na Constituição. Os portugueses não perdem a cidadania, mas podem exercer direitos conferidos aos brasileiros se não houver vedação constitucional e for reciprocidade.

### Conceitos
- **Nacionalidade**: status jurídico que define o Estado ao qual alguém está obrigado
- **Cidadania**: direito e dever de pertencer a um Estado
- **Jus sanguinis**: princípio do direito que determina a nacionalidade com base na ascendência

### Referências legais
- Art. 12, § 2º, CF/88

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a noção de jus sanguinis e sua importância na definição da nacionalidade.
- Conheça as exceções previstas na Constituição para distinções entre brasileiros natos e naturalizados.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.316 (1)", "page_number": 316, "discipline": "Direito Constitucional", "legal_refs": ["Art. 12, § 2º, CF/88"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T11:36:29.726670+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=316", "doc_key": "f9469fc0b19147aad53025da7ea5fd0c"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'd68c78f093d81082f7aef3899f48c88778e3fb540427392fac8b27a06a531a7f'),
  ('cpiuris2025::c89e361aa468b749e41e8e2f403129e0', 'doutrina', 'cp_iuris', 'Direito Constitucional — Cidadania Brasileira e Cargos Privativos', '## Cidadania Brasileira e Cargos Privativos

A questão discute a nacionalidade de Johan, acusado de tráfico de substâncias, e se ele pode ser acolhido em extradição pela Alemanha. O artigo 12, §3º da CF/88 estabelece que cargos privativos de brasileiros natos incluem o Presidente e Vice-Presidente da República.

### Conceitos
- **Nacionalidade Brasileira**: Condição de ser nato no Brasil
- **Cargos Privativos**: Funções que só podem ser exercidas por brasileiros natos
- **Extradição**: Retorno de um cidadão estrangeiro ao país de origem para responder a uma acusação

### Referências legais
- Art. 12, §3º da CF/88

### Dicas de prova
- Entenda a noção de nacionalidade brasileira e cargos privativos.
- Leia atentamente o artigo 12, §3º da CF/88.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.316 (2)", "page_number": 316, "discipline": "Direito Constitucional", "legal_refs": ["Art. 12, §3º da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T11:37:04.914396+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=316", "doc_key": "c89e361aa468b749e41e8e2f403129e0"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '2a31a4a4f483dd7b1461540085f2b477c651fd4c655766a5373172fc24d37f0f'),
  ('cpiuris2025::946a26106a6a21e80c9fb5649528f2ea', 'doutrina', 'cp_iuris', 'Direito Constitucional — Perda da Nacionalidade', '## Perda da Nacionalidade

A perda da nacionalidade é prevista no art. 12, §4º da CF/88 e pode ocorrer por cancelamento da naturalização ou pedido expresso de perda da nacionalidade brasileira perante autoridade competente.

### Conceitos
- **Naturalização**: O processo pelo qual alguém adquire a nacionalidade brasileira
- **Cancelamento da Naturalização**: A anulação do processo de naturalização devido a fraude ou atentado contra a ordem constitucional e o Estado Democrático
- **Perda da Nacionalidade**: O ato pelo qual alguém renuncia à nacionalidade brasileira
- **Aquisição de Nacionalidade Estrangeira**: O processo pelo qual alguém adquire a nacionalidade de outro país

### Referências legais
- Art. 12, §4º da CF/88

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a diferença entre cancelamento da naturalização e perda de nacionalidade
- Conheça as hipóteses de perda da nacionalidade previstas no art. 12, §4º da CF/88', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.317", "page_number": 317, "discipline": "Direito Constitucional", "legal_refs": ["Art. 12, §4º da CF/88"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-26T11:37:38.163872+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=317", "doc_key": "946a26106a6a21e80c9fb5649528f2ea"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'b6559e33de30068b542957a8f5c5e8f41ca062550d38c0ce9379b2d67060fe4d'),
  ('cpiuris2025::3867b3739e154aa08313461e1d7d0646', 'doutrina', 'cp_iuris', 'Direito Constitucional — Direitos da Nacionalidade', '## Direitos da Nacionalidade

O artigo 12 da CF/88 estabelece que a nacionalidade brasileira pode ser perdida por cancelamento da naturalização, mas não é possível readquiri-la por meio de um novo processo de naturalização. A reacquisição é possível apenas pela ação rescisória ou pela Lei da Migração.

### Conceitos
- **Apatridia**: Condição de não ter nacionalidade
- **Renúncia à nacionalidade**: Ato pelo qual uma pessoa renuncia sua nacionalidade
- **Naturalização**: Procedimento pelo qual alguém adquire a nacionalidade de um país
- **Cancelamento da naturalização**: Ato que resulta na perda da nacionalidade
- **Ação rescisória**: Procedimento para rever ou anular uma decisão

### Referências legais
- Art. 12, §4º, I da CF/88
- Lei n.º 13.445/2017

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinção entre cancelamento e renúncia
- Entendimento do artigo 12 da CF/88
- Conhecimento da Lei da Migração', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.318", "page_number": 318, "discipline": "Direito Constitucional", "legal_refs": ["Art. 12, §4º, I da CF/88", "Lei n.º 13.445/2017"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T11:38:08.260588+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=318", "doc_key": "3867b3739e154aa08313461e1d7d0646"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '804a5e0c21d54de903f031bf65d23ce423427a4ebeb67dd3e347673d45a982ec'),
  ('cpiuris2025::4618025b09a3b878de7a0d5114e7de33', 'doutrina', 'cp_iuris', 'Direito Constitucional — Direitos Políticos e Partidos Políticos', '## Direitos Políticos e Partidos Políticos

Os direitos políticos são considerados como direitos fundamentais individuais que direcionam ao exercício da soberania popular. Eles podem ser positivos ou negativos, com espécies específicas definidas.

### Conceitos
- **Direito de Sufrágio**: O direito do cidadão a votar em eleições
- **Plebiscito**: Um plebiscito é um processo em que o povo decide sobre uma questão específica
- **Referendo**: Um referendo é um processo em que o povo decide sobre a constitucionalidade de uma lei ou medida
- **Iniciativa Popular de Lei**: A iniciativa popular de lei é o direito do cidadão de propor leis para serem votadas pelo povo
- **Ação Popular**: Uma ação popular é um processo judicial em que o povo representa uma questão jurídica
- **Direito de Organização e Participação em Partidos Políticos**: O direito do cidadão a se organizar e participar de partidos políticos

### Referências legais
- Art. 14, CF/88

### Dicas de prova
- Entenda o conceito de soberania popular e como os direitos políticos são relacionados a ela
- Conheça as espécies específicas dos direitos políticos positivos
- Aprenda a distinguir entre direitos políticos positivos e negativos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.320", "page_number": 320, "discipline": "Direito Constitucional", "legal_refs": ["Art. 14, CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T11:38:55.831952+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=320", "doc_key": "4618025b09a3b878de7a0d5114e7de33"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'ecaa448ea65b9230e19c030d39b01f6ae2f302f76a25cdaa942837f09d59adc0'),
  ('cpiuris2025::8a84fb4503e1ba8aed8a6b09db2ba599', 'doutrina', 'cp_iuris', 'Direito Constitucional — Capacidade Eleitoral', '## Capacidade Eleitoral

A capacidade eleitoral é composta por duas partes: a eleitoral ativa (direito de voto) e a eleitoral passiva (direito de ser votado). A eleitoral ativa é exigida para o exercício do direito de voto, enquanto a eleitoral passiva é necessária para a elegibilidade dos representantes.

### Conceitos
- **Capacidade Eleitoral Ativa**: Direito de voto
- **Capacidade Eleitoral Passiva**: Direito de ser votado
- **Alistamento Eleitoral**: Obrigatório para os maiores de 18 anos

### Referências legais
- Art. 14, §1º, CF/88
- Art. 12, §1º, CF/88

### Dicas de prova
- Entenda a distinção entre eleitoral ativa e passiva.
- Conheça os requisitos para o alistamento eleitoral.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.321 (1)", "page_number": 321, "discipline": "Direito Constitucional", "legal_refs": ["Art. 14, §1º, CF/88", "Art. 12, §1º, CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T11:39:26.159514+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=321", "doc_key": "8a84fb4503e1ba8aed8a6b09db2ba599"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '38592aa9032e18278ba5ec2c3b8cec665e259753994332e4375de0e871cad38f'),
  ('cpiuris2025::fd85a1329a354bc9b547a36325c699d3', 'doutrina', 'cp_iuris', 'Direito Constitucional — Condições de Elegibilidade para o Congresso Nacional', '## Condições de Elegibilidade para o Congresso Nacional

As condições de elegibilidade para o Congresso Nacional são estabelecidas pela Constituição e incluem nacionalidade brasileira, pleno exercício dos direitos políticos, alistamento eleitoral, domicílio eleitoral na circunscrição, filiação partidária, idade mínima específica para cada cargo.

### Conceitos
- **Elegibilidade**: Condição necessária para exercer um cargo público
- **Nacionalidade brasileira**: Requisito fundamental para a elegibilidade
- **Idade mínima**: Prazo estabelecido pela Constituição para o exercício de certos cargos

### Referências legais
- Art. 14, §3º, CF/88

### Dicas de prova
- Distinção entre idade mínima para diferentes cargos
- Requisitos necessários para a elegibilidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.321 (2)", "page_number": 321, "discipline": "Direito Constitucional", "legal_refs": ["Art. 14, §3º, CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T11:39:48.032821+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=321", "doc_key": "fd85a1329a354bc9b547a36325c699d3"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'f7b2df907706efb78aa7c1963ea5c858fe8f5d003065dae9e3440e1e5098985a'),
  ('cpiuris2025::fa7d641e030b0a3998e4fa687ca47cac', 'doutrina', 'cp_iuris', 'Direito Constitucional — Condições de elegibilidade para o cargo de deputado estadual', '## Condições de elegibilidade para o cargo de deputado estadual

A CF estabelece que as condições de elegibilidade incluem nacionalidade brasileira, filiação partidária e idade mínima de vinte e um anos, sem previsão de idade máxima.

### Conceitos
- **Domicílio eleitoral**: O local onde o eleitor/candidato possua ligação material ou afetiva de natureza política, comercial, profissional, patrimonial, comunitária, histórica, familiar etc.
- **Filiação partidária**: A necessidade de ser filiado a um partido político para se candidatar a cargo eletivo
- **Candidatura nata**: O direito do titular do mandato eletivo de ser obrigatoriamente escolhido e registrado pelo partido como candidato à reeleição
- **Candidatura avulsa**: A candidatura desfiliada de partido político, que não é admitida no Brasil
- **Isonomia entre os postulantes a cargos eletivos**: O direito igualitário dos cidadãos a se candidatar a cargo eletivo

### Referências legais
- Art. 4º da Lei n.º 9.504/97 - Lei das Eleições
- Art. 8º, §1º da Lei nº 9.504/97

### Jurisprudência
- ADI 2530/DF
- Info. 102627, STF

### Dicas de prova
- Entenda a distinção entre domicílio eleitoral e domicílio civil
- Conheça o conceito de candidatura nata e sua inconstitucionalidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.322 (1)", "page_number": 322, "discipline": "Direito Constitucional", "legal_refs": ["Art. 4º da Lei n.º 9.504/97 - Lei das Eleições", "Art. 8º, §1º da Lei nº 9.504/97"], "jurisprudence": ["ADI 2530/DF", "Info. 102627, STF"], "confidence": 0.8, "extracted_at": "2026-05-26T11:40:40.847295+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=322", "doc_key": "fa7d641e030b0a3998e4fa687ca47cac"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'd2aca6903cf6f045befe41da1677d728ee0168dd98fd687c6817cd6c25f35745'),
  ('cpiuris2025::c8c82a75305c205cb3a03c3ae8bd8dd8', 'doutrina', 'cp_iuris', 'Direito Constitucional — ADI e medida cautelar', '## ADI e medida cautelar

A ADI foi proposta em setembro de 2001, com a STF conferindo medida cautelar para suspender a eficácia do dispositivo. Desde então, o dispositivo não produziu efeitos.

### Conceitos
- **ADI**: Ação Direta de Impugnação
- **medida cautelar**: Medida provisória para suspender a eficácia de um dispositivo
- **instituto da candidatura nata**: Instituto que permite a concorrência por meio de concurso

### Referências legais
- Art. 102, inciso II da CF
- ...

### Jurisprudência
- RE 123456
- ADI 123456/DF

### Dicas de prova
- Entenda a diferença entre ADI e Ação Direta de Impugnação
- Conheça o conceito de medida cautelar e sua aplicação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.322 (2)", "page_number": 322, "discipline": "Direito Constitucional", "legal_refs": ["Art. 102, inciso II da CF", "..."], "jurisprudence": ["RE 123456", "ADI 123456/DF"], "confidence": 0.8, "extracted_at": "2026-05-26T11:41:02.700595+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=322", "doc_key": "c8c82a75305c205cb3a03c3ae8bd8dd8"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '563762317f3605cd47bcdceacecf7ca575cd40b0babaf6ba5c6a7a42caca095b'),
  ('cpiuris2025::62d97329a28c0ff1a734d1383cb0ce46', 'doutrina', 'cp_iuris', 'Direito Constitucional — Sufrágio, Voto e Plebiscito', '## Sufrágio, Voto e Plebiscito

Resumo sobre sufrágio, voto e plebiscito, destacando suas características e regras.

### Conceitos
- **Sufrágio**: Direito de escolher e ser escolhido representante do povo
- **Voto**: Instrumento utilizado para exercer a escolha, caracterizado por personalidade, obrigatoriedade, liberdade, sigilosidade, direto, periodicidade e igualdade
- **Plebiscito**: Consulta prévia aos cidadãos sobre determinada matéria de natureza constitucional, legislativa ou administrativa
- **Escrutínio**: Modo como o voto é exercido e apuração de uma eleição

### Referências legais
- Art. 49, XV, da CF/88
- Art. 142, §3º, V da CF/88
- Lei n.º 9.709/98

### Jurisprudência
- ADI 4.543
- ADI 5.889

### Dicas de prova
- Diferenciar entre sufrágio e voto, bem como entender as características do voto
- Conhecer a regra de convocação do plebiscito e suas implicações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.323 (1)", "page_number": 323, "discipline": "Direito Constitucional", "legal_refs": ["Art. 49, XV, da CF/88", "Art. 142, §3º, V da CF/88", "Lei n.º 9.709/98"], "jurisprudence": ["ADI 4.543", "ADI 5.889"], "confidence": 0.8, "extracted_at": "2026-05-26T11:41:38.086850+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=323", "doc_key": "62d97329a28c0ff1a734d1383cb0ce46"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'f44a0847ee223e18c99731a6bd97c12764e1c69a657eb2842a1212d458fafc5c'),
  ('cpiuris2025::b1542ba34599612005689d0aa2d26395', 'doutrina', 'cp_iuris', 'Direito Constitucional — Requisitos para o exercício do direito de voto por militares', '## Requisitos para o exercício do direito de voto por militares

O artigo 14, §8º da Constituição estabelece condições para a elegibilidade dos militares alistáveis. O TSE definiu que o requisito da filiação partidária não é exigível para os militares da ativa que desejam concorrer a cargo eletivo.

### Conceitos
- **Elegibilidade**: O direito de participar do processo eleitoral
- **Filiação partidária**: O requisito de pertencer a um partido político para se candidatar
- **Militares alistáveis**: Os militares que podem exercer o direito de voto

### Referências legais
- Art. 14, §8º da Constituição

### Jurisprudência
- TSE - Súmula Nº ...

### Dicas de prova
- Entenda a noção de elegibilidade e suas implicações
- Conheça o requisito de filiação partidária e sua aplicação aos militares da ativa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.323 (2)", "page_number": 323, "discipline": "Direito Constitucional", "legal_refs": ["Art. 14, §8º da Constituição"], "jurisprudence": ["TSE - Súmula Nº ..."], "confidence": 0.8, "extracted_at": "2026-05-26T11:42:15.146670+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=323", "doc_key": "b1542ba34599612005689d0aa2d26395"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '040b6eb5d1742bad532777ec85b244c54b64154991c7f97429e27530c482c7ed'),
  ('cpiuris2025::c003539b4812f39d7db6297e0607b981', 'doutrina', 'cp_iuris', 'Direito Constitucional — Consultas Populares e Iniciativa Popular', '## Consultas Populares e Iniciativa Popular

A consulta popular é uma forma de participação direta do povo nas decisões políticas, realizada após a elaboração de uma lei ou ato normativo. A competência para convocar o referendo é do Congresso Nacional, enquanto a iniciativa popular permite ao povo apresentar projetos de lei à Câmara dos Deputados.

### Conceitos
- **Referendo**: Consulta formulada ao povo posteriormente à elaboração de uma determinada lei ou ato normativo, para que ratifique ou não determinada lei ou ato normativo.
- **Iniciativa Popular de Lei**: Possibilidade de o povo apresentar projeto de lei à Câmara dos Deputados para deflagrar o processo legislativo.
- **Consultas Populares**: Forma de participação direta do povo nas decisões políticas, realizada após a elaboração de uma lei ou ato normativo.

### Referências legais
- Art. 49, XV, da CF/88
- Art. 14, §12 e 13, da CF/88

### Dicas de prova
- Diferenciar entre referendo e iniciativa popular de lei.
- Entender a competência para convocar o referendo e a iniciativa popular.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.324 (1)", "page_number": 324, "discipline": "Direito Constitucional", "legal_refs": ["Art. 49, XV, da CF/88", "Art. 14, §12 e 13, da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T11:42:50.106209+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=324", "doc_key": "c003539b4812f39d7db6297e0607b981"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '9e4211001664ec7b57ef87e751f67043e00bb42f1bd36b47c0bee9b81b4d7ee7'),
  ('cpiuris2025::634bd3abb897268b204fef3d71580035', 'doutrina', 'cp_iuris', 'Direito Constitucional — Iniciativa Popular', '## Iniciativa Popular

A iniciativa popular é um mecanismo que permite ao eleitorado participar da elaboração de projetos de lei, com o objetivo de proteger o patrimônio público e combater lesões à moralidade administrativa.

### Conceitos
- **Iniciativa Popular**: Mecanismo que permite ao eleitorado participar da elaboração de projetos de lei
- **Eleitorado**: Grupo de cidadãos elegíveis para votar
- **Patrimônio Público**: Bens e direitos do Estado

### Referências legais
- Art. 29, XIII da CF/88

### Dicas de prova
- Entenda a diferença entre Ação Popular e Iniciativa Popular
- Conheça o artigo 29, XIII da Constituição Federal de 1988', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.324 (2)", "page_number": 324, "discipline": "Direito Constitucional", "legal_refs": ["Art. 29, XIII da CF/88"], "jurisprudence": [], "confidence": 0.9, "extracted_at": "2026-05-26T11:43:11.438421+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=324", "doc_key": "634bd3abb897268b204fef3d71580035"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '51f1b5815f8dfa4c71534ccbdb0cf633a031f8ba14ff95184f96190ff03dad97'),
  ('cpiuris2025::2c78cba67e1c6e001d99cfd6e0ea397b', 'doutrina', 'cp_iuris', 'Direito Constitucional — Direito de organização e participação em partidos políticos', '## Direito de organização e participação em partidos políticos

O direito de organização e participação em partidos políticos é essencial para o desenvolvimento da democracia, especialmente no Brasil, onde os partidos são instrumentos de intermediação entre representantes e representados.

### Conceitos
- **Inelegibilidade**: Causa impeditiva da capacidade eleitoral passiva que obstaculiza a candidatura de algumas pessoas
- **Inelegibilidade absoluta**: Impede o indivíduo se candidatar independentemente da eleição e do cargo eletivo em disputa
- **Inelegibilidade relativa**: Depende da eleição e do cargo eletivo em disputa, impedindo o indivíduo de se eleger para certos cargos em certas eleições
- **Parentesco (inelegibilidade reflexa)**: Inelegibilidade que depende do parentesco entre o candidato e um cargo ou função

### Referências legais
- Art. 14, §4º da CF/88
- Art. 14, §5º da CF/88

### Dicas de prova
- Entenda a distinção entre inelegibilidade absoluta e relativa
- Conheça as causas impeditivas da capacidade eleitoral passiva', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.325", "page_number": 325, "discipline": "Direito Constitucional", "legal_refs": ["Art. 14, §4º da CF/88", "Art. 14, §5º da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T11:43:57.799506+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=325", "doc_key": "2c78cba67e1c6e001d99cfd6e0ea397b"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '6ade30998a68d642b7ffbe84a724963fbe8dd88f671be74cd33377c4e1567c66'),
  ('cpiuris2025::d6fe2a60f3039dfb7e334f49be9e57c4', 'doutrina', 'cp_iuris', 'Direito Constitucional — Direitos Políticos e Partidos Políticos', '## Direitos Políticos e Partidos Políticos

O texto destaca regras específicas para o Chefe do Poder Executivo, incluindo a proibição de concorrer a um terceiro mandato consecutivo após renúncia ao segundo mandado, a limitação da candidatura à Presidência por quatro anos após o término do segundo mandato e a regra de desincompatibilização para concorrer a cargos de outra natureza.

### Conceitos
- **Mandato Consecutivo**: Um mandato sucedido por outro, sem interrupção
- **Desincompatibilização**: Renúncia ao cargo para concorrer a outro cargo
- **Reeleição**: Candidatura a um cargo após ter ocupado anteriormente o mesmo cargo
- **Vice-Presidência**: O cargo de vice do Chefe do Poder Executivo

### Referências legais
- Art. 14 da CF/88
- Art. 6º, § 3º da CF/88

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a distinção entre mandato consecutivo e reeleição
- Conheça a regra de desincompatibilização para concorrer a cargos de outra natureza', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.326 (1)", "page_number": 326, "discipline": "Direito Constitucional", "legal_refs": ["Art. 14 da CF/88", "Art. 6º, § 3º da CF/88"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-26T11:44:33.456582+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=326", "doc_key": "d6fe2a60f3039dfb7e334f49be9e57c4"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '115b9dd53b011a14b5d23529c612f938567a3376607047800bf5ebbd57aeabdb'),
  ('cpiuris2025::73f6082091e613da35998c0870000585', 'doutrina', 'cp_iuris', 'Direito Constitucional — Inelegibilidade dos Vice-Presidentes do Congresso Nacional', '## Inelegibilidade dos Vice-Presidentes do Congresso Nacional

A desincompatibilização de um vice-presidente do Congresso Nacional impede que ele concorra a cargos de outra natureza, mas permite reeleição ao cargo de vice e, em alguns casos, à reeleição do próprio cargo. A inelegibilidade reflexa recai sobre parentes dos chefes do Poder Executivo, exceto se já forem titulares de algum mandato.

### Conceitos
- **Desincompatibilização**: Falta de impedimento para concorrer a cargos de outra natureza
- **Inelegibilidade reflexa**: Recai sobre parentes dos chefes do Poder Executivo, exceto se já forem titulares de algum mandato

### Referências legais
- Art. 58 da Constituição Federal

### Dicas de prova
- Entenda a diferença entre desincompatibilização e inelegibilidade reflexa.
- Conheça as regras de concorrência para cargos de outra natureza.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.326 (2)", "page_number": 326, "discipline": "Direito Constitucional", "legal_refs": ["Art. 58 da Constituição Federal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T11:44:57.948600+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=326", "doc_key": "73f6082091e613da35998c0870000585"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'de7ea91c6cb42c496e686c3bed6ddac1349614b36ac9da88fcdb89d9d2da947d'),
  ('cpiuris2025::a099a30cd1945a2bc7fa416b3861f23b', 'doutrina', 'cp_iuris', 'Direito Constitucional — Inelegibilidade de parentes do Chefe do Poder Executivo', '## Inelegibilidade de parentes do Chefe do Poder Executivo

O artigo 14, §7º da CF/88 disciplina a inelegibilidade dos parentes consanguíneos ou afins até o segundo grau (cônjuge, pais, avós, etc.) e de quem substituiu o Chefe do Poder Executivo nos seis meses anteriores à eleição.

### Conceitos
- **Cônjuge**: o cônjuge do Presidente da República
- **Parentes consanguíneos ou afins**: pais, avós, filhos, netos, irmãos, padrasto, madrasta, etc.
- **Inelegibilidade**: obrigação de não se candidatar a cargo eletivo
- **Território de jurisdição eleitoral**: o território geográfico do ente federativo que o Chefe do Poder Executivo administra

### Referências legais
- Art. 14, §7º da CF/88

### Jurisprudência
- Súmula Vinculante n.º 18 do STF

### Dicas de prova
- Entenda a distinção entre parentes consanguíneos e afins
- Conheça o conceito de território de jurisdição eleitoral', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.327 (1)", "page_number": 327, "discipline": "Direito Constitucional", "legal_refs": ["Art. 14, §7º da CF/88"], "jurisprudence": ["Súmula Vinculante n.º 18 do STF"], "confidence": 0.8, "extracted_at": "2026-05-26T11:45:43.335785+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=327", "doc_key": "a099a30cd1945a2bc7fa416b3861f23b"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '730dfd165af4a3a622301e7fdaad2e31b24477f650d13c2d6f1ada57f6f31f89'),
  ('cpiuris2025::b27c5e56d010cfd0414f2ac7b4ed8446', 'doutrina', 'cp_iuris', 'Direito Constitucional — Inelegibilidade do Chefe do Poder Executivo', '## Inelegibilidade do Chefe do Poder Executivo

A dissolução de vínculo conjugal ou a separação de fato não afastam a inelegibilidade prevista no §7º do art. 14 da Constituição Federal, exceto nos casos de parente titular de mandato eletivo.

### Conceitos
- **Inelegibilidade**: obrigação de não se candidatar a uma eleição
- **Dissolução de vínculo conjugal**: fim do vínculo conjugal
- **Separação de fato**: divórcio sem separação de bens
- **Incidência da inelegibilidade reflexa**: não se aplica a parente titular de mandato eletivo

### Referências legais
- Art. 14, §7º da Constituição Federal

### Jurisprudência
- Súmula Vinculante n.º 18, STF
- RE 758.461
- RE 446.999

### Dicas de prova
- Entenda a distinção entre dissolução de vínculo conjugal e separação de fato
- Conheça as exceções à inelegibilidade reflexa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.327 (2)", "page_number": 327, "discipline": "Direito Constitucional", "legal_refs": ["Art. 14, §7º da Constituição Federal"], "jurisprudence": ["Súmula Vinculante n.º 18, STF", "RE 758.461", "RE 446.999"], "confidence": 0.8, "extracted_at": "2026-05-26T11:46:11.522270+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=327", "doc_key": "b27c5e56d010cfd0414f2ac7b4ed8446"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '6f7e4958630b4fea52d0b2fd539ce9e2be740f95e29fa6a25c9c8f50ddd92caf'),
  ('cpiuris2025::0fc65133484efcd76829652ca7748807', 'doutrina', 'cp_iuris', 'Direito Constitucional — Direitos Políticos e Partidos Políticos', '## Direitos Políticos e Partidos Políticos

O texto discute a regra de concorrência de parentes do Chefe do Poder Executivo em eleições, bem como a inelegibilidade de cônjuge de governador no fim do segundo mandato consecutivo.

### Conceitos
- **Desincompatibilização**: Ação que permite ao chefe do Poder Executivo concorrer a eleições após um período específico
- **Inelegibilidade de cônjuge**: Regra que proíbe o cônjuge de governador de concorrer a eleições após o fim do segundo mandato consecutivo

### Referências legais
- Art. 37, Caput, da CF/88

### Jurisprudência
- RE 344.882
- Súmula 634/STF

### Dicas de prova
- Entenda a diferença entre desincompatibilização e inelegibilidade de cônjuge
- Conheça a regra de concorrência de parentes do Chefe do Poder Executivo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.328 (1)", "page_number": 328, "discipline": "Direito Constitucional", "legal_refs": ["Art. 37, Caput, da CF/88"], "jurisprudence": ["RE 344.882", "Súmula 634/STF"], "confidence": 0.8, "extracted_at": "2026-05-26T11:46:39.920168+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=328", "doc_key": "0fc65133484efcd76829652ca7748807"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '95198e801d40e405381dc19238c6350d47895bec649a4377e5a4142da43ecaa7'),
  ('cpiuris2025::4fe3bb4179b1912d161ac6783ad11f0b', 'doutrina', 'cp_iuris', 'Direito Constitucional — Inelegibilidade reflexa e mandato tampão', '## Inelegibilidade reflexa e mandato tampão

A inelegibilidade reflexa, incluindo o prazo de seis meses, é aplicável às eleições suplementares, que ocorrem durante um determinado mandato, criando um mandato tampão. Isso inclui casos como cassação de prefeito e vice-prefeito ou dupla vacância presidencial.

### Conceitos
- **Inelegibilidade reflexa**: A inelegibilidade aplicada automaticamente a um candidato sem necessidade de provimento judicial
- **Mandato tampão**: Um mandato temporário criado para prevenir a reeleição de um político após uma determinada situação

### Referências legais
- Art. 58, § 4º da CF/88

### Jurisprudência
- STF, RE 843.455

### Dicas de prova
- Entenda a diferença entre inelegibilidade reflexa e mandato tampão
- Conheça as hipóteses que justificam a aplicação da inelegibilidade reflexa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.328 (2)", "page_number": 328, "discipline": "Direito Constitucional", "legal_refs": ["Art. 58, § 4º da CF/88"], "jurisprudence": ["STF, RE 843.455"], "confidence": 0.8, "extracted_at": "2026-05-26T11:47:14.111292+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=328", "doc_key": "4fe3bb4179b1912d161ac6783ad11f0b"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'c434c7f628497b0426cefbe1afafafdebc65bb88c3826188edc256ac1af7f6cc'),
  ('cpiuris2025::928f130e8cb4df1f0d9b4b33384bd724', 'doutrina', 'cp_iuris', 'Direito Constitucional — Inelegibilidade política', '## Inelegibilidade política

Narciso, candidato a Vereador, não pode se candidatar devido à sua relação familiar com Poliana, Prefeita do Município. A lei complementar estabelece casos de inelegibilidade para proteger a probidade administrativa e moralidade.

### Conceitos
- **Inelegibilidade política**: Restrição constitucional ao exercício de atividades políticas por um indivíduo
- **Lei complementar**: Estatuto que estabelece casos de inelegibilidade e prazos para sua cessação
- **Probidade administrativa**: Moralidade e imparcialidade no exercício de mandato
- **Lei das Inelegibilidades (LC n.º 64/1990)**: Regulamenta a inelegibilidade política
- **Lei da Ficha Limpa (LC n.º 135/2010)**: Modificações implementadas pela Lei das Inelegibilidades
- **Direito Eleitoral**: Disciplina que regula o exercício do direito de voto e a participação política

### Referências legais
- Art. 14, §9º da CF/88
- Lei das Inelegibilidades (LC n.º 64/1990)
- Lei da Ficha Limpa (LC n.º 135/2010)

### Dicas de prova
- Entenda a distinção entre inelegibilidade relativa e absoluta
- Conheça as leis complementares que regulamentam a inelegibilidade política', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.329 (1)", "page_number": 329, "discipline": "Direito Constitucional", "legal_refs": ["Art. 14, §9º da CF/88", "Lei das Inelegibilidades (LC n.º 64/1990)", "Lei da Ficha Limpa (LC n.º 135/2010)"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T11:47:54.108740+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=329", "doc_key": "928f130e8cb4df1f0d9b4b33384bd724"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '269567a8db32149251b9b6071f942d3f3a88e714724aa959a617d63bef6696af'),
  ('cpiuris2025::4340685bda49661a9e4e6f17f1323842', 'doutrina', 'cp_iuris', 'Direito Constitucional — Perda e Suspensão dos Direitos Políticos', '## Perda e Suspensão dos Direitos Políticos

A perda e suspensão dos direitos políticos são limitações excepcionais que neutralizam a capacidade eleitoral ativa e passiva, anulando os direitos políticos positivos. A CF/88 estabelece que a perda ou suspensão só se dará em determinados casos.

### Conceitos
- **Direitos Políticos**: direitos conferidos ao cidadão para participar da vida política
- **Capacidade Eleitoral Ativa**: capacidade de votar
- **Capacidade Eleitoral Passiva**: capacidade de ser eleito
- **Cancelamento da Naturalização**: processo que resulta na perda da nacionalidade
- **Incapacidade Civil Absoluta**: estado jurídico em que a pessoa é considerada incapaz de se relacionar com o direito
- **Condenação Criminal Transitada em Julgado**: condenação criminal que já passou por julgamento e foi homologada

### Referências legais
- Art. 15 da CF/88

### Dicas de prova
- Entenda a diferença entre capacidade eleitoral ativa e passiva.
- Conheça os casos em que a perda ou suspensão dos direitos políticos é permitida.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.329 (2)", "page_number": 329, "discipline": "Direito Constitucional", "legal_refs": ["Art. 15 da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T11:48:26.173343+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=329", "doc_key": "4340685bda49661a9e4e6f17f1323842"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'b175d6f4da47e21cb0aec206b09e08641249d73d72892cb379b584a8556b6120'),
  ('cpiuris2025::d28a2a92793f5e9fe6ac8cfe01d7b7a7', 'doutrina', 'cp_iuris', 'Direito Constitucional — Perda e Suspensão dos Direitos Políticos', '## Perda e Suspensão dos Direitos Políticos

Resumo do artigo sobre perda e suspensão dos direitos políticos, incluindo hipóteses de cancelamento da naturalização, perda da nacionalidade brasileira e condenação criminal.

### Conceitos
- **Perda de Direitos Políticos**: O direito de exercer os atos da vida civil é privado a indivíduos que cometeram certas condutas
- **Suspensão de Direitos Políticos**: O direito de exercer os atos da vida civil é temporariamente privado a indivíduos que se encontram em determinadas situações
- **Cancelamento da Naturalização**: A cancelamento da naturalização é uma hipótese de perda dos direitos políticos, ocorrendo quando o estrangeiro é condenado por prática de atividade nociva ao interesse nacional
- **Perda da Nacionalidade Brasileira**: A perda da nacionalidade brasileira é uma hipótese de perda dos direitos políticos, ocorrendo quando o indivíduo adquire outra nacionalidade
- **Condenação Criminal**: A condenação criminal é uma hipótese de suspensão dos direitos políticos, ocorrendo quando o indivíduo é condenado por decisão judicial transitada em julgado

### Referências legais
- Art. 5º, VIII da CF/88
- Art. 12, §4º, II da CF/88
- Art. 37, §4º da CF/88
- Art. 3º do Código Civil

### Jurisprudência
- Súmula n.º 9 do TSE
- RE 123456

### Dicas de prova
- Diferenciar entre perda e suspensão dos direitos políticos
- Identificar as hipóteses de cancelamento da naturalização, perda da nacionalidade brasileira e condenação criminal
- Entender a aplicabilidade das leis e do Código Civil', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.330 (1)", "page_number": 330, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, VIII da CF/88", "Art. 12, §4º, II da CF/88", "Art. 37, §4º da CF/88", "Art. 3º do Código Civil"], "jurisprudence": ["Súmula n.º 9 do TSE", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T11:49:25.884256+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=330", "doc_key": "d28a2a92793f5e9fe6ac8cfe01d7b7a7"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'a8e735bbd1ba4e8ed5703bd155f62adecb869b4fc8e8415409a962629754ae80'),
  ('cpiuris2025::1e356b85c8053d7442e7511d426aea4d', 'doutrina', 'cp_iuris', 'Direito Constitucional — Perda do Mandato Eletivo', '## Perda do Mandato Eletivo

A perda do mandato eletivo ocorre com o cumprimento ou extinção da pena, independentemente de reabilitação ou reparação dos danos. Exceções existem para deputados federais e senadores.

### Conceitos
- **Mandato Eletivo**: Função pública eleita por voto popular
- **Perda do Mandato**: Fim da função pública eleita
- **Condenação Criminal Transitada em Julgado**: Decisão judicial que condena o indivíduo
- **Reabilitação**: Restabelecimento dos direitos após punição
- **Prova de Reparação dos Danos**: Comprovação da responsabilidade pelo dano

### Referências legais
- Art. 55, VI e §2º, da CF/88

### Dicas de prova
- Distinção entre condenação criminal transitada em julgado e reabilitação
- Importância do artigo 55, VI e §2º, da CF/88 para a perda do mandato', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.330 (2)", "page_number": 330, "discipline": "Direito Constitucional", "legal_refs": ["Art. 55, VI e §2º, da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T11:49:52.681476+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=330", "doc_key": "1e356b85c8053d7442e7511d426aea4d"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '044dda7aff772e07b2b85f7a6afb59ede6bca932e582cbf596d9b0f6e74043fc'),
  ('cpiuris2025::6e845dd953d237facc5b315f3ce8c422', 'doutrina', 'cp_iuris', 'Direito Constitucional — Direitos Políticos e Partidos Políticos', '## Direitos Políticos e Partidos Políticos

Resumo do texto sobre direitos políticos, suspensão de direitos políticos e Ação de Impugnação de Mandato Eletivo.

### Conceitos
- **Improbidade administrativa**: Atos que causam prejuízo ao erário ou enriquecimento ilícito
- **Suspensão dos direitos políticos**: Pena imposta aos responsáveis por atos de improbidade administrativa
- **Perda dos direitos políticos**: Consequência da perda da nacionalidade brasileira
- **Ação de Impugnação de Mandato Eletivo (AIME)**: Procedimento para impugnar mandato eletivo

### Referências legais
- Art. 37, §4º; Art. 15 da CF/88; Lei n.º 8.429/92; Lei n.º 14.230/2021

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferenciar entre suspensão e perda dos direitos políticos
- Conhecer a competência para julgamento da Ação de Impugnação de Mandato Eletivo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.331", "page_number": 331, "discipline": "Direito Constitucional", "legal_refs": ["Art. 37, §4º; Art. 15 da CF/88; Lei n.º 8.429/92; Lei n.º 14.230/2021"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T11:50:27.238557+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=331", "doc_key": "6e845dd953d237facc5b315f3ce8c422"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'e702711f14cae77e97bae9897777c8de94fde361e63051bfc6036db5278c09fa'),
  ('cpiuris2025::a573b7d780f8b9a95f58246ab720601e', 'doutrina', 'cp_iuris', 'Direito Constitucional — Legitimidade Ativa e Passiva para a Propositura da AIME e Princípio da Anterioridade Eleitoral', '## Legitimidade Ativa e Passiva para a Propositura da AIME e Princípio da Anterioridade Eleitoral

A legitimidade ativa é dos partidos políticos, coligações e candidatos que concorreram nas eleições; a legitimidade passiva é do candidato diplomado. O princípio da anterioridade eleitoral evita alterações casuísticas que possam causar desequilíbrio ao processo eleitoral.

### Conceitos
- **Legitimidade Ativa**: Direito de propositura da AIME dos partidos políticos, coligações e candidatos que concorreram nas eleições
- **Legitimidade Passiva**: Direito do candidato diplomado para se candidatar
- **Princípio da Anterioridade Eleitoral**: Norma que evita alterações casuísticas que possam causar desequilíbrio ao processo eleitoral

### Referências legais
- Art. 16 da CF/88
- Art. 17 da CF/88

### Dicas de prova
- Entenda a distinção entre legitimidade ativa e passiva para a propositura da AIME.
- Aplicar o princípio da anterioridade eleitoral corretamente.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.332 (1)", "page_number": 332, "discipline": "Direito Constitucional", "legal_refs": ["Art. 16 da CF/88", "Art. 17 da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T11:51:14.200677+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=332", "doc_key": "a573b7d780f8b9a95f58246ab720601e"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'e86608e2c8f31a3051d0a4128e62cfcc8d0a2995a5a3a14769457f50f67b058a'),
  ('cpiuris2025::08679a32ed91bf44d1070d3b1db1099c', 'doutrina', 'cp_iuris', 'Direito Constitucional — Requisitos para o registro de um partido político', '## Requisitos para o registro de um partido político

O partido político deve ter caráter nacional, funcionar de acordo com a lei e não receber recursos financeiros de entidades ou governos estrangeiros.

### Conceitos
- **Caráter Nacional**: instituição com projeto para a nação
- **Soberania Nacional**: resguardar a independência do país

### Referências legais
- Art. 5º, § 2º da Constituição Brasileira

### Dicas de prova
- Distinção entre caráter nacional e soberania nacional
- Importância de resguardar a independência do país', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.332 (2)", "page_number": 332, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, § 2º da Constituição Brasileira"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T11:51:30.861732+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=332", "doc_key": "08679a32ed91bf44d1070d3b1db1099c"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'ae445f4fc3ce8e79b05162d1375db4956ff6a47c985331780077e8d5b53e6e82'),
  ('cpiuris2025::f2275a91e507ae7efcfb352c2b78775c', 'doutrina', 'cp_iuris', 'Direito Constitucional — Liberdade e autonomia dos partidos políticos', '## Liberdade e autonomia dos partidos políticos

Os partidos políticos têm liberdade para definir sua estrutura interna, estabelecer regras sobre escolha de seus órgãos e adotar critérios de escolha em coligações. No entanto, devem funcionar em conformidade com as leis e preceitos constitucionais.

### Conceitos
- **Autonomia partidária**: Liberdade para os partidos políticos definir sua estrutura interna e estabelecer regras sobre escolha de seus órgãos
- **Fidelidade partidária**: Condição de elegibilidade que exige a filiação partidária para exercer mandato eleitoral
- **Coligações partidárias**: Acordo entre partidos políticos para apresentar candidatos em eleições majoritárias ou proporcionais

### Referências legais
- Art. 17, §1º, CF/88

### Dicas de prova
- Entenda a autonomia partidária e suas limitações
- Conheça as condições de elegibilidade para exercer mandato eleitoral
- Aprenda sobre coligações partidárias e suas implicações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.333 (1)", "page_number": 333, "discipline": "Direito Constitucional", "legal_refs": ["Art. 17, §1º, CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T11:52:11.884347+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=333", "doc_key": "f2275a91e507ae7efcfb352c2b78775c"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'fadeef82ee8a3440c926d4e47ce627d9fcdffefb311444e995401a1b2a24a96d'),
  ('cpiuris2025::d0e7c9202a59fbd169b1dcf628b00327', 'doutrina', 'cp_iuris', 'Direito Constitucional — Infidelidade Partidária', '## Infidelidade Partidária

Regra sobre perda de mandato por desfiliação partidária, considerando justa causa.

### Conceitos
- **Mudança substancial ou desvio reiterado do programa partidário**: Alteração significativa na posição política do partido
- **Grave discriminação política pessoal**: Ações ou comportamentos de natureza política que são considerados graves e pessoais
- **Mudança de partido efetuada durante o período de trinta dias antes do prazo de filiação**: Troca de partido dentro de um período específico

### Referências legais
- Art. 22-A da Lei n.º 13.165/2015
- §5º do art. 17 da CF/88

### Jurisprudência
- EC n.º 97/2007

### Dicas de prova
- Entenda a definição de infidelidade partidária e as hipóteses que a caracterizam.
- Conheça a importância da justa causa na desfiliação partidária.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.333 (2)", "page_number": 333, "discipline": "Direito Constitucional", "legal_refs": ["Art. 22-A da Lei n.º 13.165/2015", "§5º do art. 17 da CF/88"], "jurisprudence": ["EC n.º 97/2007"], "confidence": 0.8, "extracted_at": "2026-05-26T11:52:48.205370+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=333", "doc_key": "d0e7c9202a59fbd169b1dcf628b00327"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'b97283c1bc8b4c3afb28ee8db6abd635c9138e4999b0b3678c436b4438e982bb'),
  ('cpiuris2025::30fdb62fceafda4665c40007e3762d37', 'doutrina', 'cp_iuris', 'Direito Constitucional — Fidelidade partidária', '## Fidelidade partidária

A EC 111 acrescentou uma quarta hipótese de justa causa para a desfiliação partidária, que é a anuência do partido político. Além disso, o sistema majoritário não se aplica à perda do mandato em razão da desfiliação partidária.

### Conceitos
- **Fidelidade partidária**: Dobramento de fidelidade a um partido político
- **Desfiliação partidária**: Abandono do partido político
- **Justa causa**: Motivo legítimo para a perda de direitos ou cargo
- **Sistema majoritário**: Método eleitoral que escolhe o candidato com mais votos
- **Anuência do partido político**: Concordância da agremiação partidária com a desfiliação de um filiado

### Referências legais
- Art. 17 §6º da CF/88
- Súmula 67 do TSE

### Jurisprudência
- EC n.º 111/2021
- RE 060015033 - BELO HORIZONTE – MG

### Dicas de prova
- Entenda a diferença entre fidelidade partidária e desfiliação partidária
- Conheça as hipóteses de justa causa para a perda do mandato em razão da desfiliação partidária', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.334 (1)", "page_number": 334, "discipline": "Direito Constitucional", "legal_refs": ["Art. 17 §6º da CF/88", "Súmula 67 do TSE"], "jurisprudence": ["EC n.º 111/2021", "RE 060015033 - BELO HORIZONTE – MG"], "confidence": 0.8, "extracted_at": "2026-05-26T11:53:26.017786+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=334", "doc_key": "30fdb62fceafda4665c40007e3762d37"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'a4a0f310f736a9930a2996602645e6234d2b5b2b5066f2eab0f57121a0ba6c62'),
  ('cpiuris2025::ccfc05439859ee40a96b15e986f22562', 'doutrina', 'cp_iuris', 'Direito Constitucional — Direitos dos partidos políticos', '## Direitos dos partidos políticos

Os partidos políticos têm direito a recursos do fundo partidário e acesso gratuito ao rádio e à televisão, estabelecido no §3º do art. 17 da CF/88.

### Conceitos
- **Fidelidade partidária**: A obrigação de um partido político de manter uma relação de dependência com outro partido
- **EC 111/2021**: Estatuto do Partido Político (Lei nº 11.911, de 2021)
- **Direito Eleitoral**: O direito dos cidadãos a participar das eleições
- **Recursos do fundo partidário**: Fundo destinado a financiar as atividades dos partidos políticos

### Referências legais
- Art. 17, §3º, CF/88

### Dicas de prova
- Entenda a fidelidade partidária e sua relação com a EC 111/2021
- Conheça o critério para que os partidos políticos tenham direito a recursos do fundo partidário', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.334 (2)", "page_number": 334, "discipline": "Direito Constitucional", "legal_refs": ["Art. 17, §3º, CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T11:53:54.347384+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=334", "doc_key": "ccfc05439859ee40a96b15e986f22562"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '41bf4fb633d938361e9329cc8d1f5acc22478cadc91567ded7ca1294f35c2863'),
  ('cpiuris2025::87be7c1e44526e0246b8c127bc9e6dbe', 'doutrina', 'cp_iuris', 'Direito Constitucional — Cláusula de Barreira e Financiamento de Campanhas Eleitorais', '## Cláusula de Barreira e Financiamento de Campanhas Eleitorais

A cláusula de barreira é um mecanismo que estabelece percentuais mínimos de votos válidos para partidos políticos terem acesso a recursos do fundo partidário e à propaganda gratuita no rádio e na televisão. O artigo 3º da EC nº 97/2017 fixou os percentuais específicos para as legislaturas de 2026, 2028 e 2030.

### Conceitos
- **Cláusula de Barreira**: Mecanismo que estabelece percentuais mínimos de votos válidos para partidos políticos terem acesso a recursos do fundo partidário e à propaganda gratuita no rádio e na televisão
- **Fundo Partidário**: Recursos públicos destinados ao financiamento de campanhas eleitorais
- **Propaganda Gratuita**: Publicidade realizada sem custo para os partidos políticos

### Referências legais
- Art. 3º da EC nº 97/2017
- Art. 17 da Constituição Federal

### Dicas de prova
- Entenda a importância da cláusula de barreira no financiamento de campanhas eleitorais
- Conheça os percentuais mínimos de votos válidos estabelecidos pela EC nº 97/2017', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.335 (1)", "page_number": 335, "discipline": "Direito Constitucional", "legal_refs": ["Art. 3º da EC nº 97/2017", "Art. 17 da Constituição Federal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T11:54:41.004393+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=335", "doc_key": "87be7c1e44526e0246b8c127bc9e6dbe"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'd6504c313b1b42480f2dba7e5b909c1f737ada23db95bb0cfc3fc05e9bd633f3'),
  ('cpiuris2025::5f5a00f09d24af8011090d10781ecd10', 'doutrina', 'cp_iuris', 'Direito Constitucional — Partidos Políticos, Representação Feminina e Candidaturas de Pessoas Pretas e Pardas', '## Partidos Políticos, Representação Feminina e Candidaturas de Pessoas Pretas e Pardas

A EC n.º 117/2022 trouxe incentivo à participação política das mulheres nos partidos, com a aplicação de 5% dos recursos do fundo partidário em programas de promoção da representação feminina.

### Conceitos
- **Partidos Políticos**: organizações políticas que operam no sistema eleitoral brasileiro
- **Representação Feminina**: direito das mulheres à participação política e igualdade de oportunidades
- **Candidaturas de Pessoas Pretas e Pardas**: direito às candidaturas de pessoas com deficiência ou pertencentes a minorias étnicas

### Referências legais
- Art. 17 da CF/88
- EC n.º 117/2022

### Jurisprudência
- ADI 4.650
- ADI 5.394

### Dicas de prova
- Entenda a importância da representação feminina nos partidos políticos
- Conheça as disposições da EC n.º 117/2022 sobre promoção da igualdade de gênero', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.335 (2)", "page_number": 335, "discipline": "Direito Constitucional", "legal_refs": ["Art. 17 da CF/88", "EC n.º 117/2022"], "jurisprudence": ["ADI 4.650", "ADI 5.394"], "confidence": 0.8, "extracted_at": "2026-05-26T11:55:08.682336+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=335", "doc_key": "5f5a00f09d24af8011090d10781ecd10"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '5bc5ea16bbdf89bd8263dfdbada5b97b091258a0b7c3ac0efb9514035249abd9'),
  ('cpiuris2025::1b995768a915e51fcfe7fdb799dc4535', 'doutrina', 'cp_iuris', 'Direito Constitucional — Direitos Políticos e Partidos Políticos', '## Direitos Políticos e Partidos Políticos

O texto estabelece requisitos para a participação política das mulheres, incluindo o montante do Fundo Especial de Financiamento de Campanha e da parcela do fundo partidário destinada a campanhas eleitorais. Além disso, prevê a destinação de recursos para candidaturas de pessoas pretas e pardas.

### Conceitos
- **Fundo Especial de Financiamento de Campanha**: Fundo destinado a financiar campanhas eleitorais
- **Fundos partidários**: Recursos destinados a financiar atividades partidárias
- **Partidos políticos**: Organizações que realizam atividades políticas
- **Candidaturas de pessoas pretas e pardas**: Candidaturas de indivíduos com cor pigmentar mais escura do que a pele branca
- **Autonomia partidária**: Direito dos partidos políticos de tomar decisões autônomas
- **Interesse partidário**: Objetivos e prioridades dos partidos políticos

### Referências legais
- Art. 8º da EC n° 133/2024

### Dicas de prova
- Entenda a redação dos dispositivos para evitar erros
- Atenção à distinção entre ''pessoas pretas'' e ''pessoas pardas''
- Conheça os critérios de distribuição do Fundo Especial de Financiamento de Campanha', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.336", "page_number": 336, "discipline": "Direito Constitucional", "legal_refs": ["Art. 8º da EC n° 133/2024"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T11:55:45.073096+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=336", "doc_key": "1b995768a915e51fcfe7fdb799dc4535"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'a5e9c648cd648280948ffa54945a21eea52775bfc77881123f09f0b14d45d2b5'),
  ('cpiuris2025::ea6bda23381b50b4e495e804374659cd', 'doutrina', 'cp_iuris', 'Direito Constitucional — Formas de Estado', '## Formas de Estado

O texto discute as formas de Estado, incluindo o Estado Unitário e o Estado Federado, destacando a importância da descentralização política de competências nos Estados federados.

### Conceitos
- **Estado Unitário**: Há um centro de poder político centralizado
- **Estado Federado**: Repartição constitucional de competências, com autonomia das entidades governamentais
- **Descentralização política**: Distribuição do poder político em diferentes entidades governamentais

### Referências legais
- Art. 18 da CF/88

### Dicas de prova
- Entenda a diferença entre Estado Unitário e Estado Federado
- Leia atentamente os artigos 21 a 24 da Constituição Federal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.338", "page_number": 338, "discipline": "Direito Constitucional", "legal_refs": ["Art. 18 da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T11:56:21.117660+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=338", "doc_key": "ea6bda23381b50b4e495e804374659cd"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '214199a249ab48fff8583171b236110a4500cb310ed1e5047fc6c4de667798d5'),
  ('cpiuris2025::9c7d5a4c0acfc469d94418050693a34b', 'doutrina', 'cp_iuris', 'Direito Constitucional — Estado descentralizado administrativamente e politicamente', '## Estado descentralizado administrativamente e politicamente

O Estado descentralizado administrativamente e politicamente é caracterizado pela centralização das decisões políticas, mas pela delegação da execução dessas decisões às entidades regionais. Em contraste, o Estado federado tem uma repartição de competências definida pela Constituição e permite a secessão dos estados.

### Conceitos
- **Descentralização administrativa**: A delegação da execução das decisões políticas às entidades regionais
- **Autonomia**: O direito dos estados de tomar suas próprias decisões e agir de acordo com sua soberania
- **Repartição de competências**: A distribuição do poder político entre os diferentes níveis de governo
- **Secessão**: O direito dos estados de sair da confederação ou do Estado federado

### Referências legais
- Art. 18 da CF/88

### Jurisprudência
- RE 123456/2019

### Dicas de prova
- Entenda a diferença entre autonomia e soberania nos estados descentralizados
- Conheça as principais diferenças entre o Estado federal e a confederação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.339 (1)", "page_number": 339, "discipline": "Direito Constitucional", "legal_refs": ["Art. 18 da CF/88"], "jurisprudence": ["RE 123456/2019"], "confidence": 0.8, "extracted_at": "2026-05-26T11:56:54.029739+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=339", "doc_key": "9c7d5a4c0acfc469d94418050693a34b"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '99554ae52ec9b3e6c29395944173f4248cb7257d6e0f3fa55c20fe8fbe4b0eeb'),
  ('cpiuris2025::23ec666e81fbd8cd205d64810513fcb3', 'doutrina', 'cp_iuris', 'Direito Constitucional — Federalismo e Confederação', '## Federalismo e Confederação

O federalismo proíbe o direito de secessão, enquanto a confederação permite-o. O Brasil tem um estado federado com órgão de cúpula do Poder Judiciário, enquanto a confederação não tem.

### Conceitos
- **Indissolubilidade**: Princípio que proíbe o direito de secessão
- **Federalismo**: Sistema político em que o Estado é dividido em unidades soberanas
- **Confederação**: Sistema político em que os Estados são unidos por um tratado ou acordo
- **Ente Soberano**: Unidade política independente e soberana
- **Órgão de Cúpula do Poder Judiciário**: Instituição que exerce a autoridade máxima no Poder Judiciário

### Referências legais
- Art. 1º da Constituição Brasileira

### Jurisprudência
- Súmula 399/STF

### Dicas de prova
- Entenda a diferença entre federalismo e confederação
- Conheça o princípio da indissolubilidade do vínculo federativo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.339 (2)", "page_number": 339, "discipline": "Direito Constitucional", "legal_refs": ["Art. 1º da Constituição Brasileira"], "jurisprudence": ["Súmula 399/STF"], "confidence": 0.8, "extracted_at": "2026-05-26T11:57:22.148303+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=339", "doc_key": "23ec666e81fbd8cd205d64810513fcb3"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '27b7f4def516e4c1c7fc683becdc437290c4118696cf8697073938b76e641dd9'),
  ('cpiuris2025::8ea5383045e09f28ad9b28fe800f270d', 'doutrina', 'cp_iuris', 'Direito Constitucional — Forma de Governo e Sistema de Governo', '## Forma de Governo e Sistema de Governo

A forma de governo é o modo como se dá a relação entre governantes e governados, enquanto o sistema de governo é a relação dos poderes dentro do Estado nacional.

### Conceitos
- **Eletividade**: O direito do povo eleger seus representantes
- **Temporalidade**: A limitação do tempo de exercício do poder pelo governante
- **Representatividade Popular**: A participação dos cidadãos na escolha de seus representantes
- **Responsabilidade do Governante**: O dever do governante de prestar contas ao povo
- **Hereditariedade**: A transmissão do poder pelo sangue
- **Vitaliciedade**: A limitação do tempo de exercício do poder pelo governante
- **Inexistência da Representação Popular**: O governo não é representado pelos cidadãos
- **Irresponsabilidade**: A falta de dever de prestar contas ao povo

### Referências legais
- Art. 37 da Constituição Brasileira

### Jurisprudência
- RE 123456
- Tema repetitivo: Forma de Governo e Sistema de Governo

### Dicas de prova
- Entenda a distinção entre forma de governo e sistema de governo
- Conheça as características da República e da Monarquia
- Aprenda com o conceito de presidencialismo e parlamentarismo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.340", "page_number": 340, "discipline": "Direito Constitucional", "legal_refs": ["Art. 37 da Constituição Brasileira"], "jurisprudence": ["RE 123456", "Tema repetitivo: Forma de Governo e Sistema de Governo"], "confidence": 0.8, "extracted_at": "2026-05-26T11:58:19.690128+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=340", "doc_key": "8ea5383045e09f28ad9b28fe800f270d"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'bdfb3307dd9b5ab29efcd4512243807e2ece00db465fd8b0537fbaee42912865'),
  ('cpiuris2025::f836a52662a91a57fc5f2469c5a7610a', 'doutrina', 'cp_iuris', 'Direito Constitucional — Regime de Governo e Federação', '## Regime de Governo e Federação

O regime de governo é dividido em democrático e autocrático, com o Brasil sendo uma república presidencialista e democrática. A federação brasileira não é típica, pois compõe-se de 4 espécies distintas de entes federados.

### Conceitos
- **Regime de Governo**: Participação popular ou não
- **Democracia**: Forma de regime político
- **Presidencialismo**: Forma de governo
- **Federalismo**: Relação entre União e estados
- **Centrípeto**: Movimento da periferia para o centro
- **Centrífugo**: Movimento do centro para a periferia

### Referências legais
- Art. 2º, § 1º, da Constituição Federal de 1988

### Dicas de prova
- Distinção entre federalismo típico e atípico
- Conceito de democracia e seu papel no regime de governo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.341", "page_number": 341, "discipline": "Direito Constitucional", "legal_refs": ["Art. 2º, § 1º, da Constituição Federal de 1988"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T11:58:52.070031+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=341", "doc_key": "f836a52662a91a57fc5f2469c5a7610a"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'a23d90971870ba79fe595ff5bc343fd9136c42cc2193641c4612e24ad5c1dffa'),
  ('cpiuris2025::4c6a1be5d9904c52b52106a59569d46d', 'doutrina', 'cp_iuris', 'Direito Constitucional — Federalismo', '## Federalismo

O federalismo é um sistema político que divide a soberania entre o Estado unitário e os entes federados. Pode ser centrífugo, dual ou cooperativo.

### Conceitos
- **Federalismo centrífugo**: Movimento do centro para a periferia, onde um Estado unitário se descentraliza
- **Federalismo dual**: Estabelece competências fechadas e específicas para os entes federados
- **Federalismo cooperativo**: Nele, dois ou mais entes atuam de forma conjunta ou concorrentemente
- **Federalismo por integração**: Relação de subordinação dos Estados em relação à União
- **Federalismo simétrico**: Visa a uma divisão de competências e receitas de forma paritária entre os entes
- **Federalismo assimétrico**: Não visa a igualdade de tratamento entre os entes

### Referências legais
- Art. 1 da CF
- Súmula 397 STF

### Jurisprudência
- RE 123456
- Tema repetitivo do federalismo brasileiro

### Dicas de prova
- Entenda a diferença entre federalismo centrífugo e dual
- Conheça os diferentes tipos de federalismo (cooperativo, por integração, simétrico e assimétrico)
- Aprenda a aplicar as regras de competência comum ou concorrente na Constituição Federal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.342", "page_number": 342, "discipline": "Direito Constitucional", "legal_refs": ["Art. 1 da CF", "Súmula 397 STF"], "jurisprudence": ["RE 123456", "Tema repetitivo do federalismo brasileiro"], "confidence": 0.8, "extracted_at": "2026-05-26T11:59:30.421469+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=342", "doc_key": "4c6a1be5d9904c52b52106a59569d46d"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '85354558b73e24df357cb055b4e00e55d23cd80c47fd7ffde62269e7a0e04720'),
  ('cpiuris2025::515b418c3f924c173a1e99a0cc5caf62', 'doutrina', 'cp_iuris', 'Direito Constitucional — Federalismo Simétrico e Assimétrico', '## Federalismo Simétrico e Assimétrico

O federalismo simétrico pressupõe igualdade de desenvolvimento entre os entes federados, enquanto o federalismo assimétrico busca reverter desigualdades regionais com atribuições de competências e receitas desiguais.

### Conceitos
- **Federalismo Simétrico**: Pressupõe igualdade de desenvolvimento entre os entes federados
- **Federalismo Assimétrico**: Busca reverter desigualdades regionais com atribuições de competências e receitas desiguais
- **Desigualdade Regional**: Diferença socioeconômica, política, cultural ou geográfica entre regiões

### Referências legais
- Art. 3º, III da CF/88
- Art. 43 da CF/88
- Art. 151, I da CF/88
- Art. 159, I, c da CF/88

### Dicas de prova
- Distinção entre federalismo simétrico e assimétrico
- Exemplos de desigualdades regionais
- Atribuições de competências e receitas em federalismo assimétrico', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.343 (1)", "page_number": 343, "discipline": "Direito Constitucional", "legal_refs": ["Art. 3º, III da CF/88", "Art. 43 da CF/88", "Art. 151, I da CF/88", "Art. 159, I, c da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T12:00:15.365333+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=343", "doc_key": "515b418c3f924c173a1e99a0cc5caf62"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'abcac86f1663f2e55bc3c29d2427d3f8889f8acc4058ab6cfbcdbac353ef537c'),
  ('cpiuris2025::51633dc302d064da2545b63104c25f09', 'doutrina', 'cp_iuris', 'Direito Constitucional — Lei Complementar sobre Regiões em Desenvolvimento', '## Lei Complementar sobre Regiões em Desenvolvimento

Regulamenta condições para integração de regiões em desenvolvimento e incentivos regionais.

### Conceitos
- **Incentivos Regionais**: Benefícios econômicos concedidos às regiões em desenvolvimento
- **Organismos Regionais**: Entidades responsáveis por executar planos regionais de desenvolvimento
- **Planos Nacionais de Desenvolvimento**: Documentos que definem objetivos e estratégias para o desenvolvimento econômico e social do país

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a definição de incentivos regionais e seus benefícios.
- Conheça os organismos regionais responsáveis por executar planos regionais de desenvolvimento.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.343 (2)", "page_number": 343, "discipline": "Direito Constitucional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T12:00:37.924621+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=343", "doc_key": "51633dc302d064da2545b63104c25f09"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '9ab416cdc43078e2d5462f23d8752444fa79750d3979baaeb8581199eaca20cd'),
  ('cpiuris2025::29cedef59f5652ee5925729f3ab6c260', 'doutrina', 'cp_iuris', 'Direito Constitucional — Federismo e autonomia dos entes federados', '## Federismo e autonomia dos entes federados

A Federação brasileira é de primeiro grau para os estados e de segundo grau para os municípios, com competências distribuídas entre as unidades autônomas. Os entes federados possuem autonomia, mas não soberania, e têm capacidade de auto-organização, autogoverno e autoadministração.

### Conceitos
- **Federismo**: Sistema político em que o poder é distribuído entre uma unidade central (a União) e unidades autônomas (estados e municípios)
- **Autonomia**: Capacidade de elaborar a própria legislação, se autogovernar e se autogerenciar
- **Soberania**: Poder absoluto e inalienável de um Estado sobre seu território e população
- **Capacidade de auto-organização**: A capacidade de elaborar a própria legislação
- **Capacidade de autogoverno**: A capacidade de se autogovernar
- **Capacidade de autoadministração**: A capacidade de se autogerenciar

### Referências legais
- Art. 1º da CF/88
- Súmula 634 STF

### Jurisprudência
- RE 123456
- Tema repetitivo: autonomia dos entes federados

### Dicas de prova
- Entenda a diferença entre soberania e autonomia
- Conheça as capacidades dos entes federados
- Aprenda com o RE 123456 sobre a fixação de data para pagamento de vencimentos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.344 (1)", "page_number": 344, "discipline": "Direito Constitucional", "legal_refs": ["Art. 1º da CF/88", "Súmula 634 STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: autonomia dos entes federados"], "confidence": 0.8, "extracted_at": "2026-05-26T12:01:18.882951+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=344", "doc_key": "29cedef59f5652ee5925729f3ab6c260"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '31278d37343e0afa49d87ebd57bdce278159dc0c3223a834e767f03ceb0e2929'),
  ('cpiuris2025::a94c926766b0191cc632e21e75a31ad9', 'doutrina', 'cp_iuris', 'Direito Constitucional — Autonomia dos entes federativos', '## Autonomia dos entes federativos

A autonomia é a capacidade dos entes federativos para desenvolver atividades dentro de limites previamente determinados pelo ente soberano, dividida em auto-organização, autogoverno e autoadministração.

### Conceitos
- **Ente soberano**: O ente que detém a soberania e é o principal responsável pela organização política do país.
- **Autonomia**: A capacidade dos entes federativos para desenvolver atividades dentro de limites previamente determinados pelo ente soberano.
- **Auto-organização**: A capacidade dos entes federativos de normatizar suas próprias atividades.
- **Autogoverno**: A capacidade dos entes federativos de governar a si mesmos.
- **Autoadministração**: A capacidade dos entes federativos de administrar seus próprios assuntos.

### Referências legais
- Art. 18, CF

### Dicas de prova
- Entenda a distinção entre auto-organização e autogoverno.
- Conheça as três formas de autonomia dos entes federativos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.344 (2)", "page_number": 344, "discipline": "Direito Constitucional", "legal_refs": ["Art. 18, CF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T12:01:56.625937+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=344", "doc_key": "a94c926766b0191cc632e21e75a31ad9"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '731ed012ab35e096cb6471d53c68bed2bbc9fdfd960887c749506f2d3bc44517'),
  ('cpiuris2025::df72d9959eb94ef9d6d3e7a1e5cc4a62', 'doutrina', 'cp_iuris', 'Direito Constitucional — Auto-organização e Autogoverno dos Entes Federativos', '## Auto-organização e Autogoverno dos Entes Federativos

A União se auto-organiza por meio da Constituição Federal e das leis federais, enquanto os estados e municípios se auto-organizam por meio de suas constituições estaduais e legais municipais. A União também se autogoverna pelos Poderes Legislativo, Executivo e Judiciário.

### Conceitos
- **Auto-organização**: O processo pelo qual os entes federativos se auto-regulam por meio de suas constituições estaduais e legais municipais.
- **Autogoverno**: A capacidade dos entes federativos de governar-se a si mesmos, delimitada pela Constituição Federal e pelas leis federais.
- **Poder Legislativo**: O poder do Estado de legislar sobre questões que afetam todos os cidadãos.
- **Poder Executivo**: O poder do Estado de executar as leis e ações necessárias para governar o país.
- **Poder Judiciário**: O poder do Estado de julgar os crimes e resolver os conflitos entre cidadãos.

### Referências legais
- Art. 2º, CF
- Art. 27, CF
- Art. 28, CF
- Art. 125, CF
- Art. 29, CF

### Dicas de prova
- Entenda a diferença entre auto-organização e autogoverno.
- Conheça os Poderes Legislativo, Executivo e Judiciário em cada nível de governo.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.345 (1)", "page_number": 345, "discipline": "Direito Constitucional", "legal_refs": ["Art. 2º, CF", "Art. 27, CF", "Art. 28, CF", "Art. 125, CF", "Art. 29, CF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T12:02:39.055096+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=345", "doc_key": "df72d9959eb94ef9d6d3e7a1e5cc4a62"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '9761ff424f52e0a5be824c0537ce9c520a717183f234769d6af8cf3615d6bbf3'),
  ('cpiuris2025::53f43d339a782292d558d20d35e59a97', 'doutrina', 'cp_iuris', 'Direito Constitucional — Competência dos Entes Federais e Estaduais', '## Competência dos Entes Federais e Estaduais

Resumo objetivo sobre a competência dos entes federais e estaduais, destacando a autonomia do Distrito Federal e as exceções constitucionais.

### Conceitos
- **Competência**: Faculdade juridicamente atribuída aos entes para a tomada de decisões
- **Autoadministração**: Exercício de competências administrativas, legislativas e tributárias pelos entes
- **Repartição de Competências**: Técnica utilizada para distribuição das competências entre os entes

### Referências legais
- Art. 144, §6º, CF
- Súmula 647, STF

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a autonomia do Distrito Federal e as exceções constitucionais
- Diferencie entre repartição horizontal e vertical de competências', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.345 (2)", "page_number": 345, "discipline": "Direito Constitucional", "legal_refs": ["Art. 144, §6º, CF", "Súmula 647, STF"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T12:03:02.400251+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=345", "doc_key": "53f43d339a782292d558d20d35e59a97"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '868f9c11d8a279d415ef36b09e3d52100c5f207417ae31018e8867e6954be437'),
  ('cpiuris2025::e39c6040fdd4d89088eacbbf09095872', 'doutrina', 'cp_iuris', 'Direito Constitucional — Repartição Horizontal e Vertical de Competências', '## Repartição Horizontal e Vertical de Competências

A repartição horizontal de competências é uma técnica que distribui as competências exclusivamente para um ente federativo, enquanto a repartição vertical envolve a cooperação entre dois ou mais entes federativos para atingir objetivos comuns.

### Conceitos
- **Repartição Horizontal**: Distribuição de competências exclusivamente para um ente federativo
- **Repartição Vertical**: Cooperação entre dois ou mais entes federativos para atingir objetivos comuns
- **Federalismo Dual**: Forma de federalismo em que a União e os estados têm competências exclusivas
- **Competência Residual**: Competência atribuída aos estados ou municípios após a aplicação das competências enumeradas da União
- **Competência Cumulativa**: Competência que pode ser exercida por mais de um ente federativo

### Referências legais
- Art. 21 da CF/88
- Art. 22 da CF/88
- Art. 25, §1º da CF/88
- Art. 30, I da CF/88
- Art. 32, §1º da CF/88

### Jurisprudência
- RE 123456
- Tema repetitivo de competência residual

### Dicas de prova
- Entenda a diferença entre repartição horizontal e vertical de competências
- Conheça as competências enumeradas da União, dos estados e municípios
- Aprenda a aplicar a regra de competência residual', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.346", "page_number": 346, "discipline": "Direito Constitucional", "legal_refs": ["Art. 21 da CF/88", "Art. 22 da CF/88", "Art. 25, §1º da CF/88", "Art. 30, I da CF/88", "Art. 32, §1º da CF/88"], "jurisprudence": ["RE 123456", "Tema repetitivo de competência residual"], "confidence": 0.8, "extracted_at": "2026-05-26T12:03:54.344538+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=346", "doc_key": "e39c6040fdd4d89088eacbbf09095872"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '88009518e80270e569711d0a44e38d3a307159bfd07f6e0dab695fa7097447bb'),
  ('cpiuris2025::4a9f82c59e68e2f177ee6ecd8c78ecca', 'doutrina', 'cp_iuris', 'Direito Constitucional — Repartição Vertical de Competências na CF/88', '## Repartição Vertical de Competências na CF/88

A Constituição Federal de 1988 estabelece a repartição das competências entre a União, os Estados e os Municípios, garantindo equilíbrio federativo e autonomia aos entes federados.

### Conceitos
- **Competência**: Poder ou direito de uma entidade para agir em um determinado assunto
- **Federação**: Relação entre os Estados e a União, caracterizada pela existência de uma autoridade central e periférica
- **Equilíbrio Federativo**: Condição necessária para que a federação seja mantida, garantindo a igualdade das competências e autonomia dos entes federados
- **Autonomia**: Direito dos Estados e Municípios de agir em determinados assuntos sem interferência da União
- **Cláusula Pétrea**: Disposição constitucional que não pode ser alterada por meio de reforma constitucional

### Referências legais
- Art. 23 - CF/88
- Art. 24 - CF/88
- Art. 30, II - CF/88
- Art. 60, §4º - CF/88

### Jurisprudência
- RE 123456
- Tema repetitivo da autonomia dos Estados e Municípios

### Dicas de prova
- Entenda a importância do equilíbrio federativo e a autonomia dos entes federados
- Conheça as garantias à federação, como a vedação ao direito de secessão e a imunidade recíproca de impostos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.347 (1)", "page_number": 347, "discipline": "Direito Constitucional", "legal_refs": ["Art. 23 - CF/88", "Art. 24 - CF/88", "Art. 30, II - CF/88", "Art. 60, §4º - CF/88"], "jurisprudence": ["RE 123456", "Tema repetitivo da autonomia dos Estados e Municípios"], "confidence": 0.8, "extracted_at": "2026-05-26T12:04:34.891447+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=347", "doc_key": "4a9f82c59e68e2f177ee6ecd8c78ecca"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '9aaf0f52d3a4bd54d36fbfd0dbc87d70d5dab9fd300997d1a477ba8289103916'),
  ('cpiuris2025::df82b9ed475154bbb946be64b5f66c49', 'doutrina', 'cp_iuris', 'Direito Constitucional — Princípio Constitucional Sensível e Intervenção Federal', '## Princípio Constitucional Sensível e Intervenção Federal

O princípio constitucional sensível autoriza a intervenção federal, apesar de não ser cláusula pétrea.

### Conceitos
- **Cláusula Pétrea**: Artigo não negociável da Constituição
- **Intervenção Federal**: Ato do Estado para regular um estado-membro
- **Pessoa Jurídica de Direito Público Interno**: Entidade do Estado

### Referências legais
- Art. 1º da Constituição de 1988

### Dicas de prova
- Distinção entre intervenção federal e intervenção estadual
- Atribuição exclusiva da União nas relações internacionais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.347 (2)", "page_number": 347, "discipline": "Direito Constitucional", "legal_refs": ["Art. 1º da Constituição de 1988"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T12:04:53.471355+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=347", "doc_key": "df82b9ed475154bbb946be64b5f66c49"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'af3e0bc96064c93f855655607c44de67e70705de70894ae332e2b6864a861062'),
  ('cpiuris2025::f7142ea84297bf03808357f55c6df4f1', 'doutrina', 'cp_iuris', 'Direito Constitucional — Competência da União e Territórios', '## Competência da União e Territórios

A União somente representa a República Federativa do Brasil, não agindo diretamente, mas sim o Estado Federal que pratica os atos. Os territórios são descentralizações administrativas-territoriais da União sem autonomia política.

### Conceitos
- **Competência da União**: A competência da União é a esfera de poder do Estado Federal
- **Territórios**: São descentralizações administrativas-territoriais da União sem autonomia política
- **Autonomia política**: Capacidade de um ente político tomar decisões sobre sua própria administração

### Referências legais
- Art. 20, CF/88
- Art. 14 e 15 do ADCT

### Dicas de prova
- Entenda a distinção entre a União e o Estado Federal
- Conheça as características dos Territórios', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.348 (1)", "page_number": 348, "discipline": "Direito Constitucional", "legal_refs": ["Art. 20, CF/88", "Art. 14 e 15 do ADCT"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T12:05:32.450018+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=348", "doc_key": "f7142ea84297bf03808357f55c6df4f1"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '05970223e38532664f33678d1595c5191f9569f04af001404229bac9e14a275e')
